var ET_QUESTIONS=[{id:"et_001",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1nta corriente fluye por un elemento de calefacci\xF3n de 4800W conectado a una fuente de 240V?",opciones:["10 Amperios","15 Amperios","20 Amperios","40 Amperios"],respuesta_correcta:2,explicacion:"Usando la Ley de Watt (I = P / V), tenemos 4800W / 240V = 20A."},{id:"et_002",categoria:"ET_OHM_WATT",pregunta:"Si se duplica el voltaje en un circuito con una resistencia constante, \xBFqu\xE9 sucede con la potencia (Watts)?",opciones:["La potencia se reduce a la mitad","La potencia permanece igual","La potencia se duplica exactamente","La potencia se cuadruplica (4x)"],respuesta_correcta:3,explicacion:"Seg\xFAn la f\xF3rmula P = V\xB2 / R, si el voltaje sube al doble, la potencia aumenta al cuadrado de ese cambio (2\xB2 = 4)."},{id:"et_003",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la resistencia total de dos motores de condensadora de 12 Ohmios conectados en paralelo?",opciones:["24 Ohmios","12 Ohmios","6 Ohmios","4 Ohmios"],respuesta_correcta:2,explicacion:"Para resistencias iguales en paralelo, dividimos el valor por la cantidad (12 / 2 = 6 Ohmios)."},{id:"et_004",categoria:"ET_OHM_WATT",pregunta:"\xBFQu\xE9 ca\xEDda de voltaje ocurre en un conductor que tiene 0.5 Ohmios de resistencia y transporta 16A?",opciones:["4 Voltios","8 Voltios","16 Voltios","32 Voltios"],respuesta_correcta:1,explicacion:"Ley de Ohm b\xE1sica: V = I * R. Entonces, 16A * 0.5\u03A9 = 8V."},{id:"et_005",categoria:"ET_OHM_WATT",pregunta:"Un circuito de control de 24V tiene un solenoide con una resistencia de 48 Ohmios. \xBFCu\xE1l es la intensidad?",opciones:["0.5 Amperios","2.0 Amperios","1.15 Amperios","4.8 Amperios"],respuesta_correcta:0,explicacion:"I = V / R. Calculamos 24V / 48\u03A9 = 0.5A."},{id:"et_006",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el art\xEDculo del NEC que define los t\xE9rminos utilizados en todo el c\xF3digo el\xE9ctrico?",opciones:["Art\xEDculo 90","Art\xEDculo 100","Art\xEDculo 110","Art\xEDculo 200"],respuesta_correcta:1,explicacion:"El Art\xEDculo 100 del NEC contiene las definiciones esenciales para la aplicaci\xF3n correcta del c\xF3digo."},{id:"et_007",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 cap\xEDtulo del NEC cubre espec\xEDficamente los equipos de uso especial como HVAC y refrigeraci\xF3n?",opciones:["Cap\xEDtulo 2","Cap\xEDtulo 4","Cap\xEDtulo 5","Cap\xEDtulo 8"],respuesta_correcta:1,explicacion:"El Cap\xEDtulo 4 (Equipment for General Use) incluye el Art\xEDculo 440, espec\xEDfico para equipos de aire acondicionado y refrigeraci\xF3n."},{id:"et_008",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa que un equipo est\xE9 'Listed' (Listado) seg\xFAn el Art\xEDculo 100 del NEC?",opciones:["Que aparece en el inventario de materiales de la obra actual","Que ha sido evaluado y aprobado por una organizaci\xF3n como UL o ETL","Que el fabricante ha garantizado que el equipo funciona correctamente","Que el inspector de la ciudad ha firmado la etiqueta de instalaci\xF3n"],respuesta_correcta:1,explicacion:"'Listed' significa que el equipo ha sido probado por un laboratorio de pruebas reconocido (NRTL) para cumplir con est\xE1ndares de seguridad."},{id:"et_009",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el prop\xF3sito principal del NEC seg\xFAn el Art\xEDculo 90.1(A)?",opciones:["Proporcionar una gu\xEDa de dise\xF1o para instalaciones eficientes","Asegurar que los electricistas cobren lo justo por su trabajo","La salvaguardia pr\xE1ctica de las personas y de las propiedades","Establecer los requisitos de capacitaci\xF3n para los t\xE9cnicos ET"],respuesta_correcta:2,explicacion:"El NEC no es un manual de dise\xF1o; su intenci\xF3n es la seguridad contra riesgos derivados del uso de la electricidad."},{id:"et_010",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad m\xE1xima permitida para un conductor 12 AWG THHN en una terminal de 75\xB0C?",opciones:["20 Amperios","25 Amperios","30 Amperios","35 Amperios"],respuesta_correcta:1,explicacion:"Aunque el 12 AWG THHN soporta 30A en la columna de 90\xB0C, la Tabla 310.16 limita a 25A en la columna de 75\xB0C (regla de terminales)."},{id:"et_011",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 factor de ajuste se aplica si hay 4-6 conductores portadores de corriente en una canalizaci\xF3n?",opciones:["100%","90%","80%","70%"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.15(C)(1), de 4 a 6 conductores requieren una reducci\xF3n de ampacidad al 80%."},{id:"et_012",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ca\xEDda de voltaje m\xE1xima recomendada por el NEC para un circuito derivado (branch circuit)?",opciones:["1%","2%","3%","5%"],respuesta_correcta:2,explicacion:"La nota informativa en NEC 210.19 sugiere que la ca\xEDda de voltaje no supere el 3% para un funcionamiento eficiente."},{id:"et_013",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el soporte m\xE1ximo permitido para una tuber\xEDa EMT de 1 pulgada seg\xFAn el NEC?",opciones:["Cada 3 pies","Cada 5 pies","Cada 10 pies","Cada 12 pies"],respuesta_correcta:2,explicacion:"El Art\xEDculo 358.30(A) requiere que el EMT se asegure al menos cada 10 pies y a no m\xE1s de 3 pies de cada caja o accesorio."},{id:"et_014",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1ntos dobleces de 90 grados se permiten como m\xE1ximo entre dos cajas de registro?",opciones:["2 dobleces (180\xB0)","3 dobleces (270\xB0)","4 dobleces (360\xB0)","5 dobleces (450\xB0)"],respuesta_correcta:2,explicacion:"El c\xF3digo proh\xEDbe m\xE1s de 360 grados de dobleces totales (por ejemplo, cuatro de 90\xB0) para evitar da\xF1os al aislamiento del cable al jalarlo."},{id:"et_015",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 tipo de recept\xE1culo es obligatorio en un ba\xF1o residencial seg\xFAn el NEC 210.8?",opciones:["Recept\xE1culo de 20A con protecci\xF3n AFCI \xFAnicamente","Recept\xE1culo con protecci\xF3n GFCI de clase A","Recept\xE1culo est\xE1ndar con tapa de seguridad para ni\xF1os","Recept\xE1culo conectado a un circuito de iluminaci\xF3n compartido"],respuesta_correcta:1,explicacion:"Todos los recept\xE1culos en ba\xF1os deben tener protecci\xF3n GFCI para proteger a las personas contra descargas en \xE1reas h\xFAmedas."},{id:"et_016",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga calculada para un recept\xE1culo d\xFAplex est\xE1ndar en una aplicaci\xF3n comercial?",opciones:["100 VA","150 VA","180 VA","200 VA"],respuesta_correcta:2,explicacion:"En c\xE1lculos de carga comercial, cada recept\xE1culo d\xFAplex se calcula a 180 VA seg\xFAn NEC 220.14(I)."},{id:"et_017",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es la altura m\xEDnima para los conductores de acometida sobre una plataforma residencial?",opciones:["8 pies","10 pies","12 pies","15 pies"],respuesta_correcta:1,explicacion:"NEC 230.24(B) requiere un despeje m\xEDnimo de 10 pies para conductores de acometida sobre \xE1reas peatonales o plataformas."},{id:"et_018",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de un electrodo de varilla (ground rod) de acero galvanizado?",opciones:["1/2 pulgada de di\xE1metro","5/8 pulgada de di\xE1metro","3/4 pulgada de di\xE1metro","1 pulgada de di\xE1metro"],respuesta_correcta:1,explicacion:"El Art\xEDculo 250.52(A)(5) especifica que las varillas de hierro o acero deben tener al menos 5/8' de di\xE1metro."},{id:"et_019",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 porcentaje se debe calcular la carga continua para dimensionar un breaker (OCPD)?",opciones:["80% de la carga","100% de la carga","125% de la carga","150% de la carga"],respuesta_correcta:2,explicacion:"Para cargas continuas (3 horas o m\xE1s), el dispositivo de sobrecorriente debe ser al menos el 125% de la carga."},{id:"et_020",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla del NEC se usa para encontrar la corriente a plena carga (FLC) de un motor trif\xE1sico?",opciones:["Tabla 430.248","Tabla 430.250","Tabla 310.16","Tabla 250.122"],respuesta_correcta:1,explicacion:"La Tabla 430.250 proporciona los valores de corriente para motores de inducci\xF3n trif\xE1sicos de corriente alterna."},{id:"et_021",categoria:"ET_OHM_WATT",pregunta:"\xBFQu\xE9 instrumento se debe conectar en serie con la carga para medir la intensidad de corriente?",opciones:["Volt\xEDmetro","\xD3hmetro","Amper\xEDmetro","Vat\xEDmetro"],respuesta_correcta:2,explicacion:"El amper\xEDmetro debe ser parte del camino del flujo de electrones (serie) para medir cu\xE1ntos pasan por segundo."},{id:"et_022",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 cap\xEDtulo del NEC es independiente y no puede ser modificado por los cap\xEDtulos 1 al 4?",opciones:["Cap\xEDtulo 5","Cap\xEDtulo 6","Cap\xEDtulo 7","Cap\xEDtulo 8"],respuesta_correcta:3,explicacion:"El Cap\xEDtulo 8 (Sistemas de Comunicaci\xF3n) es independiente a menos que se haga referencia espec\xEDfica a otros cap\xEDtulos."},{id:"et_023",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la letra 'W' en un cable tipo THWN?",opciones:["Wattage (Potencia alta)","Weatherproof (A prueba de clima)","Wet (Apto para lugares mojados)","Wire (Alambre s\xF3lido)"],respuesta_correcta:2,explicacion:"La 'W' indica que el aislamiento es resistente a la humedad y puede usarse en lugares mojados o enterrado."},{id:"et_024",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura m\xEDnimo para una tuber\xEDa de PVC de 2 pulgadas?",opciones:["4.5 pulgadas","8.25 pulgadas","9.5 pulgadas","12 pulgadas"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 2 del Cap\xEDtulo 9, el radio m\xEDnimo de curvatura para conduit de 2' es 9.5 pulgadas."},{id:"et_025",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1ntos recept\xE1culos se permiten en un circuito derivado de 20A en una vivienda residencial?",opciones:["10 recept\xE1culos","12 recept\xE1culos","13 recept\xE1culos","Sin l\xEDmite definido"],respuesta_correcta:3,explicacion:"El NEC no limita el n\xFAmero de recept\xE1culos en circuitos de uso general en viviendas, aunque se recomienda un c\xE1lculo basado en el \xE1rea."},{id:"et_026",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es la profundidad m\xEDnima para enterrar un cable tipo USE sin protecci\xF3n mec\xE1nica adicional?",opciones:["12 pulgadas","18 pulgadas","24 pulgadas","36 pulgadas"],respuesta_correcta:2,explicacion:"La Tabla 300.5 requiere una cobertura m\xEDnima de 24 pulgadas para cables de enterramiento directo (Direct Burial)."},{id:"et_027",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 color debe ser obligatoriamente el aislamiento de un conductor de puesta a tierra (EGC)?",opciones:["Blanco o gris natural","Verde o verde con franjas amarillas","Negro con marcas blancas en los extremos","Cualquier color excepto rojo o naranja"],respuesta_correcta:1,explicacion:"El Art\xEDculo 250.119 establece que los conductores de puesta a tierra de equipos deben ser verdes o verdes con franjas."},{id:"et_028",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xE1ximo de breaker para un circuito con cable 14 AWG de cobre (regla general)?",opciones:["15 Amperios","20 Amperios","25 Amperios","30 Amperios"],respuesta_correcta:0,explicacion:"NEC 240.4(D)(3) limita el 14 AWG a una protecci\xF3n de sobrecorriente m\xE1xima de 15A."},{id:"et_029",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se debe dimensionar el conductor de un solo motor?",opciones:["100%","115%","125%","150%"],respuesta_correcta:2,explicacion:"NEC 430.22 requiere que los conductores de un solo motor tengan una ampacidad de al menos el 125% de la corriente de placa."},{id:"et_030",categoria:"ET_TRANSFORMADORES",pregunta:"En un transformador con relaci\xF3n 4:1, si el primario tiene 480V, \xBFcu\xE1l es el voltaje secundario?",opciones:["120 Voltios","240 Voltios","1920 Voltios","208 Voltios"],respuesta_correcta:0,explicacion:"Relaci\xF3n 4:1 significa que el voltaje baja 4 veces. 480 / 4 = 120V."},{id:"et_031",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga de iluminaci\xF3n por pie cuadrado para una unidad de vivienda (residencial)?",opciones:["2 VA por pie cuadrado","3 VA por pie cuadrado","3.5 VA por pie cuadrado","5 VA por pie cuadrado"],respuesta_correcta:1,explicacion:"La Tabla 220.12 especifica 3 VA por pie cuadrado para \xE1reas habitables en residencias."},{id:"et_032",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 clasificaci\xF3n recibe un lugar donde hay gases o vapores inflamables presentes?",opciones:["Clase I","Clase II","Clase III","Clase IV"],respuesta_correcta:0,explicacion:"La Clase I define lugares donde hay gases o vapores inflamables en cantidades suficientes para producir explosiones."},{id:"et_033",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 art\xEDculo del NEC cubre los sistemas de alarma contra incendios?",opciones:["Art\xEDculo 700","Art\xEDculo 725","Art\xEDculo 760","Art\xEDculo 800"],respuesta_correcta:2,explicacion:"El Art\xEDculo 760 cubre espec\xEDficamente la instalaci\xF3n de cableado y equipos para sistemas de alarma de incendio."},{id:"et_034",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es la distancia de la 'Limited Approach Boundary' para un sistema de 480V?",opciones:["1 pie","3 pies 6 pulgadas","10 pies","42 pies"],respuesta_correcta:1,explicacion:"Seg\xFAn NFPA 70E, para 480V (fijo), la frontera de aproximaci\xF3n limitada es de 3 pies 6 pulgadas."},{id:"et_035",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la potencia consumida por una carga que drena 5A a 120V con un factor de potencia de 1.0?",opciones:["24 Watts","60 Watts","120 Watts","600 Watts"],respuesta_correcta:3,explicacion:"P = V * I. Entonces, 120V * 5A = 600W."},{id:"et_036",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es la profundidad de trabajo m\xEDnima frente a un panel de 120/240V?",opciones:["24 pulgadas","30 pulgadas","36 pulgadas (3 pies)","48 pulgadas (4 pies)"],respuesta_correcta:2,explicacion:"La Tabla 110.26(A)(1) requiere un espacio libre de 3 pies para sistemas de hasta 150V a tierra."},{id:"et_037",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 material de conductor requiere una ampacidad mayor para transportar la misma carga que el cobre?",opciones:["Plata","Aluminio","Oro","N\xEDquel"],respuesta_correcta:1,explicacion:"El aluminio tiene mayor resistencia que el cobre, por lo que requiere un calibre mayor para la misma corriente."},{id:"et_038",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 tipo de tuber\xEDa no se permite usar para soporte de luminarias?",opciones:["RMC (R\xEDgido)","IMC (Intermedio)","EMT (El\xE9ctrico Met\xE1lico)","FMC (Flexible)"],respuesta_correcta:3,explicacion:"El conduit flexible (FMC) no tiene la rigidez estructural para soportar peso de luminarias u otros equipos."},{id:"et_039",categoria:"ET_CIRCUITOS",pregunta:"\xBFA qu\xE9 distancia m\xE1xima de una puerta de habitaci\xF3n debe estar el switch de luz?",opciones:["6 pulgadas","Al entrar a la habitaci\xF3n","No hay distancia espec\xEDfica","A 12 pulgadas del marco"],respuesta_correcta:1,explicacion:"El NEC requiere que el control de iluminaci\xF3n est\xE9 ubicado en la entrada, pero no especifica una medida exacta en pulgadas."},{id:"et_040",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el n\xFAmero m\xE1ximo de desconectadores principales permitidos en una sola acometida?",opciones:["2 desconectadores","4 desconectadores","6 desconectadores","8 desconectadores"],respuesta_correcta:2,explicacion:"La 'Regla de los Seis' (NEC 230.71) permite hasta 6 desconectadores agrupados en un solo lugar."},{id:"et_041",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el prop\xF3sito del Main Bonding Jumper en un sistema el\xE9ctrico?",opciones:["Conectar el chasis del motor a la tuber\xEDa de agua","Unir el conductor neutral con la tierra en el servicio","Proteger los equipos electr\xF3nicos contra rayos","Evitar que el voltaje del neutral suba a m\xE1s de 120V"],respuesta_correcta:1,explicacion:"El Main Bonding Jumper establece la conexi\xF3n cr\xEDtica entre el conductor puesto a tierra (neutral) y el conductor de puesta a tierra (tierra) en el equipo de servicio."},{id:"et_042",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 indica el 'Interrupting Rating' de un breaker de circuito?",opciones:["La corriente m\xE1xima de carga que puede soportar continuamente","La corriente de falla m\xE1s alta que puede interrumpir sin explotar","El tiempo en milisegundos que tarda en dispararse por sobrecarga","La cantidad de veces que puede resetearse antes de fallar"],respuesta_correcta:1,explicacion:"El valor de interrupci\xF3n (t\xEDpicamente 10,000A o 22,000A) es la corriente de cortocircuito m\xE1xima que el breaker puede detener con seguridad."},{id:"et_043",categoria:"ET_MOTORES",pregunta:"\xBFC\xF3mo se define el t\xE9rmino 'Locked Rotor Current' (LRC) en un motor el\xE9ctrico?",opciones:["La corriente de funcionamiento a plena carga mec\xE1nica","La corriente inicial al arrancar cuando el rotor no gira","La corriente m\xEDnima necesaria para mantener el motor girando","La corriente que fluye cuando el motor se sobrecalienta"],respuesta_correcta:1,explicacion:"LRC es la corriente de arranque, que suele ser de 6 a 8 veces la corriente nominal, presente justo antes de que el rotor comience a moverse."},{id:"et_044",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 sucede con la corriente en el secundario si un transformador eleva el voltaje (Step-up)?",opciones:["La corriente aumenta proporcionalmente","La corriente disminuye proporcionalmente","La corriente se mantiene igual al primario","La corriente se duplica autom\xE1ticamente"],respuesta_correcta:1,explicacion:"Por la ley de conservaci\xF3n de energ\xEDa (P=VI), si el voltaje sube, la corriente debe bajar para mantener la potencia constante."},{id:"et_045",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 tipo de luminaria debe usarse en un \xE1rea de regadera (Shower)?",opciones:["Cualquier luminaria con protecci\xF3n GFCI","Luminaria marcada como 'Suitable for Wet Locations'","Luminaria est\xE1ndar con bombillo LED sellado","Luminaria colgante a no menos de 3 pies"],respuesta_correcta:1,explicacion:"Las luminarias instaladas dentro de la zona de regadera deben estar listadas espec\xEDficamente para lugares mojados (Wet Locations)."},{id:"et_046",categoria:"ET_HAZARDOUS",pregunta:"En una clasificaci\xF3n de Clase II, \xBFqu\xE9 tipo de material peligroso est\xE1 presente?",opciones:["Gases inflamables o vapores l\xEDquidos","Polvos combustibles (como harina o carb\xF3n)","Fibras o part\xEDculas vol\xE1tiles inflamables","L\xEDquidos corrosivos que emiten vapores"],respuesta_correcta:1,explicacion:"La Clase II se refiere a \xE1reas con polvos combustibles conductores o no conductores presentes en la atm\xF3sfera."},{id:"et_047",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 clase de circuito de control se limita a una potencia m\xE1xima de 100 VA?",opciones:["Clase 1","Clase 2","Clase 3","Clase 4"],respuesta_correcta:1,explicacion:"Los circuitos Clase 2 est\xE1n limitados en potencia para reducir el riesgo de incendio y descarga el\xE9ctrica, t\xEDpicamente a 100 VA."},{id:"et_048",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es la funci\xF3n principal de un dispositivo de bloqueo (Lockout Device)?",opciones:["Avisar a otros t\xE9cnicos que el equipo est\xE1 en reparaci\xF3n","Impedir f\xEDsicamente que se energice un circuito o equipo","Asegurar que las herramientas no se pierdan en el sitio","Bloquear el acceso a personas no autorizadas al panel"],respuesta_correcta:1,explicacion:"El bloqueo f\xEDsico garantiza que la energ\xEDa no pueda ser restablecida mientras un t\xE9cnico trabaja en el sistema."},{id:"et_049",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es el voltaje de un circuito con una resistencia de 10 Ohmios y una potencia de 1000 Watts?",opciones:["10 Voltios","100 Voltios","240 Voltios","480 Voltios"],respuesta_correcta:1,explicacion:"V = \u221A(P * R). Entonces, \u221A(1000 * 10) = \u221A10000 = 100V."},{id:"et_050",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el s\xEDmbolo 'N' al lado de un texto en la edici\xF3n actual del NEC?",opciones:["Nuevo art\xEDculo o secci\xF3n agregada en esta edici\xF3n","Nota informativa que no es obligatoria cumplir","No aplica para instalaciones de tipo residencial","Nivel de seguridad cr\xEDtico para el electricista"],respuesta_correcta:0,explicacion:"La 'N' indica material que es completamente nuevo en la edici\xF3n vigente del C\xF3digo El\xE9ctrico Nacional."},{id:"et_051",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un cable 10 AWG de cobre con aislamiento TW?",opciones:["20 Amperios","25 Amperios","30 Amperios","35 Amperios"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.16, el cable 10 AWG en la columna de 60\xB0C (TW) tiene una capacidad de 30A."},{id:"et_052",categoria:"ET_CANALIZACIONES",pregunta:"\xBFA qu\xE9 distancia m\xE1xima de una caja de conexiones se debe soportar un conduit de PVC?",opciones:["1 pie","3 pies","5 pies","10 pies"],respuesta_correcta:1,explicacion:"NEC 352.30 requiere que el PVC se soporte a no m\xE1s de 3 pies (900 mm) de cada terminaci\xF3n."},{id:"et_053",categoria:"ET_CIRCUITOS",pregunta:"\xBFEn qu\xE9 \xE1reas de una vivienda NO se requiere protecci\xF3n AFCI (Arc-Fault)?",opciones:["Dormitorios y salas de estar","Comedores y bibliotecas","Garajes y \xE1reas exteriores","Pasillos y vestidores"],respuesta_correcta:2,explicacion:"Los garajes, ba\xF1os y exteriores suelen requerir GFCI, pero el NEC no exige AFCI en estas \xE1reas espec\xEDficas."},{id:"et_054",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de los conductores de entrada de servicio para una casa unifamiliar?",opciones:["60 Amperios","100 Amperios","150 Amperios","200 Amperios"],respuesta_correcta:1,explicacion:"NEC 230.79(C) requiere que el desconectador de servicio para una vivienda unifamiliar sea de al menos 100A."},{id:"et_055",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es la resistencia m\xE1xima permitida para un solo electrodo de varilla (si no se instala uno adicional)?",opciones:["5 Ohmios","10 Ohmios","25 Ohmios","50 Ohmios"],respuesta_correcta:2,explicacion:"NEC 250.53(A)(2) exige que si la resistencia es mayor a 25 Ohmios, se instale un segundo electrodo de apoyo."},{id:"et_056",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 tipo de fusible se utiliza com\xFAnmente para proteger motores debido a su retardo de tiempo?",opciones:["Fusible de acci\xF3n r\xE1pida (Fast-acting)","Fusible de elemento dual (Time-delay)","Fusible de tipo tap\xF3n (Plug fuse)","Fusible de enlace de plata puro"],respuesta_correcta:1,explicacion:"Los fusibles 'Time-delay' permiten el pico de corriente de arranque del motor sin quemarse, pero protegen contra sobrecargas largas."},{id:"et_057",categoria:"ET_MOTORES",pregunta:"\xBFCu\xE1l es el prop\xF3sito del rel\xE9 de sobrecarga (Overload Relay) en un arrancador de motor?",opciones:["Proteger contra cortocircuitos entre fases","Proteger el motor contra un calor excesivo prolongado","Desconectar el motor si el voltaje sube demasiado","Invertir el sentido de giro del motor autom\xE1ticamente"],respuesta_correcta:1,explicacion:"La sobrecarga detecta cuando el motor drena un poco m\xE1s de corriente de lo normal por mucho tiempo, evitando que se queme el bobinado."},{id:"et_058",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFC\xF3mo se conectan los devanados en una configuraci\xF3n 'Delta'?",opciones:["Todos los finales se unen en un punto com\xFAn","El final de una fase se une al inicio de la siguiente","Se usa un cable neutral conectado al centro f\xEDsico","Cada fase opera de forma independiente sin uni\xF3n"],respuesta_correcta:1,explicacion:"En una conexi\xF3n Delta (tri\xE1ngulo), los devanados se conectan en serie formando un lazo cerrado."},{id:"et_059",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es el espacio libre m\xEDnimo alrededor de una luminaria empotrada (Recessed) que no es tipo IC?",opciones:["1/4 pulgada","1/2 pulgada","1 pulgada","2 pulgadas"],respuesta_correcta:1,explicacion:"Las luminarias No-IC deben estar separadas al menos 1/2' de materiales combustibles para evitar incendios."},{id:"et_060",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 t\xE9cnica de protecci\xF3n se requiere para equipos el\xE9ctricos en Clase I, Divisi\xF3n 1?",opciones:["Uso de gabinetes herm\xE9ticos al polvo","Uso de equipos 'Explosion-proof' (A prueba de explosi\xF3n)","Uso de conductores de aluminio aislados","Uso de breakers de alta velocidad \xFAnicamente"],respuesta_correcta:1,explicacion:"Los gabinetes explosion-proof est\xE1n dise\xF1ados para contener una explosi\xF3n interna sin que la llama escape al exterior."},{id:"et_061",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 voltaje m\xE1ximo se maneja t\xEDpicamente en un sistema de control Clase 2 de HVAC?",opciones:["12 Voltios","24 Voltios","48 Voltios","120 Voltios"],respuesta_correcta:1,explicacion:"Aunque puede variar, el est\xE1ndar de la industria HVAC para termostatos y controles Clase 2 es de 24V AC."},{id:"et_062",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es la primera acci\xF3n antes de trabajar en un panel el\xE9ctrico seg\xFAn NFPA 70E?",opciones:["Ponerse los guantes de hule aislantes","Verificar la ausencia de voltaje con un medidor","Informar al supervisor que el trabajo inici\xF3","Colocar etiquetas de peligro en las puertas"],respuesta_correcta:1,explicacion:"Establecer una condici\xF3n de trabajo el\xE9ctricamente segura requiere probar que no hay voltaje con un instrumento calibrado."},{id:"et_063",categoria:"ET_OHM_WATT",pregunta:"\xBFQu\xE9 sucede con la corriente en un circuito de 120V si la resistencia baja de 20 a 10 Ohmios?",opciones:["La corriente se reduce a la mitad","La corriente permanece igual","La corriente se duplica","La corriente aumenta cuatro veces"],respuesta_correcta:2,explicacion:"I = V / R. Inicialmente 120/20 = 6A. Al bajar la resistencia: 120/10 = 12A. La corriente se duplic\xF3."},{id:"et_064",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa la sigla AHJ en el contexto del cumplimiento del c\xF3digo?",opciones:["American Health Jurisdiction","Authority Having Jurisdiction","Approved Home Junctions","Advanced Housing Junctions"],respuesta_correcta:1,explicacion:"La AHJ (Autoridad con Jurisdicci\xF3n) es la organizaci\xF3n o individuo responsable de aprobar equipos e instalaciones (el inspector)."},{id:"et_065",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es el ampacidad m\xE1xima de un cable 1/0 AWG de cobre THWN a 75\xB0C?",opciones:["100 Amperios","125 Amperios","150 Amperios","175 Amperios"],respuesta_correcta:2,explicacion:"Consultando la Tabla 310.16, el cable 1/0 de cobre en la columna de 75\xB0C tiene una ampacidad de 150A."},{id:"et_066",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el porcentaje m\xE1ximo de llenado permitido para una tuber\xEDa con 3 o m\xE1s conductores?",opciones:["31%","40%","53%","60%"],respuesta_correcta:1,explicacion:"El Cap\xEDtulo 9, Tabla 1 del NEC especifica que para 3 o m\xE1s conductores, el \xE1rea ocupada no debe superar el 40%."},{id:"et_067",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 distancia m\xE1xima puede haber entre recept\xE1culos en una pared de una sala residencial?",opciones:["6 pies","10 pies","12 pies","15 pies"],respuesta_correcta:2,explicacion:"NEC 210.52(A)(1) requiere que ning\xFAn punto a lo largo de la l\xEDnea del piso est\xE9 a m\xE1s de 6 pies de un recept\xE1culo (espaciado de 12 pies)."},{id:"et_068",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el color est\xE1ndar del conductor neutral (puesto a tierra) en un sistema de 120/240V?",opciones:["Blanco o Gris","Verde con amarillo","Rojo o Negro","Azul o Naranja"],respuesta_correcta:0,explicacion:"El Art\xEDculo 200.6 requiere que el conductor puesto a tierra se identifique con color blanco o gris."},{id:"et_069",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 calibre m\xEDnimo de cobre se requiere para un conductor de electrodo de tierra (GEC) para un servicio de 200A?",opciones:["#8 AWG","#6 AWG","#4 AWG","#2 AWG"],respuesta_correcta:2,explicacion:"Para un servicio de 200A (t\xEDpicamente conductores de fase 2/0 o 3/0), la Tabla 250.66 requiere un GEC de #4 AWG."},{id:"et_070",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 se refiere el t\xE9rmino 'Trip-Free' en un breaker de circuito?",opciones:["El breaker puede ser operado sin pagar una tarifa","El breaker se dispara aunque la manija se mantenga en ON","El breaker no necesita mantenimiento preventivo","El breaker se dispara sin causar un arco el\xE9ctrico"],respuesta_correcta:1,explicacion:"Un dise\xF1o Trip-Free garantiza que el mecanismo interno desconecte el circuito por falla incluso si alguien bloquea la palanca manualmente."},{id:"et_071",categoria:"ET_MOTORES",pregunta:"\xBFCu\xE1l es el prop\xF3sito de un 'Disconnecting Means' a la vista del motor?",opciones:["Permitir al operador cambiar la velocidad del motor","Garantizar la seguridad del t\xE9cnico durante el mantenimiento","Ahorrar energ\xEDa cuando el motor no est\xE1 en uso","Proteger el motor contra rayos o picos de voltaje"],respuesta_correcta:1,explicacion:"Debe haber un desconectador a la vista (m\xE1ximo 50 pies) para que el t\xE9cnico pueda asegurar que nadie encienda el equipo mientras trabaja."},{id:"et_072",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 tipo de transformador se usa frecuentemente para alimentar controles de 24V en HVAC?",opciones:["Transformador de corriente (CT)","Transformador de potencia industrial","Transformador de Clase 2 (Control)","Transformador de aislamiento galv\xE1nico"],respuesta_correcta:2,explicacion:"Los transformadores de Clase 2 est\xE1n limitados en energ\xEDa para prevenir riesgos de incendio en sistemas de control."},{id:"et_073",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 significa que un recept\xE1culo sea 'Tamper-Resistant' (TR)?",opciones:["Que es resistente a golpes de martillo o ca\xEDdas","Que tiene persianas internas para evitar que ni\xF1os inserten objetos","Que no puede ser removido de la pared sin herramientas","Que es apto para instalaciones en exteriores mojados"],respuesta_correcta:1,explicacion:"Los recept\xE1culos TR tienen un mecanismo que solo permite la entrada si se insertan las dos patas de un enchufe al mismo tiempo."},{id:"et_074",categoria:"ET_HAZARDOUS",pregunta:"\xBFCu\xE1l es la diferencia principal entre Divisi\xF3n 1 y Divisi\xF3n 2?",opciones:["La Divisi\xF3n 1 tiene voltajes mucho m\xE1s altos que la 2","En la 1 el peligro es constante, en la 2 es accidental","La Divisi\xF3n 1 solo aplica a polvos y la 2 solo a gases","La Divisi\xF3n 1 no requiere tuber\xEDa met\xE1lica y la 2 s\xED"],respuesta_correcta:1,explicacion:"En Divisi\xF3n 1 el material peligroso est\xE1 presente en condiciones normales; en Divisi\xF3n 2 solo ocurre por fallas o accidentes."},{id:"et_075",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el calibre m\xEDnimo permitido para conductores de control Clase 1?",opciones:["14 AWG","16 AWG","18 AWG","22 AWG"],respuesta_correcta:2,explicacion:"NEC 725.43 permite calibres tan peque\xF1os como 18 AWG para circuitos de control Clase 1."},{id:"et_076",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 nivel de corriente (Amperios) puede causar fibrilaci\xF3n card\xEDaca en un humano?",opciones:["0.001 Amperios (1 mA)","0.010 Amperios (10 mA)","0.075 Amperios (75 mA)","10.0 Amperios (10000 mA)"],respuesta_correcta:2,explicacion:"Cantidades tan peque\xF1as como 75 a 100 mA (0.075A) son suficientes para descontrolar el ritmo del coraz\xF3n y causar la muerte."},{id:"et_077",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos Watts hay en 1 Caballo de Fuerza (Horsepower)?",opciones:["550 Watts","746 Watts","1000 Watts","1200 Watts"],respuesta_correcta:1,explicacion:"La conversi\xF3n est\xE1ndar utilizada en ingenier\xEDa el\xE9ctrica es 1 HP = 746 Watts."},{id:"et_078",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa una l\xEDnea vertical en el margen de una p\xE1gina del NEC?",opciones:["Esa secci\xF3n es un error de imprenta conocido","Hubo un cambio en el texto respecto a la edici\xF3n anterior","Esa parte del c\xF3digo ha sido eliminada por completo","Esa secci\xF3n solo aplica para instalaciones de alta tensi\xF3n"],respuesta_correcta:1,explicacion:"Las l\xEDneas verticales indican que el lenguaje de esa secci\xF3n espec\xEDfica fue modificado o movido desde la edici\xF3n previa."},{id:"et_079",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la temperatura m\xE1xima de operaci\xF3n para un cable tipo RHW?",opciones:["60\xB0C","75\xB0C","90\xB0C","105\xB0C"],respuesta_correcta:1,explicacion:"La letra 'H' indica calor (Heat), y cables como RHW o THW tienen un l\xEDmite de 75\xB0C."},{id:"et_080",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el uso principal de un accesorio tipo 'LB' en una tuber\xEDa?",opciones:["Para unir dos tramos de tuber\xEDa de diferente material","Para permitir un giro de 90\xB0 con acceso hacia atr\xE1s","Para conectar tuber\xEDa flexible a tuber\xEDa r\xEDgida","Para medir el voltaje sin abrir la canalizaci\xF3n"],respuesta_correcta:1,explicacion:"Un conducto 'LB' (L-shape, Back access) permite hacer giros rectos y tener una tapa de registro en la parte posterior."},{id:"et_081",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 circuito se requiere para alimentar una lavander\xEDa en una vivienda?",opciones:["Un circuito de 15A de uso general","Un circuito de 20A dedicado a la lavander\xEDa","Un circuito compartido con la iluminaci\xF3n del ba\xF1o","Dos circuitos de 20A para peque\xF1os electrodom\xE9sticos"],respuesta_correcta:1,explicacion:"NEC 210.11(C)(2) requiere al menos un circuito de 20 amperios para los recept\xE1culos de la lavander\xEDa."},{id:"et_082",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 parte del sistema el\xE9ctrico une el neutral con la caja met\xE1lica del panel principal?",opciones:["El electrodo de tierra","El tornillo de uni\xF3n verde (Bonding Screw)","El aislador de porcelana del neutral","El conector de la tuber\xEDa de entrada"],respuesta_correcta:1,explicacion:"El bonding screw (o strap) es el medio para asegurar que la caja del panel est\xE9 al mismo potencial que el neutral en el servicio."},{id:"et_083",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es la funci\xF3n del Equipment Grounding Conductor (EGC)?",opciones:["Transportar corriente normal de retorno al panel","Proporcionar un camino de baja impedancia para corriente de falla","Atraer los rayos hacia la varilla de tierra enterrada","Mantener el voltaje de las fases estable a 120V"],respuesta_correcta:1,explicacion:"El EGC (cable verde o desnudo) asegura que si una fase toca el chasis, la corriente fluya r\xE1pido para disparar el breaker."},{id:"et_084",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es la diferencia entre un cortocircuito y una sobrecarga?",opciones:["El cortocircuito es lento, la sobrecarga es instant\xE1nea","La sobrecarga es intencional, el corto es accidental","El corto tiene corriente alt\xEDsima, la sobrecarga es un exceso leve","No hay diferencia, ambos t\xE9rminos significan lo mismo"],respuesta_correcta:2,explicacion:"Una sobrecarga es operar demasiados equipos; un cortocircuito es un fallo de aislamiento con corriente destructiva inmediata."},{id:"et_085",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 indica la 'Service Factor' (SF) en la placa de un motor?",opciones:["La cantidad de veces que el motor puede fallar al a\xF1o","El porcentaje de sobrecarga continua que el motor puede soportar","El tiempo que tarda el motor en enfriarse tras apagarse","La distancia m\xE1xima permitida del cable de alimentaci\xF3n"],respuesta_correcta:1,explicacion:"Un SF de 1.15 significa que el motor puede operar al 115% de su carga nominal por periodos cortos sin da\xF1arse."},{id:"et_086",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es la conexi\xF3n m\xE1s com\xFAn para un servicio comercial trif\xE1sico de 208Y/120V?",opciones:["Conexi\xF3n Delta-Delta","Conexi\xF3n Wye-Wye (Estrella-Estrella)","Conexi\xF3n Delta-Wye (Tri\xE1ngulo-Estrella)","Conexi\xF3n de fase abierta (Open Delta)"],respuesta_correcta:2,explicacion:"La configuraci\xF3n Delta-Wye permite tener un primario de alta tensi\xF3n (Delta) y un secundario con neutral (Wye) para cargas de 120V."},{id:"et_087",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 altura m\xEDnima deben estar los recept\xE1culos en un garaje comercial?",opciones:["12 pulgadas sobre el piso","18 pulgadas sobre el piso","48 pulgadas sobre el piso","No hay una altura m\xEDnima"],respuesta_correcta:1,explicacion:"Debido a los vapores de gasolina que bajan al piso, se requiere que cualquier fuente de ignici\xF3n est\xE9 a 18' o m\xE1s (NEC 511.7)."},{id:"et_088",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 tipo de sello se usa en tuber\xEDas para evitar el paso de gases entre \xE1reas?",opciones:["Sello de silicona para alta temperatura","Accesorio de sello (Sealing Fitting) con compuesto","Cinta aislante de hule vulcanizado","Espuma expansiva contra incendios"],respuesta_correcta:1,explicacion:"Los sealing fittings se llenan con un compuesto especial que bloquea el paso de gases inflamables a trav\xE9s del conduit."},{id:"et_089",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el requisito de separaci\xF3n entre cables Clase 2 y cables de potencia (120V)?",opciones:["Pueden ir en la misma tuber\xEDa si est\xE1n aislados","Deben estar separados al menos por 2 pulgadas (50 mm)","No pueden estar a menos de 12 pulgadas de distancia","Deben ser del mismo color para evitar confusiones"],respuesta_correcta:1,explicacion:"NEC 725.136 requiere una separaci\xF3n f\xEDsica (t\xEDpicamente 2 pulgadas) para evitar que el alto voltaje induzca corriente en el de baja."},{id:"et_090",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Arc Flash'?",opciones:["Un destello de luz causado por un corto en una bombilla","Una liberaci\xF3n violenta de energ\xEDa t\xE9rmica por un arco el\xE9ctrico","El reflejo del sol en un panel de distribuci\xF3n met\xE1lico","Una t\xE9cnica de soldadura el\xE9ctrica para unir tuber\xEDas"],respuesta_correcta:1,explicacion:"Un Arc Flash es una explosi\xF3n de calor y luz extremadamente peligrosa que ocurre durante una falla de arco en equipos de potencia."},{id:"et_091",categoria:"ET_OHM_WATT",pregunta:"Si un circuito tiene 120V y 10A, \xBFcu\xE1l es la resistencia?",opciones:["1.2 Ohmios","12 Ohmios","120 Ohmios","1200 Ohmios"],respuesta_correcta:1,explicacion:"R = V / I. 120 / 10 = 12 Ohmios."},{id:"et_092",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC cubre los m\xE9todos de cableado y materiales generales?",opciones:["Art\xEDculo 250","Art\xEDculo 300","Art\xEDculo 430","Art\xEDculo 700"],respuesta_correcta:1,explicacion:"El Art\xEDculo 300 establece los requisitos generales para todos los m\xE9todos de cableado permitidos por el c\xF3digo."},{id:"et_093",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la sigla AWG?",opciones:["American Wire Gauge","Aluminum Wire Grade","Automatic Wire Generator","Applied Wattage Group"],respuesta_correcta:0,explicacion:"AWG es el sistema est\xE1ndar norteamericano para medir el di\xE1metro de los conductores el\xE9ctricos."},{id:"et_094",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el porcentaje de llenado para 2 conductores en una tuber\xEDa?",opciones:["31%","40%","53%","60%"],respuesta_correcta:0,explicacion:"Para exactamente dos conductores en una canalizaci\xF3n, el l\xEDmite de llenado es del 31% del \xE1rea interna."},{id:"et_095",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 se define como una carga continua (Continuous Load)?",opciones:["Una carga que funciona por m\xE1s de 1 hora","Una carga que funciona por m\xE1s de 2 horas","Una carga que funciona por m\xE1s de 3 horas","Una carga que nunca se apaga durante el a\xF1o"],respuesta_correcta:2,explicacion:"Seg\xFAn el Art\xEDculo 100, una carga continua es aquella donde la corriente m\xE1xima se mantiene por 3 horas o m\xE1s."},{id:"et_096",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el espacio libre vertical sobre una calle p\xFAblica para cables de acometida?",opciones:["10 pies","12 pies","15 pies","18 pies"],respuesta_correcta:3,explicacion:"NEC 230.24(B)(4) requiere un despeje de 18 pies sobre calles, avenidas y callejones p\xFAblicos."},{id:"et_097",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 tabla del NEC se usa para dimensionar el conductor de puesta a tierra de equipos (EGC)?",opciones:["Tabla 250.66","Tabla 250.102","Tabla 250.122","Tabla 310.16"],respuesta_correcta:2,explicacion:"La Tabla 250.122 dimensiona el cable de tierra basado en el tama\xF1o del dispositivo de sobrecorriente (breaker)."},{id:"et_098",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el color est\xE1ndar de un breaker de 20A en la mayor\xEDa de las marcas residenciales?",opciones:["Blanco","Azul","Rojo","Negro (con marca blanca o naranja)"],respuesta_correcta:3,explicacion:"Aunque las marcas var\xEDan, el est\xE1ndar visual suele ser negro, pero la marca '20' es la identificaci\xF3n legal obligatoria."},{id:"et_099",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa 'NEMA Design' en la placa de un motor?",opciones:["El pa\xEDs donde se fabric\xF3 el motor el\xE9ctrico","La eficiencia energ\xE9tica certificada por el gobierno","Las caracter\xEDsticas de torque y corriente de arranque","El tama\xF1o f\xEDsico de los tornillos de montaje"],respuesta_correcta:2,explicacion:"Los dise\xF1os NEMA (A, B, C, D) clasifican el comportamiento del motor durante el arranque y bajo carga."},{id:"et_100",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 componente protege a un transformador contra sobrecalentamiento interno?",opciones:["El breaker secundario","El fusible primario","El rel\xE9 t\xE9rmico o sensor de temperatura","La varilla de tierra conectada al chasis"],respuesta_correcta:2,explicacion:"Muchos transformadores tienen sensores t\xE9rmicos internos que cortan el flujo si la temperatura del n\xFAcleo sube demasiado."},{id:"et_101",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la potencia total en un circuito trif\xE1sico equilibrado de 208V con una corriente de 10A (FP=1)?",opciones:["2,080 Watts","3,602 Watts","4,160 Watts","6,240 Watts"],respuesta_correcta:1,explicacion:"En trif\xE1sico, P = V * I * \u221A3. Calculamos: 208 * 10 * 1.732 = 3,602.5 Watts."},{id:"et_102",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos Ohmios tiene una bombilla de 100W operando a un voltaje est\xE1ndar de 120V?",opciones:["1.2 Ohmios","120 Ohmios","144 Ohmios","1000 Ohmios"],respuesta_correcta:2,explicacion:"R = V\xB2 / P. Entonces: 120 * 120 / 100 = 14,400 / 100 = 144 Ohmios."},{id:"et_103",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC regula el uso de cables flexibles y cordones para equipos?",opciones:["Art\xEDculo 310","Art\xEDculo 400","Art\xEDculo 430","Art\xEDculo 440"],respuesta_correcta:1,explicacion:"El Art\xEDculo 400 cubre los requisitos para cables flexibles, incluyendo su uso prohibido como sustituto de cableado fijo."},{id:"et_104",categoria:"ET_NEC",pregunta:"Seg\xFAn el NEC 110.26, \xBFcu\xE1l es el ancho m\xEDnimo del espacio de trabajo frente a un equipo el\xE9ctrico?",opciones:["24 pulgadas (60 cm)","30 pulgadas (76 cm)","36 pulgadas (91 cm)","42 pulgadas (106 cm)"],respuesta_correcta:1,explicacion:"El ancho del espacio de trabajo debe ser el ancho del equipo o 30 pulgadas, lo que sea mayor."},{id:"et_105",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 tabla del NEC se utiliza para determinar el di\xE1metro y \xE1rea de los conductores aislados?",opciones:["Cap\xEDtulo 9, Tabla 1","Cap\xEDtulo 9, Tabla 4","Cap\xEDtulo 9, Tabla 5","Cap\xEDtulo 9, Tabla 8"],respuesta_correcta:2,explicacion:"La Tabla 5 del Cap\xEDtulo 9 proporciona las dimensiones de los conductores y sus diferentes tipos de aislamiento."},{id:"et_106",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un conductor 4 AWG de aluminio tipo THWN a 75\xB0C?",opciones:["55 Amperios","65 Amperios","75 Amperios","85 Amperios"],respuesta_correcta:1,explicacion:"Consultando la Tabla 310.16, el cable 4 AWG de aluminio en la columna de 75\xB0C tiene una capacidad de 65A."},{id:"et_107",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es la distancia m\xE1xima permitida entre soportes para un conducto met\xE1lico intermedio (IMC)?",opciones:["5 pies (1.5 m)","8 pies (2.4 m)","10 pies (3.0 m)","12 pies (3.6 m)"],respuesta_correcta:2,explicacion:"Al igual que el RMC, el Art\xEDculo 342.30 establece que el IMC debe ser soportado a intervalos no mayores de 10 pies."},{id:"et_108",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 tipo de caja de salida se requiere para soportar un ventilador de techo (Paddle Fan)?",opciones:["Caja octagonal est\xE1ndar","Caja de pl\xE1stico reforzada","Caja marcada como 'Fan-Rated'","Caja de metal con abrazadera"],respuesta_correcta:2,explicacion:"El NEC exige que las cajas para ventiladores de techo est\xE9n listadas y marcadas espec\xEDficamente para ese prop\xF3sito debido al peso y vibraci\xF3n."},{id:"et_109",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es el amperaje m\xE1ximo de un circuito derivado que alimenta solo una carga de iluminaci\xF3n?",opciones:["15 Amperios","20 Amperios","30 Amperios","50 Amperios"],respuesta_correcta:3,explicacion:"Seg\xFAn NEC 210.23, los circuitos de 50A est\xE1n limitados a cargas de iluminaci\xF3n fijas con equipo pesado en aplicaciones no residenciales."},{id:"et_110",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es el requisito de protecci\xF3n GFCI para recept\xE1culos en una cocina residencial?",opciones:["Solo los recept\xE1culos sobre el mostrador","Solo los recept\xE1culos a 6 pies del fregadero","Todos los recept\xE1culos que sirven al mostrador","Solo el recept\xE1culo del refrigerador y estufa"],respuesta_correcta:2,explicacion:"NEC 210.8(A)(6) requiere protecci\xF3n GFCI para todos los recept\xE1culos que sirven a las superficies de los mostradores de la cocina."},{id:"et_111",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 conductor no est\xE1 permitido conectar al lado de carga de un desconectador de servicio?",opciones:["Conductor de fase A","Conductor de fase B","Conductor puesto a tierra (Neutral)","Conductor de uni\xF3n de equipo"],respuesta_correcta:2,explicacion:"El neutral no debe ser desconectado a menos que todas las fases se desconecten simult\xE1neamente mediante un polo del mismo switch."},{id:"et_112",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el despeje m\xEDnimo horizontal para conductores de acometida desde una ventana que se abre?",opciones:["1 pie (30 cm)","2 pies (60 cm)","3 pies (90 cm)","6 pies (1.8 m)"],respuesta_correcta:2,explicacion:"NEC 230.9(A) requiere que los conductores de servicio est\xE9n al menos a 3 pies de ventanas, puertas o salidas de incendio."},{id:"et_113",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 tipo de electrodo de tierra se conoce com\xFAnmente como 'Ufer Ground'?",opciones:["Varilla de acero de 8 pies","Placa met\xE1lica enterrada","Electrodo revestido de concreto","Tuber\xEDa de agua met\xE1lica fr\xEDa"],respuesta_correcta:2,explicacion:"El Art\xEDculo 250.52(A)(3) define el electrodo revestido de concreto, apodado 'Ufer' por su inventor."},{id:"et_114",categoria:"ET_GROUNDING",pregunta:"\xBFDe qu\xE9 color debe ser el aislamiento de un conductor neutral en un sistema de 277/480V?",opciones:["Blanco s\xF3lido \xFAnicamente","Gris o con franjas grises","Negro con cinta blanca","Verde con franja blanca"],respuesta_correcta:1,explicacion:"Cuando hay m\xFAltiples sistemas de voltaje, se usa gris para el neutral del sistema de mayor voltaje (277/480V) y blanco para el de 120/240V."},{id:"et_115",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el amperaje est\xE1ndar de un fusible que sigue despu\xE9s de los 100 Amperios?",opciones:["110 Amperios","125 Amperios","150 Amperios","175 Amperios"],respuesta_correcta:0,explicacion:"La Tabla 240.6(A) lista las clasificaciones est\xE1ndar de amperaje; despu\xE9s de 100A sigue 110A."},{id:"et_116",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 regla permite proteger un conductor con un breaker mayor a su ampacidad en HVAC?",opciones:["Regla del 125% de la carga","Regla del siguiente tama\xF1o est\xE1ndar","Regla del motor-compresor (Art 440)","Regla de la ca\xEDda de voltaje"],respuesta_correcta:2,explicacion:"El Art\xEDculo 440 permite que el breaker sea mucho m\xE1s grande que el cable para permitir el arranque del compresor sin disparos molestos."},{id:"et_117",categoria:"ET_MOTORES",pregunta:"\xBFC\xF3mo se dimensiona el OCPD para un motor que tiene una corriente nominal (FLC) de 20A?",opciones:["20 Amperios fijos","25 Amperios (125%)","50 Amperios (250% aprox)","80 Amperios (400% aprox)"],respuesta_correcta:2,explicacion:"Seg\xFAn NEC 430.52, para breakers de tiempo inverso, se permite hasta el 250% de la FLC del motor (20 * 2.5 = 50A)."},{id:"et_118",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa 'Locked Rotor Code Letter' en la placa de un motor?",opciones:["El tipo de rodamiento que usa el rotor","La clase de aislamiento de los cables","Los KVA por HP durante el arranque","La temperatura m\xE1xima de operaci\xF3n"],respuesta_correcta:2,explicacion:"Las letras de c\xF3digo (A a V) indican la cantidad de energ\xEDa (KVA) que consume el motor por cada caballo de fuerza al arrancar."},{id:"et_119",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es la corriente del primario de un transformador de 25 KVA operando a 480V monof\xE1sico?",opciones:["25.0 Amperios","41.6 Amperios","52.1 Amperios","60.4 Amperios"],respuesta_correcta:2,explicacion:"I = VA / V. Entonces: 25,000 / 480 = 52.08 Amperios."},{id:"et_120",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 art\xEDculo del NEC proh\xEDbe el uso de transformadores de tipo seco en lugares mojados?",opciones:["Art\xEDculo 430","Art\xEDculo 440","Art\xEDculo 450","Art\xEDculo 490"],respuesta_correcta:2,explicacion:"El Art\xEDculo 450 establece que los transformadores deben estar listados para el ambiente donde se instalan (interior vs exterior)."},{id:"et_121",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1ntos VA se deben calcular para una luminaria tipo 'Track Lighting' de 10 pies?",opciones:["180 VA","500 VA","750 VA","1500 VA"],respuesta_correcta:3,explicacion:"NEC 220.43(B) requiere calcular 150 VA por cada 2 pies de riel de iluminaci\xF3n (10/2 * 150 = 750 VA, pero para circuitos comerciales se usa el c\xE1lculo de carga)."},{id:"et_122",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la ubicaci\xF3n prohibida para una luminaria abierta (sin globo protector)?",opciones:["Encima de la estufa de cocina","Dentro de un cl\xF3set de ropa","En un garaje de techos bajos","En una pared de pasillo exterior"],respuesta_correcta:1,explicacion:"NEC 410.16 proh\xEDbe bombillas incandescentes expuestas en cl\xF3sets de ropa por el alto riesgo de incendio con los materiales almacenados."},{id:"et_123",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 tipo de conduit es obligatorio en una instalaci\xF3n de Clase I, Divisi\xF3n 1?",opciones:["PVC de c\xE9dula 80 (Heavy wall)","EMT con conectores de compresi\xF3n","RMC (R\xEDgido) o IMC roscado","Tuber\xEDa flexible de metal (FMC)"],respuesta_correcta:2,explicacion:"El NEC requiere tuber\xEDa met\xE1lica r\xEDgida (RMC) o intermedio (IMC) con uniones roscadas para contener posibles explosiones internas."},{id:"et_124",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es la potencia m\xE1xima permitida para un circuito Clase 3?",opciones:["100 VA","150 VA","200 VA","No tiene l\xEDmite de potencia"],respuesta_correcta:0,explicacion:"Al igual que la Clase 2, los circuitos Clase 3 tienen l\xEDmites de energ\xEDa estrictos (t\xEDpicamente 100 VA) para evitar choques el\xE9ctricos."},{id:"et_125",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 categor\xEDa de PPE (HRC) requiere ropa resistente al arco de al menos 8 cal/cm\xB2?",opciones:["Categor\xEDa 1","Categor\xEDa 2","Categor\xEDa 3","Categor\xEDa 4"],respuesta_correcta:1,explicacion:"La Categor\xEDa 2 de NFPA 70E exige una protecci\xF3n m\xEDnima de 8 cal/cm\xB2, que suele incluir camisa y pantalones FR o sobretodo."},{id:"et_126",categoria:"ET_OHM_WATT",pregunta:"Si tres resistencias de 30 Ohmios cada una se conectan en serie, \xBFcu\xE1l es la resistencia total?",opciones:["10 Ohmios","30 Ohmios","60 Ohmios","90 Ohmios"],respuesta_correcta:3,explicacion:"En serie, las resistencias simplemente se suman: 30 + 30 + 30 = 90 Ohmios."},{id:"et_127",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es el voltaje necesario para mover 2 Amperios a trav\xE9s de una resistencia de 240 Ohmios?",opciones:["120 Voltios","240 Voltios","480 Voltios","960 Voltios"],respuesta_correcta:2,explicacion:"Ley de Ohm: V = I * R. Entonces: 2A * 240\u03A9 = 480V."},{id:"et_128",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Accessible' aplicado a m\xE9todos de cableado (wiring methods)?",opciones:["Que se puede tocar sin quitar ninguna parte del edificio","Que se puede alcanzar tras quitar un panel de acceso","Que est\xE1 a la vista de cualquier persona en la habitaci\xF3n","Que el cableado no tiene ning\xFAn tipo de aislamiento"],respuesta_correcta:0,explicacion:"Para cableado, 'Accessible' significa que puede ser removido o expuesto sin da\xF1ar la estructura del edificio."},{id:"et_129",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo nominal permitido para sistemas el\xE9ctricos en unidades de vivienda?",opciones:["120 Voltios","240 Voltios","600 Voltios","1000 Voltios"],respuesta_correcta:2,explicacion:"La mayor\xEDa de las reglas residenciales del NEC asumen sistemas que no superan los 600V entre conductores."},{id:"et_130",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 conductor se identifica con una marca naranja o una cinta naranja (High-Leg)?",opciones:["El neutral en un sistema de 120/240V","La fase con el voltaje m\xE1s alto a tierra en Delta","El cable de tierra en un sistema aislado","La fase A en cualquier sistema trif\xE1sico"],respuesta_correcta:1,explicacion:"En un sistema Delta de 4 hilos (High-Leg), la fase con 208V a tierra debe identificarse con color naranja."},{id:"et_131",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de un conductor de cobre para cableado general?",opciones:["10 AWG","12 AWG","14 AWG","18 AWG"],respuesta_correcta:2,explicacion:"NEC 310.106(A) establece que el tama\xF1o m\xEDnimo para conductores de potencia es 14 AWG cobre o 12 AWG aluminio."},{id:"et_132",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 profundidad m\xEDnima de cobertura se requiere para un conduit RMC bajo una calle p\xFAblica?",opciones:["12 pulgadas","18 pulgadas","24 pulgadas","30 pulgadas"],respuesta_correcta:2,explicacion:"Bajo calles p\xFAblicas o \xE1reas de tr\xE1fico pesado, la Tabla 300.5 exige una profundidad m\xEDnima de 24 pulgadas para cualquier m\xE9todo."},{id:"et_133",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1ntos conductores 12 AWG THHN caben en una caja de 4 x 1-1/2 pulgadas cuadrada (21.0 cu in)?",opciones:["7 conductores","9 conductores","11 conductores","13 conductores"],respuesta_correcta:1,explicacion:"Cada 12 AWG requiere 2.25 cu in. 21.0 / 2.25 = 9.33. El m\xE1ximo permitido son 9 conductores."},{id:"et_134",categoria:"ET_CIRCUITOS",pregunta:"\xBFA qu\xE9 distancia de un fregadero en una lavander\xEDa se requiere protecci\xF3n GFCI?",opciones:["Solo a menos de 3 pies","Solo a menos de 6 pies","No importa la distancia","Solo si el recept\xE1culo est\xE1 bajo el fregadero"],respuesta_correcta:1,explicacion:"NEC 210.8(A)(7) requiere GFCI para todos los recept\xE1culos instalados a menos de 6 pies del borde superior de un fregadero."},{id:"et_135",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga m\xEDnima para circuitos de peque\xF1os electrodom\xE9sticos en la cocina?",opciones:["1500 VA por circuito","1800 VA por circuito","2400 VA por circuito","3000 VA por circuito"],respuesta_correcta:0,explicacion:"NEC 220.52(A) especifica que cada circuito de 20A para peque\xF1os electrodom\xE9sticos debe calcularse a 1500 VA."},{id:"et_136",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es la longitud m\xE1xima permitida para el conductor de entrada de servicio dentro del edificio?",opciones:["3 pies","6 pies","10 pies","Lo m\xE1s corto posible (no especificado)"],respuesta_correcta:3,explicacion:"El NEC no da un n\xFAmero exacto, pero exige que el desconectador est\xE9 en el punto de entrada 'm\xE1s cercano' posible."},{id:"et_137",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o de cable de cobre se requiere para una acometida residencial de 100A?",opciones:["#4 AWG","#3 AWG","#2 AWG","#1 AWG"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 310.12 para servicios de vivienda, un servicio de 100A requiere conductores de fase de cobre calibre #4 AWG."},{id:"et_138",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el prop\xF3sito del conductor de electrodo de puesta a tierra (GEC)?",opciones:["Conectar los chasis de los motores al panel","Conectar el sistema el\xE9ctrico a la tierra f\xEDsica","Servir como retorno de corriente para cargas de 120V","Unir las tuber\xEDas de gas con el sistema el\xE9ctrico"],respuesta_correcta:1,explicacion:"El GEC es el cable que une el terminal neutral/tierra del servicio con la varilla de tierra o tuber\xEDa de agua."},{id:"et_139",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 tama\xF1o m\xEDnimo de EGC de cobre se requiere para un circuito protegido por un breaker de 60A?",opciones:["#12 AWG","#10 AWG","#8 AWG","#6 AWG"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 250.122, un dispositivo de sobrecorriente de 60A requiere un cable de tierra de equipo de al menos #10 AWG cobre."},{id:"et_140",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es la clasificaci\xF3n de interrupci\xF3n m\xEDnima para breakers residenciales comunes?",opciones:["1,000 Amperios (1k AIC)","5,000 Amperios (5k AIC)","10,000 Amperios (10k AIC)","22,000 Amperios (22k AIC)"],respuesta_correcta:2,explicacion:"La mayor\xEDa de los breakers est\xE1ndar para paneles residenciales tienen un valor de interrupci\xF3n (AIC) de 10,000 Amperios."},{id:"et_141",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 tipo de breaker se requiere para proteger contra incendios causados por arcos el\xE9ctricos?",opciones:["GFCI (Ground Fault)","AFCI (Arc Fault)","Breaker Termomagn\xE9tico","Breaker de tiempo inverso"],respuesta_correcta:1,explicacion:"El AFCI detecta las firmas electr\xF3nicas de arcos peligrosos y corta la energ\xEDa para prevenir incendios antes de que ocurran."},{id:"et_142",categoria:"ET_MOTORES",pregunta:"\xBFCu\xE1l es la corriente de arranque aproximada de un motor con letra de c\xF3digo 'G'?",opciones:["3 veces la corriente nominal","6 veces la corriente nominal","9 veces la corriente nominal","12 veces la corriente nominal"],respuesta_correcta:1,explicacion:"La letra 'G' corresponde a un rango de 5.6 a 6.29 KVA/HP, que promedia unas 6 veces la corriente de funcionamiento."},{id:"et_143",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 distancia m\xE1xima debe estar el desconectador de un motor?",opciones:["A la vista y no m\xE1s de 25 pies","A la vista y no m\xE1s de 50 pies","En el mismo piso y no m\xE1s de 100 pies","No hay l\xEDmite si el breaker se puede bloquear"],respuesta_correcta:1,explicacion:"El NEC define 'a la vista' como visible y a una distancia no mayor de 50 pies (15 metros) del equipo."},{id:"et_144",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFC\xF3mo se llama el devanado de un transformador que se conecta a la fuente de energ\xEDa?",opciones:["Devanado Secundario","Devanado Primario","Devanado de Control","Devanado Terciario"],respuesta_correcta:1,explicacion:"El devanado primario es el que recibe el voltaje de entrada, independientemente de si el transformador eleva o reduce el voltaje."},{id:"et_145",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 voltaje hay entre dos fases en un sistema trif\xE1sico 'Wye' de 208/120V?",opciones:["120 Voltios","208 Voltios","240 Voltios","277 Voltios"],respuesta_correcta:1,explicacion:"En un sistema Wye de 208/120V, el voltaje entre cualquier fase y neutral es 120V, y entre dos fases cualesquiera es 208V."},{id:"et_146",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga m\xE1xima permitida para un circuito de iluminaci\xF3n de 15A de uso continuo?",opciones:["10 Amperios","12 Amperios","15 Amperios","20 Amperios"],respuesta_correcta:1,explicacion:"Para cargas continuas, solo se puede usar el 80% de la capacidad del circuito. 15A * 0.80 = 12 Amperios."},{id:"et_147",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 tipo de cable se permite usar para luminarias en un cielorraso suspendido?",opciones:["Cable tipo NM-B (Romex)","Cable tipo AC o MC (Armado)","Cable de extensi\xF3n dom\xE9stico","Conductores sueltos THHN"],respuesta_correcta:1,explicacion:"En edificios comerciales con cielorrasos suspendidos, se requiere el uso de cables protegidos met\xE1licamente como AC o MC."},{id:"et_148",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 define a un \xE1rea como Clase III?",opciones:["Presencia de polvos met\xE1licos explosivos","Presencia de vapores de gasolina","Presencia de fibras o part\xEDculas vol\xE1tiles","Presencia de qu\xEDmicos altamente corrosivos"],respuesta_correcta:2,explicacion:"La Clase III se refiere a lugares donde se manejan o almacenan fibras de f\xE1cil ignici\xF3n como textiles o aserr\xEDn."},{id:"et_149",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para un circuito de control Clase 1?",opciones:["24 Voltios","120 Voltios","600 Voltios","1000 Voltios"],respuesta_correcta:2,explicacion:"A diferencia de Clase 2, los circuitos Clase 1 pueden operar hasta a 600V, aunque com\xFAnmente operan a 120V."},{id:"et_150",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa la sigla 'LOTO'?",opciones:["Line Off, Time Out","Low Output, Total Ohm","Lockout / Tagout","Live Only, Trained Only"],respuesta_correcta:2,explicacion:"LOTO es el procedimiento de seguridad para asegurar que la maquinaria o equipo est\xE9 apagado e inoperable durante el mantenimiento."},{id:"et_151",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la ca\xEDda de voltaje en un cable con 0.2 Ohmios si la carga es de 30 Amperios?",opciones:["3 Voltios","6 Voltios","12 Voltios","15 Voltios"],respuesta_correcta:1,explicacion:"V = I * R. Entonces: 30A * 0.2\u03A9 = 6 Voltios."},{id:"et_152",categoria:"ET_OHM_WATT",pregunta:"\xBFQu\xE9 potencia disipa una resistencia de 10 Ohmios conectada a 120V?",opciones:["12 Watts","120 Watts","1200 Watts","1440 Watts"],respuesta_correcta:3,explicacion:"P = V\xB2 / R. Entonces: 120 * 120 / 10 = 14400 / 10 = 1440 Watts."},{id:"et_153",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el art\xEDculo del NEC que cubre las instalaciones en piscinas y fuentes?",opciones:["Art\xEDculo 430","Art\xEDculo 440","Art\xEDculo 680","Art\xEDculo 700"],respuesta_correcta:2,explicacion:"El Art\xEDculo 680 contiene reglas cr\xEDticas de seguridad para prevenir electrocuciones en agua."},{id:"et_154",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 secci\xF3n del NEC trata sobre los requisitos para espacios de cables en techos (Plenums)?",opciones:["Secci\xF3n 110.26","Secci\xF3n 300.22","Secci\xF3n 430.12","Secci\xF3n 725.3"],respuesta_correcta:1,explicacion:"La secci\xF3n 300.22 regula los m\xE9todos de cableado en espacios que transportan aire ambiental."},{id:"et_155",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 tipo de aislamiento se identifica por ser libre de hal\xF3genos y retardante al fuego?",opciones:["THHN","THWN","LSZH (Low Smoke)","XHHW"],respuesta_correcta:2,explicacion:"Los cables LSZH se usan en \xE1reas concurridas para evitar gases t\xF3xicos en caso de incendio."},{id:"et_156",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un cable 2 AWG de cobre THHN a 90\xB0C?",opciones:["100 Amperios","115 Amperios","125 Amperios","130 Amperios"],respuesta_correcta:3,explicacion:"Seg\xFAn la Tabla 310.16, el cable 2 AWG de cobre en la columna de 90\xB0C tiene una capacidad de 130A."},{id:"et_157",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 porcentaje de llenado se permite para un solo conductor dentro de un conduit?",opciones:["31%","40%","53%","60%"],respuesta_correcta:2,explicacion:"Para un solo conductor, el NEC permite ocupar hasta el 53% del \xE1rea transversal interna del tubo."},{id:"et_158",categoria:"ET_CANALIZACIONES",pregunta:"\xBFA qu\xE9 distancia m\xE1xima de una caja de EMT debe colocarse el primer soporte?",opciones:["1 pie (30 cm)","3 pies (90 cm)","5 pies (1.5 m)","10 pies (3.0 m)"],respuesta_correcta:1,explicacion:"El EMT debe soportarse a una distancia m\xE1xima de 3 pies de cada terminaci\xF3n (cajas, tableros, etc.)."},{id:"et_159",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la clasificaci\xF3n m\xEDnima para los circuitos de recept\xE1culos en el \xE1rea de comedor?",opciones:["15 Amperios","20 Amperios","30 Amperios","No hay requisito"],respuesta_correcta:1,explicacion:"NEC 210.11(C)(1) exige circuitos de 20A para el \xE1rea de comedor, cocina y despensa."},{id:"et_160",categoria:"ET_CIRCUITOS",pregunta:"\xBFD\xF3nde es obligatorio instalar un recept\xE1culo GFCI en un garaje residencial?",opciones:["Solo cerca de la puerta principal","Solo si hay un fregadero en el garaje","En todos los recept\xE1culos del garaje","Solo en el recept\xE1culo del abridor de puerta"],respuesta_correcta:2,explicacion:"NEC 210.8(A)(2) exige que todos los recept\xE1culos de 125V en garajes tengan protecci\xF3n GFCI."},{id:"et_161",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o m\xEDnimo de cable de aluminio se requiere para un servicio de 200A en una casa?",opciones:["2/0 AWG","3/0 AWG","4/0 AWG","250 kcmil"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.12, un servicio residencial de 200A requiere conductores de fase de aluminio calibre 4/0 AWG."},{id:"et_162",categoria:"ET_SERVICIO",pregunta:"\xBFA qu\xE9 altura m\xEDnima debe estar el punto de conexi\xF3n de la acometida sobre una entrada de auto?",opciones:["10 pies","12 pies","15 pies","18 pies"],respuesta_correcta:1,explicacion:"NEC 230.24(B)(2) requiere un despeje de 12 pies sobre entradas de autos residenciales (driveways)."},{id:"et_163",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 metal no est\xE1 permitido usar como electrodo de tierra por s\xED solo?",opciones:["Cobre","Acero inoxidable","Aluminio","Hierro galvanizado"],respuesta_correcta:2,explicacion:"El aluminio no se permite para electrodos de tierra enterrados debido a su alta tasa de corrosi\xF3n galv\xE1nica en contacto con el suelo."},{id:"et_164",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el color prohibido para identificar conductores de fase en un sistema de potencia?",opciones:["Verde","Rojo","Azul","Negro"],respuesta_correcta:0,explicacion:"El color verde (y verde con rayas amarillas) est\xE1 reservado exclusivamente para la puesta a tierra de equipos."},{id:"et_165",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 significa la sigla OCPD en los diagramas el\xE9ctricos?",opciones:["Over Current Protection Device","Output Current Power Drive","Original Circuit Phase Detector","Open Circuit Permanent Damage"],respuesta_correcta:0,explicacion:"OCPD se refiere gen\xE9ricamente a breakers o fusibles que protegen el circuito contra excesos de corriente."},{id:"et_166",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 ocurre cuando un breaker termomagn\xE9tico se dispara por sobrecarga leve?",opciones:["Un electroim\xE1n jala el gatillo instant\xE1neamente","Una l\xE1mina bimet\xE1lica se dobla debido al calor","Un fusible interno se quema y debe reemplazarse","El voltaje sube hasta que el circuito se rompe"],respuesta_correcta:1,explicacion:"Las sobrecargas son detectadas por el componente t\xE9rmico (bimetal), mientras que los cortos son detectados por el componente magn\xE9tico."},{id:"et_167",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se calculan las protecciones de sobrecarga (Overloads) est\xE1ndar?",opciones:["100%","115% a 125%","150% a 175%","200% a 250%"],respuesta_correcta:1,explicacion:"Dependiendo del Factor de Servicio (SF) y el aumento de temperatura, los overloads se ajustan t\xEDpicamente entre el 115% y 125% de la placa."},{id:"et_168",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla del NEC se usa para motores de Corriente Continua (DC)?",opciones:["Tabla 430.247","Tabla 430.248","Tabla 430.250","Tabla 430.52"],respuesta_correcta:0,explicacion:"La Tabla 430.247 proporciona los valores de corriente a plena carga para motores de corriente continua."},{id:"et_169",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 voltaje se obtiene entre una fase y el neutral en un sistema trif\xE1sico 480Y/277V?",opciones:["120 Voltios","208 Voltios","240 Voltios","277 Voltios"],respuesta_correcta:3,explicacion:"En un sistema Wye de 480V, el voltaje de fase a neutral es 277V (480 / 1.732)."},{id:"et_170",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es la funci\xF3n de los 'Taps' en un transformador de potencia?",opciones:["Cambiar de monof\xE1sico a trif\xE1sico","Ajustar ligeramente el voltaje de salida","Desconectarlo en caso de emergencia","Medir la corriente sin usar un mult\xEDmetro"],respuesta_correcta:1,explicacion:"Los taps permiten cambiar la relaci\xF3n de vueltas para compensar variaciones en el voltaje de la red primaria."},{id:"et_171",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es el espacio m\xEDnimo entre una luminaria LED y el estante de un cl\xF3set?",opciones:["3 pulgadas","6 pulgadas","12 pulgadas","18 pulgadas"],respuesta_correcta:2,explicacion:"NEC 410.16(C) especifica una distancia m\xEDnima de 12 pulgadas para luminarias de superficie incandescentes o LED."},{id:"et_172",categoria:"ET_ILUMINACION",pregunta:"\xBFC\xF3mo se calcula la carga de iluminaci\xF3n comercial basada en el \xE1rea?",opciones:["Usando la Tabla 220.12 y los pies cuadrados","Contando cada bombillo individualmente","Multiplicando el voltaje por el amperaje del breaker","Sumando los Watts de todos los balastos instalados"],respuesta_correcta:0,explicacion:"En edificios comerciales, el NEC proporciona valores de VA por pie cuadrado seg\xFAn el tipo de ocupaci\xF3n en la Tabla 220.12."},{id:"et_173",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa una ubicaci\xF3n de 'Divisi\xF3n 2'?",opciones:["Peligro constante en condiciones normales","Peligro presente solo por falla accidental","\xC1rea donde se fabrican los explosivos","\xC1rea que no requiere ning\xFAn tipo de tuber\xEDa"],respuesta_correcta:1,explicacion:"En Divisi\xF3n 2, los materiales inflamables est\xE1n confinados y solo representan peligro si hay una ruptura o mal funcionamiento."},{id:"et_174",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 tipo de cable de alarma de fuego es apto para uso en ductos de aire (Plenums)?",opciones:["Tipo FPL","Tipo FPLR","Tipo FPLP","Tipo NPLF"],respuesta_correcta:2,explicacion:"La letra 'P' al final (FPLP) indica que el cable es 'Plenum Rated', con aislamiento de bajo humo."},{id:"et_175",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es el color de los guantes de hule aislantes para trabajar en 480V (Clase 0)?",opciones:["Rojo","Amarillo","Blanco","Negro (etiqueta roja)"],respuesta_correcta:3,explicacion:"Los guantes Clase 0 est\xE1n certificados para 1,000V AC y se identifican por una etiqueta de color rojo en el pu\xF1o."},{id:"et_176",categoria:"ET_OHM_WATT",pregunta:"Si un motor de 1 HP tiene una eficiencia del 100%, \xBFcu\xE1nta potencia consume?",opciones:["550 Watts","746 Watts","1000 Watts","1200 Watts"],respuesta_correcta:1,explicacion:"Por definici\xF3n t\xE9cnica, un caballo de fuerza mec\xE1nico equivale a 746 Watts el\xE9ctricos."},{id:"et_177",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la corriente en un circuito de 240V que alimenta una carga de 10,000 Watts?",opciones:["20.8 Amperios","41.6 Amperios","52.4 Amperios","60.0 Amperios"],respuesta_correcta:1,explicacion:"I = P / V. 10,000 / 240 = 41.66 Amperios."},{id:"et_178",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa la palabra 'Shall' cuando aparece en un texto del NEC?",opciones:["Que la acci\xF3n es recomendada pero opcional","Que la acci\xF3n es de car\xE1cter obligatorio","Que la acci\xF3n depende del criterio del due\xF1o","Que la acci\xF3n solo aplica en grandes ciudades"],respuesta_correcta:1,explicacion:"En lenguaje de c\xF3digos y normas, 'Shall' indica un requisito mandatorio u obligatorio."},{id:"et_179",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es la secci\xF3n del NEC que define los requisitos para el etiquetado de tableros?",opciones:["110.16","110.21","110.24","110.26"],respuesta_correcta:1,explicacion:"La secci\xF3n 110.21 cubre los requisitos de marcado y advertencias de peligro en equipos el\xE9ctricos."},{id:"et_180",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 letra en un cable indica que tiene una cubierta de nylon?",opciones:["R","H","W","N"],respuesta_correcta:3,explicacion:"La 'N' al final (como en THHN) significa que el cable tiene una capa externa de Nylon para facilitar el deslizamiento."},{id:"et_181",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un cable #6 AWG de cobre tipo TW a 60\xB0C?",opciones:["40 Amperios","55 Amperios","65 Amperios","75 Amperios"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 310.16, el cable #6 de cobre en la columna de 60\xB0C tiene una ampacidad de 55A."},{id:"et_182",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura m\xEDnimo para un conduit RMC de 3/4 pulgada?",opciones:["4 pulgadas","4.5 pulgadas","5 pulgadas","6 pulgadas"],respuesta_correcta:1,explicacion:"El Cap\xEDtulo 9, Tabla 2 especifica un radio de 4.5 pulgadas para tuber\xEDa r\xEDgida de 3/4'."},{id:"et_183",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1ntos conductores 10 AWG caben en un EMT de 1/2 pulgada?",opciones:["3 conductores","4 conductores","5 conductores","6 conductores"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla C.1 del Anexo C, el m\xE1ximo permitido para 10 AWG THHN en EMT de 1/2' es de 4 conductores."},{id:"et_184",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la altura est\xE1ndar permitida para un recept\xE1culo en una pared?",opciones:["12 a 15 pulgadas","18 a 24 pulgadas","No hay una altura m\xEDnima por NEC","Exactamente a 48 pulgadas"],respuesta_correcta:2,explicacion:"El NEC no especifica una altura m\xEDnima o m\xE1xima para recept\xE1culos en paredes de uso general en viviendas."},{id:"et_185",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 circuito se requiere para alimentar un lavavajillas y un triturador de comida?",opciones:["Un solo circuito de 15A compartido","Un circuito de 20A compartido o dos individuales","Cualquier circuito de iluminaci\xF3n cercano","Deben conectarse a los circuitos de la encimera"],respuesta_correcta:1,explicacion:"Debido a la carga de los motores, se recomienda circuitos individuales o un circuito de 20A bien dimensionado."},{id:"et_186",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o de GEC de cobre se requiere para una tuber\xEDa de agua de 1 pulgada?",opciones:["#8 AWG","#6 AWG","#4 AWG","#2 AWG"],respuesta_correcta:1,explicacion:"El conductor del electrodo de tierra (GEC) conectado a una tuber\xEDa de agua suele ser de #6 AWG como m\xEDnimo."},{id:"et_187",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el despeje m\xEDnimo sobre un techo plano para conductores de acometada?",opciones:["3 pies","8 pies","10 pies","12 pies"],respuesta_correcta:1,explicacion:"NEC 230.24(A) requiere un despeje vertical de 8 pies sobre superficies de techos con pendientes menores a 4 en 12."},{id:"et_188",categoria:"ET_GROUNDING",pregunta:"\xBFC\xF3mo se identifica un conductor neutral mayor a #6 AWG?",opciones:["Con aislamiento blanco en toda su longitud","Marc\xE1ndolo con cinta blanca en los extremos","Con aislamiento gris \xFAnicamente","Usando un cable desnudo de cobre"],respuesta_correcta:1,explicacion:"Para calibres grandes (#4 y superiores), el NEC permite usar conductores negros marcados con cinta blanca en cada terminaci\xF3n."},{id:"et_189",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el prop\xF3sito del 'Bonding'?",opciones:["Crear una conexi\xF3n a la tierra profunda","Establecer continuidad el\xE9ctrica entre partes met\xE1licas","Reducir la factura el\xE9ctrica del cliente","Permitir que el neutral transporte m\xE1s corriente"],respuesta_correcta:1,explicacion:"Bonding es la uni\xF3n de todas las partes met\xE1licas no portadoras de corriente para asegurar que est\xE9n al mismo potencial."},{id:"et_190",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 indica la clasificaci\xF3n de voltaje en un fusible (ej. 250V)?",opciones:["El voltaje exacto al que el fusible se quemar\xE1","El voltaje m\xE1ximo del sistema donde puede usarse","La ca\xEDda de voltaje permitida a trav\xE9s del fusible","El voltaje que genera el fusible al funcionar"],respuesta_correcta:1,explicacion:"Un fusible de 250V no puede usarse en un sistema de 480V porque el arco generado al quemarse podr\xEDa no extinguirse."},{id:"et_191",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 distancia se puede aplicar la 'Tap Rule' de 10 pies?",opciones:["A cualquier distancia si el cable es grueso","Solo si el cable termina en un desconectador o breaker","Solo en instalaciones residenciales unifamiliares","Solo para alimentar transformadores de control"],respuesta_correcta:1,explicacion:"La regla de derivaci\xF3n de 10 pies exige que los conductores terminen en un dispositivo de sobrecorriente que limite la carga."},{id:"et_192",categoria:"ET_MOTORES",pregunta:"\xBFC\xF3mo se calcula la carga para un grupo de cuatro motores?",opciones:["Sumando las cuatro corrientes nominales","125% del motor m\xE1s grande + suma de los otros tres","125% de la suma de los cuatro motores","150% de la placa del motor m\xE1s peque\xF1o"],respuesta_correcta:1,explicacion:"NEC 430.24 requiere tomar el 125% de la FLC del motor m\xE1s grande y sumarle la FLC de todos los dem\xE1s motores del grupo."},{id:"et_193",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa un motor 'Totally Enclosed Fan Cooled' (TEFC)?",opciones:["Que el motor no tiene ventilador externo","Que el aire exterior no entra al interior del motor","Que el motor debe sumergirse en aceite para enfriar","Que el motor solo puede funcionar en climas fr\xEDos"],respuesta_correcta:1,explicacion:"En un motor TEFC, el aire de enfriamiento es soplado sobre la carcasa sellada, pero no entra en contacto con el bobinado."},{id:"et_194",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 sucede con el voltaje si conectamos un transformador de 480:120 al rev\xE9s?",opciones:["El transformador explotar\xE1 de inmediato","El voltaje de salida ser\xE1 de 1920 Voltios","El voltaje de salida ser\xE1 de 30 Voltios","El transformador no funcionar\xE1 en absoluto"],respuesta_correcta:1,explicacion:"Funcionar\xE1 como elevador (Step-up). La relaci\xF3n 4:1 invertida multiplicar\xE1 el voltaje de entrada por 4 (480 * 4 = 1920V)."},{id:"et_195",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 calibre m\xEDnimo de conductor de uni\xF3n se requiere para un transformador seco?",opciones:["#14 AWG cobre","#10 AWG cobre","Basado en la Tabla 250.102(C)(1)","Igual al tama\xF1o del cable de fase"],respuesta_correcta:2,explicacion:"El conductor de uni\xF3n del lado de la fuente se dimensiona seg\xFAn el tama\xF1o de los conductores de fase del secundario."},{id:"et_196",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la profundidad m\xEDnima de una caja de salida para una luminaria?",opciones:["1/4 pulgada","1/2 pulgada","1 pulgada","1-1/2 pulgadas"],respuesta_correcta:1,explicacion:"NEC 314.24 especifica que las cajas que contienen conductores no deben tener una profundidad interna menor a 1/2'."},{id:"et_197",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 tipo de portal\xE1mparas se requiere en \xE1reas de almacenamiento comercial?",opciones:["Cualquier base de pl\xE1stico econ\xF3mica","Base de porcelana con guarda protectora","Luminarias fluorescentes sin balasto","Focos LED tipo 'pigtail' colgantes"],respuesta_correcta:1,explicacion:"Para evitar la rotura accidental de bombillas y posibles incendios, se requieren luminarias con protecci\xF3n f\xEDsica."},{id:"et_198",categoria:"ET_HAZARDOUS",pregunta:"\xBFCu\xE1l es la funci\xF3n del compuesto 'Chico' en un sello de conduit?",opciones:["Lubricar los cables para que pasen m\xE1s f\xE1cil","Endurecerse para bloquear el paso de llamas y gases","Proteger la tuber\xEDa contra la corrosi\xF3n \xE1cida","Identificar que el trabajo fue inspeccionado"],respuesta_correcta:1,explicacion:"'Chico' es una marca com\xFAn de compuesto de sellado que crea una barrera f\xEDsica impenetrable para gases inflamables."},{id:"et_199",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1ntas veces el di\xE1metro del cable debe ser el radio de curvatura en cable coaxial?",opciones:["5 veces el di\xE1metro","10 veces el di\xE1metro","15 veces el di\xE1metro","20 veces el di\xE1metro"],respuesta_correcta:1,explicacion:"Para cables de comunicaci\xF3n y baja tensi\xF3n, un radio de 10 veces el di\xE1metro evita la p\xE9rdida de se\xF1al y da\xF1o f\xEDsico."},{id:"et_200",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es el l\xEDmite de voltaje para considerar un circuito como de 'bajo voltaje'?",opciones:["24 Voltios","50 Voltios","120 Voltios","600 Voltios"],respuesta_correcta:1,explicacion:"OSHA y el NEC suelen establecer los 50V como el umbral donde el riesgo de choque el\xE9ctrico requiere medidas de protecci\xF3n mayores."},{id:"et_201",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la resistencia de un motor que consume 10 Amperios cuando se conecta a una l\xEDnea de 240V?",opciones:["2.4 Ohmios","24 Ohmios","240 Ohmios","2400 Ohmios"],respuesta_correcta:1,explicacion:"Seg\xFAn la ley de Ohm, R = V / I. Por lo tanto, 240V / 10A = 24 Ohmios."},{id:"et_202",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos Watts consume un calentador el\xE9ctrico de agua que tiene una resistencia de 12 Ohmios a 240V?",opciones:["2000 Watts","2880 Watts","4800 Watts","5760 Watts"],respuesta_correcta:2,explicacion:"P = V\xB2 / R. Entonces: 240 * 240 / 12 = 57,600 / 12 = 4800 Watts."},{id:"et_203",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC regula la instalaci\xF3n de equipos de aire acondicionado y refrigeraci\xF3n?",opciones:["Art\xEDculo 422","Art\xEDculo 430","Art\xEDculo 440","Art\xEDculo 450"],respuesta_correcta:2,explicacion:"El Art\xEDculo 440 es espec\xEDfico para equipos que contienen compresores herm\xE9ticos de motor-refrigerante."},{id:"et_204",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es la profundidad m\xEDnima de espacio de trabajo para un equipo de 480V con partes vivas expuestas frente a una pared de ladrillo?",opciones:["3 pies (90 cm)","3.5 pies (1.1 m)","4 pies (1.2 m)","5 pies (1.5 m)"],respuesta_correcta:1,explicacion:"Bajo la Condici\xF3n 2 de la Tabla 110.26(A)(1), para sistemas de 151-600V frente a superficies puestas a tierra (ladrillo/concreto), se requieren 3.5 pies."},{id:"et_205",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa el sufijo '-2' en un cable con aislamiento tipo XHHW-2?",opciones:["Que el cable tiene dos conductores internos","Que es apto para 90\xB0C en seco y mojado","Que requiere doble protecci\xF3n de tuber\xEDa","Que solo puede usarse en circuitos de Clase 2"],respuesta_correcta:1,explicacion:"El '-2' indica que el aislamiento mantiene su clasificaci\xF3n de 90\xB0C tanto en ubicaciones secas como mojadas."},{id:"et_206",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un conductor #1 AWG de cobre THHN a 75\xB0C?",opciones:["110 Amperios","130 Amperios","150 Amperios","170 Amperios"],respuesta_correcta:1,explicacion:"Consultando la Tabla 310.16, el cable #1 AWG de cobre en la columna de 75\xB0C tiene una capacidad de 130A."},{id:"et_207",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el n\xFAmero m\xE1ximo de conductores 14 AWG permitidos en una caja met\xE1lica de 4 x 2-1/8 x 1-1/2 (10.3 cu in)?",opciones:["3 conductores","5 conductores","7 conductores","8 conductores"],respuesta_correcta:1,explicacion:"Cada 14 AWG requiere 2.0 cu in. 10.3 / 2.0 = 5.15. El m\xE1ximo permitido son 5 conductores."},{id:"et_208",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 tipo de tuber\xEDa no met\xE1lica es resistente a la luz solar y puede usarse a la intemperie?",opciones:["PVC C\xE9dula 40 marcado 'Sunlight Resistant'","Tuber\xEDa el\xE9ctrica no met\xE1lica (ENT) azul","Conducto de fibra \xF3ptica de polietileno","Tuber\xEDa de PVC para plomer\xEDa est\xE1ndar"],respuesta_correcta:0,explicacion:"El PVC para uso el\xE9ctrico debe estar espec\xEDficamente marcado como resistente a la luz solar si se instala expuesto al sol."},{id:"et_209",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga m\xEDnima para un circuito derivado de 20A que alimenta una lavander\xEDa?",opciones:["1200 VA","1500 VA","1800 VA","2400 VA"],respuesta_correcta:1,explicacion:"NEC 220.52(B) requiere un c\xE1lculo de al menos 1500 VA para el circuito derivado de la lavander\xEDa."},{id:"et_210",categoria:"ET_CIRCUITOS",pregunta:"\xBFEn qu\xE9 lugar de una vivienda NO se requiere protecci\xF3n GFCI para recept\xE1culos de 125V?",opciones:["\xC1reas de rastreo (Crawl spaces)","Cobertizos de herramientas (Sheds)","Dormitorios cerca de las ventanas","Debajo de los fregaderos de cocina"],respuesta_correcta:2,explicacion:"Los dormitorios requieren protecci\xF3n AFCI, pero no GFCI a menos que el recept\xE1culo est\xE9 a menos de 6 pies de un fregadero."},{id:"et_211",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 dispositivo debe ser capaz de desconectar todos los conductores de un edificio de la fuente de suministro?",opciones:["El breaker de la unidad de aire acondicionado","El medio de desconexi\xF3n del servicio (Main Service)","El interruptor de transferencia del generador","Cualquier breaker de 20A en el panel principal"],respuesta_correcta:1,explicacion:"El Art\xEDculo 230.70 exige un medio para desconectar todos los conductores del edificio de los conductores de entrada de servicio."},{id:"et_212",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es la longitud m\xE1xima del conductor de entrada de servicio antes del desconectador principal?",opciones:["3 pies (90 cm)","6 pies (1.8 m)","10 pies (3.0 m)","Debe ser lo m\xE1s corto posible (AHJ decide)"],respuesta_correcta:3,explicacion:"El NEC no especifica una medida en pies, indicando que debe estar en una ubicaci\xF3n 'inmediatamente adyacente' al punto de entrada."},{id:"et_213",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de un electrodo de tuber\xEDa de metal (Pipe Electrode)?",opciones:["1/2 pulgada","3/4 pulgada","1 pulgada","2 pulgadas"],respuesta_correcta:1,explicacion:"NEC 250.52(A)(5) establece que los electrodos de tuber\xEDa o conducto no deben ser menores a 3/4 de pulgada de di\xE1metro comercial."},{id:"et_214",categoria:"ET_GROUNDING",pregunta:"\xBFC\xF3mo se debe conectar el conductor de puesta a tierra (EGC) a una caja met\xE1lica?",opciones:["Enred\xE1ndolo firmemente en un tornillo de montaje","Usando un tornillo de puesta a tierra verde listado","Sold\xE1ndolo directamente a la parte trasera de la caja","Sujet\xE1ndolo con cinta aislante a la tuber\xEDa"],respuesta_correcta:1,explicacion:"El Art\xEDculo 250.148 requiere que la conexi\xF3n a la caja se haga con un tornillo de puesta a tierra identificado o un dispositivo listado."},{id:"et_215",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el amperaje est\xE1ndar m\xE1ximo para un fusible tipo tap\xF3n (Plug Fuse) Edison?",opciones:["15 Amperios","20 Amperios","30 Amperios","50 Amperios"],respuesta_correcta:2,explicacion:"Los fusibles de tipo tap\xF3n est\xE1n limitados por el NEC a un m\xE1ximo de 30 amperios y 125 voltios."},{id:"et_216",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 letra identifica a un breaker dise\xF1ado para proteger motores de alta eficiencia con picos de arranque?",opciones:["Clase A","Clase B","Tipo HACR","Tipo SWD"],respuesta_correcta:2,explicacion:"Los breakers marcados como 'HACR' est\xE1n listados para su uso en equipos de calefacci\xF3n, aire acondicionado y refrigeraci\xF3n."},{id:"et_217",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje se ajusta la protecci\xF3n contra cortocircuito para un motor usando un breaker de tiempo inverso?",opciones:["125%","150%","250%","400%"],respuesta_correcta:2,explicacion:"La Tabla 430.52 permite un ajuste m\xE1ximo inicial del 250% de la FLC del motor para breakers de tiempo inverso."},{id:"et_218",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'FLA' en un compresor de refrigeraci\xF3n?",opciones:["Full Load Amperes","Fixed Load Amperes","Fan Load Amperes","Frequency Level Amperes"],respuesta_correcta:0,explicacion:"FLA se refiere a la corriente m\xE1xima que el motor est\xE1 dise\xF1ado para drenar bajo su carga nominal completa."},{id:"et_219",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es la corriente del secundario de un transformador de 75 KVA trif\xE1sico a 208V?",opciones:["208 Amperios","225 Amperios","208.2 Amperios","208.4 Amperios"],respuesta_correcta:2,explicacion:"I = VA / (V * \u221A3). Calculamos: 75,000 / (208 * 1.732) = 208.18 Amperios."},{id:"et_220",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es la distancia m\xEDnima de espacio libre frente a un transformador seco de 600V?",opciones:["24 pulgadas","30 pulgadas","36 pulgadas","48 pulgadas"],respuesta_correcta:2,explicacion:"Seg\xFAn NEC 110.26, el espacio de trabajo frontal para equipos de hasta 600V debe ser de al menos 3 pies (36 pulgadas)."},{id:"et_221",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 carga de VA se asigna a cada salida de iluminaci\xF3n en un edificio comercial si no se conoce la luminaria?",opciones:["60 VA","100 VA","180 VA","No se permite si no se conoce la carga"],respuesta_correcta:2,explicacion:"Para salidas de uso general en instalaciones comerciales, se calculan 180 VA por salida seg\xFAn NEC 220.14(I)."},{id:"et_222",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la separaci\xF3n m\xEDnima para conductores de luminarias de descarga de alta intensidad?",opciones:["1/4 pulgada","1/2 pulgada","1 pulgada","6 pulgadas"],respuesta_correcta:0,explicacion:"El Art\xEDculo 410 requiere separaciones f\xEDsicas para evitar la inducci\xF3n y el calor excesivo en los cables de alimentaci\xF3n."},{id:"et_223",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 tipo de sello es obligatorio cuando el conduit entra en un recinto que contiene chispas en Clase I?",opciones:["Sello de caucho expandible","Sello hidr\xE1ulico de aceite","Sello contra explosi\xF3n (Sealing Fitting)","Sello de silicona tipo calafateo"],respuesta_correcta:2,explicacion:"NEC 501.15 requiere sellos para evitar que las explosiones internas se propaguen a trav\xE9s del sistema de tuber\xEDas."},{id:"et_224",categoria:"ET_BAJA_TENSION",pregunta:"\xBFA qu\xE9 distancia m\xE1xima deben estar soportados los cables de control Clase 2 sobre una estructura?",opciones:["Cada 2 pies","Cada 4.5 pies","Cada 10 pies","No requieren soporte espec\xEDfico"],respuesta_correcta:1,explicacion:"Aunque son de baja tensi\xF3n, deben instalarse de manera profesional y soportarse a intervalos similares a los cables de potencia (4.5 pies)."},{id:"et_225",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa el 'Approach Boundary' para un electricista?",opciones:["La distancia m\xE1xima donde puede estar un civil sin casco","La distancia m\xEDnima para evitar un choque el\xE9ctrico o arco","La zona donde es obligatorio usar guantes de hule","El \xE1rea donde se permite comer y beber en la obra"],respuesta_correcta:1,explicacion:"Define las zonas de seguridad alrededor de partes vivas para prevenir contacto accidental o lesiones por arco el\xE9ctrico."},{id:"et_226",categoria:"ET_OHM_WATT",pregunta:"Si un circuito tiene 480V y una potencia de 12,000W, \xBFcu\xE1l es la corriente?",opciones:["20 Amperios","25 Amperios","40 Amperios","50 Amperios"],respuesta_correcta:1,explicacion:"I = P / V. Entonces: 12,000 / 480 = 25 Amperios."},{id:"et_227",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la potencia de un motor de 120V que drena 12A con un factor de potencia del 80%?",opciones:["1152 Watts","1440 Watts","1800 Watts","2000 Watts"],respuesta_correcta:0,explicacion:"P = V * I * FP. Entonces: 120 * 12 * 0.80 = 1152 Watts."},{id:"et_228",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 cap\xEDtulo del NEC trata sobre 'Condiciones Especiales' como sistemas de emergencia?",opciones:["Cap\xEDtulo 5","Cap\xEDtulo 6","Cap\xEDtulo 7","Cap\xEDtulo 8"],respuesta_correcta:2,explicacion:"El Cap\xEDtulo 7 cubre sistemas de emergencia, sistemas de potencia de reserva legalmente requeridos y otros sistemas especiales."},{id:"et_229",categoria:"ET_NEC",pregunta:"\xBFQui\xE9n es la autoridad final para interpretar las reglas del NEC en una obra?",opciones:["El arquitecto dise\xF1ador","El contratista el\xE9ctrico","La Autoridad con Jurisdicci\xF3n (AHJ)","El fabricante del equipo"],respuesta_correcta:2,explicacion:"La AHJ (usualmente el inspector el\xE9ctrico local) tiene la responsabilidad legal de interpretar y aplicar el c\xF3digo."},{id:"et_230",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 tipo de cable est\xE1 permitido para ser enterrado directamente en la tierra?",opciones:["Tipo THHN","Tipo NM-B","Tipo UF-B","Tipo TW"],respuesta_correcta:2,explicacion:"El cable tipo UF-B (Underground Feeder) est\xE1 dise\xF1ado con una chaqueta resistente a la humedad y corrosi\xF3n para entierro directo."},{id:"et_231",categoria:"ET_CONDUCTORES",pregunta:"\xBFA qu\xE9 porcentaje de ampacidad se reduce un cable si se instala en un \xE1rea con 40\xB0C de temperatura ambiente?",opciones:["100%","91%","82%","71%"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 310.15(B)(1), para conductores de 90\xB0C a una temperatura de 40\xB0C (104\xB0F), el factor es 0.91."},{id:"et_232",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es la profundidad m\xEDnima de cobertura para un cable UF bajo una entrada de auto residencial?",opciones:["12 pulgadas","18 pulgadas","24 pulgadas","30 pulgadas"],respuesta_correcta:1,explicacion:"La Tabla 300.5 requiere 18 pulgadas de profundidad para cables de enterramiento directo bajo entradas de autos residenciales."},{id:"et_233",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1ntos conductores 10 AWG THHN se permiten en un conduit EMT de 3/4 de pulgada?",opciones:["6 conductores","10 conductores","12 conductores","16 conductores"],respuesta_correcta:1,explicacion:"Consultando el Anexo C, Tabla C.1, el m\xE1ximo permitido para 10 AWG THHN en EMT de 3/4 es de 10 conductores."},{id:"et_234",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para una estufa el\xE9ctrica de 10 kW en una vivienda?",opciones:["8,000 VA","10,000 VA","12,000 VA","15,000 VA"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 220.55, para una sola estufa de entre 9 y 12 kW, se permite usar una carga de demanda de 8 kW (8,000 VA)."},{id:"et_235",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 circuito se requiere para los recept\xE1culos de la encimera de la cocina (Small Appliance)?",opciones:["Uno de 15A de uso general","Dos o m\xE1s de 20A dedicados","Uno de 30A para electrodom\xE9sticos pesados","Cualquier circuito que alimente las luces"],respuesta_correcta:1,explicacion:"NEC 210.11(C)(1) requiere al menos dos circuitos derivados de 20 amperios para los electrodom\xE9sticos de la cocina."},{id:"et_236",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es la distancia m\xEDnima de los conductores de acometida sobre una piscina?",opciones:["12.5 pies","18 pies","22.5 pies","25 pies"],respuesta_correcta:2,explicacion:"NEC 680.9 requiere un despeje vertical de al menos 22.5 pies en todas las direcciones sobre el nivel del agua de la piscina."},{id:"et_237",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o m\xEDnimo de cable de cobre se requiere para un servicio residencial de 200A?",opciones:["2/0 AWG","3/0 AWG","4/0 AWG","250 kcmil"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 310.12, un servicio de 200A para una vivienda requiere conductores de fase de cobre calibre 2/0 AWG."},{id:"et_238",categoria:"ET_GROUNDING",pregunta:"\xBFA qu\xE9 distancia m\xE1xima de la entrada de la tuber\xEDa de agua fr\xEDa debe conectarse el GEC?",opciones:["3 pies (90 cm)","5 pies (1.5 m)","10 pies (3.0 m)","Cualquier punto accesible de la tuber\xEDa"],respuesta_correcta:1,explicacion:"NEC 250.52(A)(1) requiere que la conexi\xF3n a la tuber\xEDa de agua met\xE1lica se realice dentro de los primeros 5 pies desde la entrada."},{id:"et_239",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 tama\xF1o de EGC de aluminio se requiere para un circuito de 100A?",opciones:["#8 AWG","#6 AWG","#4 AWG","#2 AWG"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 250.122, para un breaker de 100A se requiere un conductor de tierra de equipo de #4 AWG si es de aluminio."},{id:"et_240",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es la funci\xF3n de un breaker tipo AFCI?",opciones:["Proteger contra electrocuci\xF3n por contacto con agua","Detectar fallas de arco el\xE9ctrico que causan incendios","Evitar que el motor se queme por sobrecarga","Cortar la energ\xEDa si el voltaje baja de 100V"],respuesta_correcta:1,explicacion:"El Arc-Fault Circuit Interrupter detecta arcos peligrosos y abre el circuito para prevenir incendios en el cableado."},{id:"et_241",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 porcentaje se debe cargar un circuito derivado si la carga es continua?",opciones:["80%","100%","125%","150%"],respuesta_correcta:0,explicacion:"Por regla general, la carga no debe exceder el 80% de la capacidad del circuito si funciona por m\xE1s de 3 horas."},{id:"et_242",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla del NEC se usa para encontrar la FLC de un motor monof\xE1sico de 120V?",opciones:["Tabla 430.247","Tabla 430.248","Tabla 430.250","Tabla 430.52"],respuesta_correcta:1,explicacion:"La Tabla 430.248 proporciona los valores de corriente para motores monof\xE1sicos de corriente alterna."},{id:"et_243",categoria:"ET_MOTORES",pregunta:"\xBFCu\xE1l es la altura m\xE1xima permitida para el centro de la palanca de un desconectador?",opciones:["4 pies (1.2 m)","5 pies (1.5 m)","6 pies 7 pulgadas (2.0 m)","Sin l\xEDmite de altura"],respuesta_correcta:2,explicacion:"NEC 404.8(A) establece que el centro de la palanca de operaci\xF3n no debe estar a m\xE1s de 6 pies 7 pulgadas sobre el piso."},{id:"et_244",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 es un autotransformador?",opciones:["Un transformador que se enciende solo con un timer","Un transformador con un solo devanado com\xFAn para primario y secundario","Un transformador dise\xF1ado para uso exclusivo en autom\xF3viles","Un transformador que no requiere puesta a tierra"],respuesta_correcta:1,explicacion:"Un autotransformador utiliza una sola bobina donde una parte act\xFAa como primario y el total (o parte) como secundario."},{id:"et_245",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es el voltaje fase-fase en un sistema Wye de 480/277V?",opciones:["120 Voltios","208 Voltios","240 Voltios","480 Voltios"],respuesta_correcta:3,explicacion:"En este sistema, 480V es el voltaje entre fases y 277V es el voltaje de cada fase con respecto al neutral."},{id:"et_246",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga calculada para una luminaria de descarga (HID) de 400W?",opciones:["400 VA","450 VA","500 VA","Basada en el amperaje nominal del balasto"],respuesta_correcta:3,explicacion:"Para luminarias con balasto, la carga se basa en la corriente nominal del balasto, no solo en los Watts de la bombilla."},{id:"et_247",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 distancia de un recept\xE1culo debe estar una luminaria en una tina de ba\xF1o?",opciones:["Al menos 1 pie","Al menos 3 pies","Al menos 8 pies","No se permiten luminarias sobre tinas"],respuesta_correcta:1,explicacion:"NEC 410.10(D) proh\xEDbe partes de luminarias colgantes dentro de una zona de 3 pies horizontales y 8 pies verticales de la tina."},{id:"et_248",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 clase define una ubicaci\xF3n con polvos combustibles?",opciones:["Clase I","Clase II","Clase III","Clase IV"],respuesta_correcta:1,explicacion:"La Clase II se refiere a \xE1reas con riesgos de explosi\xF3n debido a polvos combustibles como granos o qu\xEDmicos en polvo."},{id:"et_249",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 calibre m\xEDnimo se permite para cables de extensi\xF3n en equipos industriales?",opciones:["18 AWG","16 AWG","14 AWG","12 AWG"],respuesta_correcta:0,explicacion:"El Art\xEDculo 400 permite calibres tan peque\xF1os como 18 AWG para cordones flexibles de equipos espec\xEDficos."},{id:"et_250",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Safety Grounding' durante el mantenimiento de alta tensi\xF3n?",opciones:["Mejorar el factor de potencia del sistema","Descargar capacitancia y proteger contra energizaci\xF3n accidental","Reducir el ruido magn\xE9tico en los cables de control","Evitar que las herramientas se caigan al suelo"],respuesta_correcta:1,explicacion:"Las tierras de seguridad se colocan para crear un cortocircuito a tierra que proteja al t\xE9cnico si alguien enciende la energ\xEDa."},{id:"et_251",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos miliamperios hay en 2.5 Amperios?",opciones:["25 mA","250 mA","2500 mA","25000 mA"],respuesta_correcta:2,explicacion:"1 Amperio = 1000 mA. Entonces: 2.5 * 1000 = 2500 mA."},{id:"et_252",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es el costo de operar una carga de 5kW por 10 horas si el kWh cuesta $0.10?",opciones:["$0.50","$5.00","$10.00","$50.00"],respuesta_correcta:1,explicacion:"Costo = Potencia * Tiempo * Tarifa. Entonces: 5kW * 10h * 0.10 = $5.00."},{id:"et_253",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 tabla se usa para dimensionar el conductor neutral basado en la carga desequilibrada?",opciones:["Tabla 220.55","Tabla 250.66","Tabla 310.16","Reglas del Art\xEDculo 220.61"],respuesta_correcta:3,explicacion:"El Art\xEDculo 220.61 proporciona el m\xE9todo de c\xE1lculo para la carga m\xE1xima desequilibrada del neutral."},{id:"et_254",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para el cual se aplica el Art\xEDculo 300?",opciones:["120 Voltios","600 Voltios","1000 Voltios","5000 Voltios"],respuesta_correcta:2,explicacion:"La mayor\xEDa de los requisitos generales de m\xE9todos de cableado en el Art\xEDculo 300 aplican hasta 1000V nominales."},{id:"et_255",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la letra 'H' en un aislamiento de conductor?",opciones:["Resistente a la humedad (Humidity)","Resistente al calor hasta 75\xB0C (Heat)","Resistente al hidr\xF3geno (Hydrogen)","Cable de alta tensi\xF3n (High voltage)"],respuesta_correcta:1,explicacion:"La 'H' indica resistencia al calor hasta 75\xB0C. 'HH' indica resistencia hasta 90\xB0C."},{id:"et_256",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un cable 3/0 AWG de cobre THWN-2 a 90\xB0C?",opciones:["175 Amperios","200 Amperios","225 Amperios","250 Amperios"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.16, el cable 3/0 de cobre en la columna de 90\xB0C tiene una ampacidad de 225A."},{id:"et_257",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el soporte m\xE1ximo permitido para una tuber\xEDa de PVC de 1/2 pulgada?",opciones:["Cada 2 pies","Cada 3 pies","Cada 5 pies","Cada 10 pies"],respuesta_correcta:1,explicacion:"Para PVC de 1/2 a 1 pulgada, el Art\xEDculo 352.30(A) requiere soportes a intervalos de no m\xE1s de 3 pies."},{id:"et_258",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1ntos conductores 12 AWG THHN caben en una tuber\xEDa EMT de 1/2 pulgada?",opciones:["6 conductores","9 conductores","12 conductores","15 conductores"],respuesta_correcta:1,explicacion:"Consultando el Anexo C, Tabla C.1, el m\xE1ximo permitido para 12 AWG THHN en EMT de 1/2 es de 9 conductores."},{id:"et_259",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 carga de VA se usa para un recept\xE1culo de vitrina comercial por cada pie lineal?",opciones:["90 VA","180 VA","200 VA","360 VA"],respuesta_correcta:2,explicacion:"NEC 220.14(E) requiere calcular 200 VA por cada pie (300 mm) de vitrina de exhibici\xF3n (Show Window)."},{id:"et_260",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es el requisito de GFCI para un recept\xE1culo en un s\xF3tano no terminado?",opciones:["Solo si est\xE1 cerca de la lavander\xEDa","Solo si el piso est\xE1 mojado","Es obligatorio para todos los recept\xE1culos","No se requiere si hay un congelador conectado"],respuesta_correcta:2,explicacion:"NEC 210.8(A)(5) exige protecci\xF3n GFCI para todos los recept\xE1culos de 125V en s\xF3tanos no terminados."},{id:"et_261",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de los conductores de entrada de servicio para una carga de 15A?",opciones:["#14 AWG","#12 AWG","#10 AWG","#8 AWG"],respuesta_correcta:3,explicacion:"NEC 230.79(A) establece que para cargas limitadas de un solo circuito, los conductores no deben ser menores a #8 AWG cobre."},{id:"et_262",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 color de cinta se usa para identificar la fase B en un sistema de 480V?",opciones:["Negro","Rojo","Naranja","P\xFArpura"],respuesta_correcta:2,explicacion:"Aunque no es mandatorio en todo el c\xF3digo, la pr\xE1ctica est\xE1ndar y el requisito para sistemas Delta es usar naranja para la fase B (High-Leg)."},{id:"et_263",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el calibre m\xEDnimo de un GEC de cobre conectado a un electrodo de varilla?",opciones:["#10 AWG","#8 AWG","#6 AWG","#4 AWG"],respuesta_correcta:2,explicacion:"NEC 250.66(A) indica que el conductor que va a una varilla de tierra no necesita ser mayor a #6 AWG de cobre."},{id:"et_264",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 significa un sistema de puesta a tierra 'Solidly Grounded'?",opciones:["Que tiene mucha tierra f\xEDsica alrededor del edificio","Que el neutral est\xE1 conectado directamente a tierra sin resistencia","Que la conexi\xF3n se hizo con soldadura exot\xE9rmica s\xF3lida","Que el sistema est\xE1 protegido contra rayos intensos"],respuesta_correcta:1,explicacion:"Significa que el conductor puesto a tierra est\xE1 conectado intencionalmente a la tierra sin insertar ninguna resistencia o impedancia."},{id:"et_265",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el amperaje est\xE1ndar que sigue despu\xE9s de 200 Amperios en breakers?",opciones:["210 Amperios","225 Amperios","250 Amperios","300 Amperios"],respuesta_correcta:1,explicacion:"La Tabla 240.6(A) muestra que el siguiente tama\xF1o est\xE1ndar despu\xE9s de 200A es 225A."},{id:"et_266",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 tipo de breaker protege contra el arco que ocurre cuando un cable se da\xF1a dentro de la pared?",opciones:["GFCI","AFCI","OCPD","GFI"],respuesta_correcta:1,explicacion:"El AFCI (Arc-Fault Circuit Interrupter) est\xE1 dise\xF1ado para detectar arcos serie y paralelos causados por conductores da\xF1ados."},{id:"et_267",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje se calcula el desconectador de un motor basado en su HP?",opciones:["100%","115%","125%","150%"],respuesta_correcta:1,explicacion:"NEC 430.110(A) requiere que el medio de desconexi\xF3n tenga una clasificaci\xF3n de al menos el 115% de la corriente de plena carga."},{id:"et_268",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla del NEC se usa para encontrar la corriente de rotor bloqueado?",opciones:["Tabla 430.250","Tabla 430.251(B)","Tabla 430.52","Tabla 9 Cap\xEDtulo 9"],respuesta_correcta:1,explicacion:"La Tabla 430.251(B) proporciona los valores de corriente de rotor bloqueado para motores trif\xE1sicos."},{id:"et_269",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 voltaje hay entre una fase y el neutral en un sistema trif\xE1sico 'Delta' con High-Leg?",opciones:["120V y 208V","120V y 240V","208V y 240V","120V \xFAnicamente"],respuesta_correcta:0,explicacion:"En un sistema Delta de 120/240V, dos fases dan 120V al neutral y la tercera (High-Leg) da 208V al neutral."},{id:"et_270",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 art\xEDculo del NEC proh\xEDbe el uso de agua para enfriar transformadores secos?",opciones:["Art\xEDculo 430","Art\xEDculo 440","Art\xEDculo 450","Art\xEDculo 680"],respuesta_correcta:2,explicacion:"El Art\xEDculo 450 detalla los m\xE9todos de enfriamiento permitidos para transformadores, que usualmente son aire o aceite diel\xE9ctrico."},{id:"et_271",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la separaci\xF3n m\xEDnima para una luminaria LED empotrada de un material combustible?",opciones:["1/4 pulgada","1/2 pulgada","1 pulgada","3 pulgadas"],respuesta_correcta:1,explicacion:"A menos que sea tipo IC (Insulation Contact), se requiere un despeje de 1/2 pulgada de materiales combustibles."},{id:"et_272",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1ntos VA se calculan por cada 5 pies de riel de iluminaci\xF3n comercial?",opciones:["450 VA","750 VA","900 VA","1500 VA"],respuesta_correcta:1,explicacion:"NEC 220.43(B) requiere 150 VA por cada 2 pies de riel. 5 pies / 2 = 2.5. 2.5 * 150 = 375 VA (pero en total comercial se suma por tramos)."},{id:"et_273",categoria:"ET_HAZARDOUS",pregunta:"\xBFEn qu\xE9 clasificaci\xF3n se incluyen las gasolineras (Service Stations)?",opciones:["Clase I, Divisi\xF3n 1 y 2","Clase II, Divisi\xF3n 1 \xFAnicamente","Clase III, Divisi\xF3n 2 \xFAnicamente","Ubicaciones ordinarias con GFCI"],respuesta_correcta:0,explicacion:"Las \xE1reas de despacho de combustible y tanques son Clase I debido a los vapores inflamables de la gasolina."},{id:"et_274",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para un sistema de timbre residencial?",opciones:["12 Voltios","24 Voltios","50 Voltios","120 Voltios"],respuesta_correcta:1,explicacion:"Los sistemas de timbre y termostatos residenciales suelen ser Clase 2 y operan a un m\xE1ximo de 24V-30V."},{id:"et_275",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa 'GFCI'?",opciones:["General Fuse Circuit Indicator","Ground Fault Circuit Interrupter","Grid Flow Control Instrument","Graphic Frequency Current Interrupter"],respuesta_correcta:1,explicacion:"El interruptor de falla a tierra protege a las personas detectando fugas de corriente de apenas 5 miliamperios."},{id:"et_276",categoria:"ET_OHM_WATT",pregunta:"Si la potencia es 2400W y el voltaje es 240V, \xBFcu\xE1l es la resistencia?",opciones:["10 Ohmios","24 Ohmios","48 Ohmios","100 Ohmios"],respuesta_correcta:1,explicacion:"R = V\xB2 / P. Entonces: 240 * 240 / 2400 = 57600 / 2400 = 24 Ohmios."},{id:"et_277",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos HP genera un motor de 1492 Watts?",opciones:["1 HP","1.5 HP","2 HP","3 HP"],respuesta_correcta:2,explicacion:"1 HP = 746 Watts. 1492 / 746 = 2 HP."},{id:"et_278",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Approved' seg\xFAn el Art\xEDculo 100?",opciones:["Que el equipo es el m\xE1s barato disponible","Que es aceptable para la autoridad con jurisdicci\xF3n","Que el due\xF1o de la casa dio permiso de instalarlo","Que el plano fue dibujado con computadora"],respuesta_correcta:1,explicacion:"'Approved' significa que la AHJ considera el equipo o instalaci\xF3n aceptable bajo los est\xE1ndares del c\xF3digo."},{id:"et_279",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el voltaje nominal de un sistema identificado como 120/240V?",opciones:["120 Voltios","240 Voltios","600 Voltios","No tiene un solo valor nominal"],respuesta_correcta:1,explicacion:"El voltaje nominal se refiere al valor asignado al sistema, que en este caso es el voltaje mayor (240V) entre conductores."},{id:"et_280",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 color de aislamiento identifica a un conductor puesto a tierra de calibre #4 AWG?",opciones:["Blanco s\xF3lido o gris","Cinta blanca en los extremos","Verde con franja amarilla","Cualquier color excepto negro"],respuesta_correcta:1,explicacion:"Conductores mayores a #6 pueden ser negros e identificarse permanentemente con blanco o gris en las terminaciones."},{id:"et_281",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un conductor #12 AWG de cobre THWN a 75\xB0C?",opciones:["15 Amperios","20 Amperios","25 Amperios","30 Amperios"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.16, el cable #12 de cobre en la columna de 75\xB0C tiene una ampacidad de 25A."},{id:"et_282",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura para un conduit de PVC de 1 pulgada?",opciones:["4.5 pulgadas","5.75 pulgadas","8.25 pulgadas","10 pulgadas"],respuesta_correcta:1,explicacion:"El Cap\xEDtulo 9, Tabla 2 especifica un radio de 5.75 pulgadas para tuber\xEDa de PVC de 1 pulgada."},{id:"et_283",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el porcentaje m\xE1ximo de llenado para 3 conductores en una canalizaci\xF3n?",opciones:["31%","40%","53%","60%"],respuesta_correcta:1,explicacion:"Para 3 o m\xE1s conductores, el \xE1rea ocupada no debe superar el 40% del \xE1rea interna de la tuber\xEDa."},{id:"et_284",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para un calentador de agua de 4500W?",opciones:["4500 VA","5625 VA","6000 VA","9000 VA"],respuesta_correcta:0,explicacion:"Las cargas resistivas como calentadores de agua se calculan a su potencia nominal. 4500W = 4500 VA."},{id:"et_285",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 distancia m\xE1xima puede haber entre recept\xE1culos en una vitrina de exhibici\xF3n?",opciones:["6 pies","12 pies","Debe haber uno cada 12 pies lineales","No hay una distancia m\xE1xima"],respuesta_correcta:2,explicacion:"NEC 210.62 requiere al menos un recept\xE1culo por cada 12 pies lineales de vitrina de exhibici\xF3n."},{id:"et_286",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o de GEC de aluminio se requiere para un servicio de 400A?",opciones:["#1/0 AWG","#2/0 AWG","#3/0 AWG","#4/0 AWG"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 250.66, para conductores de fase de aluminio de 500-600 kcmil, se requiere un GEC de aluminio #2/0."},{id:"et_287",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el despeje vertical m\xEDnimo sobre una acera peatonal para cables de servicio?",opciones:["8 pies","10 pies","12 pies","15 pies"],respuesta_correcta:1,explicacion:"NEC 230.24(B)(1) requiere un despeje de 10 pies para conductores de entrada de servicio sobre \xE1reas peatonales."},{id:"et_288",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 color est\xE1 prohibido para el aislamiento de un conductor de fase?",opciones:["Rojo","Verde","Azul","Naranja"],respuesta_correcta:1,explicacion:"El color verde est\xE1 estrictamente reservado para los conductores de puesta a tierra de equipos (EGC)."},{id:"et_289",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Main Bonding Jumper'?",opciones:["Conectar el panel a la varilla de tierra","Unir el neutral y la tierra en el servicio principal","Proteger los breakers contra cortocircuitos","Evitar que el voltaje de fase suba a 240V"],respuesta_correcta:1,explicacion:"Este puente une el conductor neutral con el sistema de tierra \xFAnicamente en el equipo de servicio principal."},{id:"et_290",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para el cual se usan los fusibles tipo cartucho?",opciones:["125 Voltios","250 Voltios","600 Voltios","1000 Voltios"],respuesta_correcta:2,explicacion:"Los fusibles de cartucho est\xE1ndar se fabrican com\xFAnmente en clasificaciones de 250V y 600V."},{id:"et_291",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 distancia se puede aplicar la 'Tap Rule' de 25 pies?",opciones:["En cualquier lugar sin restricciones","Solo en aplicaciones comerciales e industriales","Solo si el cable est\xE1 en conduit o gabinete","Solo si el cable es de cobre #14 AWG"],respuesta_correcta:2,explicacion:"La regla de derivaci\xF3n de 25 pies requiere que los conductores est\xE9n protegidos f\xEDsicamente contra da\xF1os."},{id:"et_292",categoria:"ET_MOTORES",pregunta:"\xBFC\xF3mo se calcula la ampacidad del conductor para un motor con FLC de 40A?",opciones:["40 Amperios","46 Amperios","50 Amperios","60 Amperios"],respuesta_correcta:2,explicacion:"NEC 430.22 requiere 125% de la FLC. 40A * 1.25 = 50 Amperios."},{id:"et_293",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa un motor con 'Clase de Aislamiento F'?",opciones:["Que el motor es aprueba de fuego (Fire)","Que el bobinado soporta hasta 155\xB0C de temperatura","Que el motor solo funciona en frecuencia de 50Hz","Que el motor debe usarse con fusible de 15A"],respuesta_correcta:1,explicacion:"La Clase F es una clasificaci\xF3n t\xE9rmica que indica que los materiales aislantes del motor soportan hasta 155\xB0C."},{id:"et_294",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 sucede si un transformador se sobrecarga por un tiempo prolongado?",opciones:["El voltaje de salida aumentar\xE1 peligrosamente","El aislamiento de las bobinas se derretir\xE1","La corriente del primario bajar\xE1 a cero","El transformador se convertir\xE1 en un im\xE1n permanente"],respuesta_correcta:1,explicacion:"El calor excesivo degrada el aislamiento del bobinado, lo que eventualmente causa un cortocircuito interno y falla total."},{id:"et_295",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es la corriente del primario de un transformador de 50 KVA trif\xE1sico a 480V?",opciones:["52.1 Amperios","60.2 Amperios","104.2 Amperios","120.4 Amperios"],respuesta_correcta:1,explicacion:"I = 50,000 / (480 * 1.732) = 50,000 / 831.36 = 60.14 Amperios."},{id:"et_296",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga de iluminaci\xF3n comercial para un edificio de oficinas?",opciones:["2 VA por pie cuadrado","3 VA por pie cuadrado","3.5 VA por pie cuadrado","3.9 VA por pie cuadrado"],respuesta_correcta:2,explicacion:"La Tabla 220.12 especifica 3.5 VA por cada pie cuadrado para \xE1reas de oficinas comerciales."},{id:"et_297",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 tipo de recept\xE1culo es obligatorio en un cuarto de lavado (Laundry Room)?",opciones:["Recept\xE1culo est\xE1ndar de 15A","Recept\xE1culo con protecci\xF3n GFCI","Recept\xE1culo con tapa de hule negra","Recept\xE1culo conectado al circuito de la estufa"],respuesta_correcta:1,explicacion:"NEC 210.8(A)(10) requiere protecci\xF3n GFCI para todos los recept\xE1culos instalados en \xE1reas de lavander\xEDa."},{id:"et_298",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Intrinsically Safe'?",opciones:["Que el equipo est\xE1 guardado bajo llave siempre","Que la energ\xEDa es tan baja que no puede causar ignici\xF3n","Que el equipo tiene un extintor de fuego integrado","Que el equipo solo se enciende si el aire es puro"],respuesta_correcta:1,explicacion:"La seguridad intr\xEDnseca limita la energ\xEDa el\xE9ctrica y t\xE9rmica para que no pueda encender una atm\xF3sfera explosiva."},{id:"et_299",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el radio de curvatura para un cable de fibra \xF3ptica?",opciones:["5 veces el di\xE1metro","10 veces el di\xE1metro","15 veces el di\xE1metro","20 veces el di\xE1metro"],respuesta_correcta:3,explicacion:"Debido a la fragilidad del vidrio o pl\xE1stico interno, la fibra \xF3ptica requiere un radio de curvatura amplio de 20x."},{id:"et_300",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es la distancia m\xEDnima de aproximaci\xF3n para personal no calificado a 480V?",opciones:["3 pies","5 pies","10 pies","15 pies"],respuesta_correcta:2,explicacion:"La 'Limited Approach Boundary' de NFPA 70E para personas no capacitadas es de 10 pies para voltajes de hasta 750V."},{id:"et_301",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la potencia total de una carga trif\xE1sica de 480V con 20A y un factor de potencia de 0.85?",opciones:["9,600 Watts","14,121 Watts","16,627 Watts","28,800 Watts"],respuesta_correcta:1,explicacion:"En trif\xE1sico: P = V * I * \u221A3 * FP. Calculamos: 480 * 20 * 1.732 * 0.85 = 14,121 Watts."},{id:"et_302",categoria:"ET_OHM_WATT",pregunta:"Si un circuito de 120V tiene una resistencia de 15 Ohmios, \xBFcu\xE1nta corriente fluye por \xE9l?",opciones:["4 Amperios","8 Amperios","12 Amperios","15 Amperios"],respuesta_correcta:1,explicacion:"Ley de Ohm: I = V / R. Entonces: 120V / 15\u03A9 = 8 Amperios."},{id:"et_303",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC establece los requisitos para el tama\xF1o de las cajas de salida y tracci\xF3n?",opciones:["Art\xEDculo 300","Art\xEDculo 310","Art\xEDculo 312","Art\xEDculo 314"],respuesta_correcta:3,explicacion:"El Art\xEDculo 314 cubre la instalaci\xF3n y el c\xE1lculo de volumen (Box Fill) de cajas de salida, dispositivos y uni\xF3n."},{id:"et_304",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el espacio libre m\xEDnimo sobre el nivel del piso para equipos el\xE9ctricos de 600V?",opciones:["5 pies (1.5 m)","6 pies (1.8 m)","6.5 pies (2.0 m)","No hay altura m\xEDnima"],respuesta_correcta:2,explicacion:"NEC 110.26(A)(3) requiere un espacio de trabajo con una altura libre m\xEDnima de 6.5 pies (2 metros) desde el piso."},{id:"et_305",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la letra 'X' en el aislamiento de un conductor tipo XHHW?",opciones:["Extra resistente","Cross-linked polymer","Xen\xF3n diel\xE9ctrico","Apto para rayos X"],respuesta_correcta:1,explicacion:"La 'X' indica que el aislamiento es de Polietileno de Cadena Cruzada (Cross-linked Polyethylene), un material muy resistente al calor."},{id:"et_306",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un conductor #4/0 AWG de aluminio THWN-2 a 75\xB0C?",opciones:["150 Amperios","180 Amperios","205 Amperios","230 Amperios"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 310.16, el cable #4/0 de aluminio en la columna de 75\xB0C tiene una capacidad de 180A."},{id:"et_307",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura m\xEDnimo para un conducto met\xE1lico r\xEDgido (RMC) de 2 pulgadas?",opciones:["8.25 pulgadas","9.5 pulgadas","12 pulgadas","15 pulgadas"],respuesta_correcta:1,explicacion:"Consultando el Cap\xEDtulo 9, Tabla 2, el radio de curvatura para tuber\xEDa r\xEDgida de 2 pulgadas es de 9.5 pulgadas."},{id:"et_308",categoria:"ET_CANALIZACIONES",pregunta:"\xBFA qu\xE9 distancia m\xE1xima de una caja debe estar soportada una tuber\xEDa IMC de 3/4 pulgada?",opciones:["1 pie (30 cm)","3 pies (90 cm)","5 pies (1.5 m)","10 pies (3.0 m)"],respuesta_correcta:1,explicacion:"NEC 342.30(A) exige que el IMC se soporte a no m\xE1s de 3 pies de cada terminaci\xF3n o caja."},{id:"et_309",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para un secador de ropa el\xE9ctrico de 5000W?",opciones:["4000 VA","5000 VA","6250 VA","8000 VA"],respuesta_correcta:1,explicacion:"NEC 220.54 establece que la carga para secadoras debe ser de 5000 VA o la placa del fabricante, lo que sea mayor."},{id:"et_310",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 tipo de recept\xE1culo es obligatorio instalar en un 'Crawl Space' residencial?",opciones:["Recept\xE1culo est\xE1ndar","Recept\xE1culo tipo AFCI","Recept\xE1culo con protecci\xF3n GFCI","Recept\xE1culo tipo Twist-Lock"],respuesta_correcta:2,explicacion:"NEC 210.8(A)(4) exige protecci\xF3n GFCI para todos los recept\xE1culos instalados en \xE1reas de rastreo o crawl spaces."},{id:"et_311",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el n\xFAmero m\xE1ximo permitido de desconectadores de servicio agrupados en un solo lugar?",opciones:["2 desconectadores","4 desconectadores","6 desconectadores","12 desconectadores"],respuesta_correcta:2,explicacion:"Conocida como la 'Regla de los Seis' (NEC 230.71), se permiten hasta 6 medios de desconexi\xF3n por cada juego de conductores de entrada."},{id:"et_312",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 color identifica al conductor neutral de un servicio de 120/208V?",opciones:["Blanco","Gris","Cinta Naranja","Cualquier color claro"],respuesta_correcta:0,explicacion:"El Art\xEDculo 200.6 requiere que el conductor neutral se identifique con color blanco para el sistema de voltaje m\xE1s bajo presente."},{id:"et_313",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el di\xE1metro m\xEDnimo para un electrodo de varilla de acero inoxidable?",opciones:["1/2 pulgada","5/8 pulgada","3/4 pulgada","1 pulgada"],respuesta_correcta:1,explicacion:"NEC 250.52(A)(5) especifica que las varillas de acero inoxidable deben tener al menos 5/8 de pulgada de di\xE1metro."},{id:"et_314",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 tabla del NEC se usa para dimensionar el conductor del electrodo de tierra (GEC)?",opciones:["Tabla 250.66","Tabla 250.102","Tabla 250.122","Tabla 310.16"],respuesta_correcta:0,explicacion:"La Tabla 250.66 dimensiona el cable de tierra que va a los electrodos basado en el tama\xF1o del conductor de fase m\xE1s grande."},{id:"et_315",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 significa la marca 'SWD' en un breaker de circuito?",opciones:["Standard Wattage Device","Switching Duty (Apto para luces)","Short Wave Detector","Safe Water Drain"],respuesta_correcta:1,explicacion:"Los breakers marcados como SWD est\xE1n dise\xF1ados para ser usados como interruptores de encendido/apagado para luces fluorescentes."},{id:"et_316",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xE1ximo de un breaker para un cable 12 AWG de cobre seg\xFAn la regla general?",opciones:["15 Amperios","20 Amperios","25 Amperios","30 Amperios"],respuesta_correcta:1,explicacion:"NEC 240.4(D)(5) limita el cable 12 AWG a una protecci\xF3n de sobrecorriente m\xE1xima de 20 amperios."},{id:"et_317",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje se dimensiona el conductor para un motor con una FLC de 100A?",opciones:["100 Amperios","115 Amperios","125 Amperios","150 Amperios"],respuesta_correcta:2,explicacion:"NEC 430.22 exige que el cable soporte el 125% de la carga: 100A * 1.25 = 125A."},{id:"et_318",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa 'Duty Cycle' en la placa de identificaci\xF3n de un motor?",opciones:["El pa\xEDs de origen del motor","El tiempo que el motor puede operar bajo carga","La rotaci\xF3n de las fases en el motor","El tipo de lubricante de los rodamientos"],respuesta_correcta:1,explicacion:"El ciclo de trabajo indica si el motor es para uso continuo o intermitente (ej. 30 min ON / 30 min OFF)."},{id:"et_319",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es el voltaje fase-fase en un sistema Delta de 240V con High-Leg?",opciones:["120V entre todas las fases","208V entre todas las fases","240V entre todas las fases","480V entre todas las fases"],respuesta_correcta:2,explicacion:"En un sistema Delta de 240V, el voltaje entre cualquiera de las tres fases (A-B, B-C, C-A) es siempre 240V."},{id:"et_320",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 art\xEDculo del NEC cubre espec\xEDficamente los transformadores?",opciones:["Art\xEDculo 430","Art\xEDculo 440","Art\xEDculo 450","Art\xEDculo 480"],respuesta_correcta:2,explicacion:"El Art\xEDculo 450 establece las reglas para la instalaci\xF3n, sobrecorriente y ventilaci\xF3n de transformadores."},{id:"et_321",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga VA m\xEDnima por cada salida de recept\xE1culo en un circuito comercial?",opciones:["100 VA","150 VA","180 VA","200 VA"],respuesta_correcta:2,explicacion:"NEC 220.14(I) requiere calcular 180 VA por cada salida individual o d\xFAplex montada en un mismo yugo."},{id:"et_322",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 distancia m\xE1xima debe estar un switch de luz de la ducha?",opciones:["Al menos 1 pie","Al menos 3 pies","Al menos 5 pies","No hay distancia si es GFCI"],respuesta_correcta:1,explicacion:"NEC 404.4 proh\xEDbe la instalaci\xF3n de switches dentro de \xE1reas mojadas de duchas o tinas a menos que est\xE9n listados."},{id:"et_323",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 clasificaci\xF3n define una ubicaci\xF3n con fibras vol\xE1tiles o part\xEDculas inflamables?",opciones:["Clase I","Clase II","Clase III","Clase IV"],respuesta_correcta:2,explicacion:"La Clase III se refiere a lugares donde se manejan fibras textiles, aserr\xEDn o part\xEDculas vol\xE1tiles de f\xE1cil ignici\xF3n."},{id:"et_324",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el calibre m\xEDnimo permitido para cables de control Clase 1?",opciones:["14 AWG","16 AWG","18 AWG","22 AWG"],respuesta_correcta:2,explicacion:"NEC 725.43 permite el uso de conductores de calibre 18 AWG y 16 AWG para circuitos de control Clase 1."},{id:"et_325",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa 'Approach Boundary' limitado en NFPA 70E?",opciones:["La distancia donde empieza el riesgo de arco","La distancia donde el riesgo de choque aumenta","La zona donde se permite trabajar sin PPE","El punto donde se requiere una escolta"],respuesta_correcta:1,explicacion:"Es la distancia l\xEDmite desde una parte viva expuesta dentro de la cual existe un riesgo de choque el\xE9ctrico."},{id:"et_326",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1nta potencia consume un motor de 240V que drena 15A con FP de 0.90?",opciones:["3,240 Watts","3,600 Watts","4,000 Watts","4,500 Watts"],respuesta_correcta:0,explicacion:"P = V * I * FP. Entonces: 240 * 15 * 0.90 = 3,240 Watts."},{id:"et_327",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la resistencia total de tres resistencias de 15 Ohmios en paralelo?",opciones:["45 Ohmios","15 Ohmios","5 Ohmios","3 Ohmios"],respuesta_correcta:2,explicacion:"Resistencia en paralelo: 15 / 3 (cantidad de resistencias iguales) = 5 Ohmios."},{id:"et_328",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 cap\xEDtulo del NEC cubre los 'Equipos Especiales' como elevadores y gr\xFAas?",opciones:["Cap\xEDtulo 4","Cap\xEDtulo 5","Cap\xEDtulo 6","Cap\xEDtulo 7"],respuesta_correcta:2,explicacion:"El Cap\xEDtulo 6 est\xE1 dedicado a equipos espec\xEDficos y especiales como se\xF1ales, piscinas y paneles solares."},{id:"et_329",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'In Sight From' seg\xFAn el Art\xEDculo 100?",opciones:["Que el equipo es visible desde cualquier parte del techo","Visible y a no m\xE1s de 50 pies (15 metros) de distancia","A la vista y conectado al mismo panel de breaker","Visible \xFAnicamente cuando se quita la tapa del panel"],respuesta_correcta:1,explicacion:"El t\xE9rmino exige que el equipo sea visible y est\xE9 ubicado a una distancia m\xE1xima de 50 pies."},{id:"et_330",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 color de conductor neutral debe usarse en un sistema de 277V?",opciones:["Blanco s\xF3lido \xFAnicamente","Gris o con franjas grises","Naranja s\xF3lido \xFAnicamente","Azul con franjas blancas"],respuesta_correcta:1,explicacion:"Se utiliza gris para identificar el neutral del sistema de mayor voltaje cuando hay m\xFAltiples sistemas presentes."},{id:"et_331",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un cable 2/0 AWG de cobre THWN-2 a 90\xB0C?",opciones:["145 Amperios","175 Amperios","195 Amperios","225 Amperios"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.16, el cable 2/0 de cobre en la columna de 90\xB0C tiene una ampacidad de 195A."},{id:"et_332",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el soporte m\xE1ximo permitido para una tuber\xEDa EMT de 2 pulgadas?",opciones:["Cada 3 pies","Cada 5 pies","Cada 10 pies","Cada 15 pies"],respuesta_correcta:2,explicacion:"A pesar del tama\xF1o, el Art\xEDculo 358.30(A) mantiene el soporte m\xE1ximo para EMT en 10 pies (3 metros)."},{id:"et_333",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1ntos conductores 14 AWG caben en un conduit EMT de 1/2 pulgada?",opciones:["6 conductores","9 conductores","12 conductores","15 conductores"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla C.1 del Anexo C, el m\xE1ximo permitido para 14 AWG THHN en EMT de 1/2 es de 12 conductores."},{id:"et_334",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga m\xEDnima para una estufa comercial de 15 kW?",opciones:["12,000 VA","15,000 VA","18,000 VA","20,000 VA"],respuesta_correcta:1,explicacion:"Para equipos comerciales, la carga se basa en el 100% del valor de la placa de identificaci\xF3n."},{id:"et_335",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 tipo de protecci\xF3n es obligatoria para recept\xE1culos en una cochera residencial (Carport)?",opciones:["Protecci\xF3n AFCI \xFAnicamente","Protecci\xF3n GFCI obligatoria","Solo recept\xE1culos tipo TR","Cualquier recept\xE1culo con tapa de hule"],respuesta_correcta:1,explicacion:"NEC 210.8(A)(2) exige protecci\xF3n GFCI para todos los recept\xE1culos de 125V en garajes y cocheras."},{id:"et_336",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el despeje m\xEDnimo sobre una entrada de autos (driveway) para cables de servicio?",opciones:["8 pies","10 pies","12 pies","15 pies"],respuesta_correcta:2,explicacion:"NEC 230.24(B)(2) requiere un despeje vertical m\xEDnimo de 12 pies para conductores de acometida residenciales."},{id:"et_337",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de un GEC de cobre para un servicio de 400A?",opciones:["#4 AWG","#2 AWG","#1/0 AWG","#2/0 AWG"],respuesta_correcta:2,explicacion:"Para un servicio de 400A (conductores de fase de 500 kcmil), la Tabla 250.66 requiere un GEC de #1/0 AWG cobre."},{id:"et_338",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 color de conductor est\xE1 reservado para el Equipment Grounding Conductor?",opciones:["Blanco s\xF3lido","Gris natural","Naranja con raya","Verde o verde/amarillo"],respuesta_correcta:3,explicacion:"El color verde identifica exclusivamente a los conductores de puesta a tierra de equipos seg\xFAn el Art\xEDculo 250.119."},{id:"et_339",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es la resistencia m\xE1xima sugerida para un sistema de electrodos de tierra?",opciones:["5 Ohmios","10 Ohmios","25 Ohmios","50 Ohmios"],respuesta_correcta:2,explicacion:"El NEC requiere que si un electrodo \xFAnico tiene m\xE1s de 25 Ohmios, se a\xF1ada un segundo electrodo en paralelo."},{id:"et_340",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 significa la marca 'HACR' en un breaker?",opciones:["Heavy Ampere Current Rating","Heating, Air Conditioning, Refrigeration","High Altitude Circuit Regulator","Home Appliance Circuit Rated"],respuesta_correcta:1,explicacion:"Los breakers HACR est\xE1n probados y certificados para manejar las cargas espec\xEDficas de motores de aire acondicionado."},{id:"et_341",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el amperaje est\xE1ndar que sigue despu\xE9s de 60 Amperios?",opciones:["65 Amperios","70 Amperios","75 Amperios","80 Amperios"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 240.6(A), el siguiente tama\xF1o de fusible o breaker est\xE1ndar despu\xE9s de 60A es 70A."},{id:"et_342",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla del NEC proporciona la corriente nominal para motores trif\xE1sicos?",opciones:["Tabla 430.248","Tabla 430.250","Tabla 310.16","Tabla 250.122"],respuesta_correcta:1,explicacion:"La Tabla 430.250 es la referencia oficial para los valores de corriente (FLC) de motores trif\xE1sicos."},{id:"et_343",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 distancia m\xE1xima debe estar el desconectador 'a la vista' del motor?",opciones:["25 pies (7.5 m)","50 pies (15 m)","75 pies (22.5 m)","100 pies (30 m)"],respuesta_correcta:1,explicacion:"'A la vista' (In sight from) se define legalmente en el c\xF3digo como una distancia no mayor a 50 pies."},{id:"et_344",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFC\xF3mo se llama el devanado del transformador que se conecta a la carga?",opciones:["Devanado Primario","Devanado Secundario","Devanado de Control","Devanado Auxiliar"],respuesta_correcta:1,explicacion:"El devanado secundario es el que entrega el voltaje transformado al sistema o equipo receptor."},{id:"et_345",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 sucede con la corriente si un transformador reduce el voltaje de 480V a 120V?",opciones:["La corriente disminuye 4 veces","La corriente aumenta 4 veces","La corriente se mantiene igual","La corriente baja a cero"],respuesta_correcta:1,explicacion:"Por conservaci\xF3n de energ\xEDa, si el voltaje baja 4 veces, la corriente disponible en el secundario aumenta 4 veces."},{id:"et_346",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 carga de VA se calcula para un recept\xE1culo d\xFAplex en una vivienda?",opciones:["180 VA","90 VA","No se calcula por unidad","200 VA"],respuesta_correcta:2,explicacion:"En viviendas, la carga de los recept\xE1culos se incluye en el c\xE1lculo de carga general por pie cuadrado (3 VA)."},{id:"et_347",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la altura m\xEDnima de una luminaria sobre el nivel del agua de una piscina?",opciones:["8 pies (2.4 m)","10 pies (3.0 m)","12 pies (3.6 m)","15 pies (4.5 m)"],respuesta_correcta:2,explicacion:"NEC 680.22 requiere que las luminarias est\xE9n al menos a 12 pies sobre el nivel m\xE1ximo del agua de la piscina."},{id:"et_348",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 clasificaci\xF3n define un \xE1rea donde hay gases inflamables presentes?",opciones:["Clase I","Clase II","Clase III","Clase IV"],respuesta_correcta:0,explicacion:"La Clase I abarca lugares con presencia de gases, vapores producidos por l\xEDquidos o l\xEDquidos inflamables."},{id:"et_349",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para un circuito de Clase 2?",opciones:["24 Voltios","30 Voltios","50 Voltios","120 Voltios"],respuesta_correcta:1,explicacion:"Los circuitos de Clase 2 est\xE1n limitados por voltaje (30V) y potencia para reducir riesgos de incendio y choque."},{id:"et_350",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 color de etiqueta identifica a los guantes de hule Clase 00?",opciones:["Rojo","Amarillo","Beige","Azul"],respuesta_correcta:2,explicacion:"Los guantes Clase 00 (probados hasta 500V AC) se identifican con una etiqueta de color beige."},{id:"et_351",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos miliamperios hay en 0.75 Amperios?",opciones:["7.5 mA","75 mA","750 mA","7500 mA"],respuesta_correcta:2,explicacion:"1 Amperio = 1000 mA. Entonces: 0.75 * 1000 = 750 mA."},{id:"et_352",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la resistencia de una bombilla de 60W a 120V?",opciones:["2 Ohmios","120 Ohmios","240 Ohmios","480 Ohmios"],respuesta_correcta:2,explicacion:"R = V\xB2 / P. Entonces: 120 * 120 / 60 = 14400 / 60 = 240 Ohmios."},{id:"et_353",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC cubre los sistemas de alarma contra incendios?",opciones:["Art\xEDculo 700","Art\xEDculo 725","Art\xEDculo 760","Art\xEDculo 800"],respuesta_correcta:2,explicacion:"El Art\xEDculo 760 contiene todos los requisitos para cableado e instalaci\xF3n de alarmas de incendio."},{id:"et_354",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el s\xEDmbolo 'N' al lado de un art\xEDculo en el NEC?",opciones:["No permitido en la industria","Nuevo material agregado al c\xF3digo","Nota informativa no obligatoria","Nivel de seguridad cr\xEDtico"],respuesta_correcta:1,explicacion:"La letra 'N' identifica secciones o art\xEDculos que son nuevos en la edici\xF3n actual del NEC."},{id:"et_355",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un cable #10 AWG de cobre tipo TW a 60\xB0C?",opciones:["20 Amperios","25 Amperios","30 Amperios","35 Amperios"],respuesta_correcta:2,explicacion:"Consultando la Tabla 310.16, el cable #10 de cobre en la columna de 60\xB0C tiene una capacidad de 30A."},{id:"et_356",categoria:"ET_CONDUCTORES",pregunta:"\xBFA qu\xE9 porcentaje se reduce la ampacidad si hay 7-9 conductores en un conduit?",opciones:["80%","70%","50%","45%"],respuesta_correcta:1,explicacion:"La Tabla 310.15(C)(1) requiere una reducci\xF3n al 70% cuando hay de 7 a 9 conductores portadores de corriente."},{id:"et_357",categoria:"ET_CANALIZACIONES",pregunta:"\xBFA qu\xE9 distancia m\xE1xima de una caja de PVC debe estar el primer soporte?",opciones:["1 pie (30 cm)","3 pies (90 cm)","5 pies (1.5 m)","10 pies (3.0 m)"],respuesta_correcta:1,explicacion:"El PVC debe ser soportado a una distancia m\xE1xima de 3 pies de cada caja, gabinete o terminaci\xF3n de tuber\xEDa."},{id:"et_358",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1ntos conductores 10 AWG THHN caben en un EMT de 1/2 pulgada?",opciones:["3 conductores","4 conductores","5 conductores","6 conductores"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla C.1 del Anexo C, el m\xE1ximo permitido para 10 AWG THHN en EMT de 1/2 es de 4 conductores."},{id:"et_359",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 circuito se requiere para alimentar un lavaplatos (Dishwasher) residencial?",opciones:["Circuito de 15A de uso general","Circuito individual de 20A","Circuito compartido con la cocina","Circuito de 30A de alta potencia"],respuesta_correcta:1,explicacion:"Se requiere un circuito dedicado para el lavaplatos para evitar sobrecargas y disparos del breaker por el motor."},{id:"et_360",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es el requisito de GFCI para recept\xE1culos en un ba\xF1o comercial?",opciones:["No se requiere si no hay regadera","Es obligatorio para todos los recept\xE1culos","Solo se requiere a 6 pies del lavabo","Solo se requiere si el piso es de concreto"],respuesta_correcta:1,explicacion:"NEC 210.8(B)(2) exige protecci\xF3n GFCI para todos los recept\xE1culos de 125V en ba\xF1os de cualquier tipo de edificio."},{id:"et_361",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de cable de cobre para una acometida residencial de 200A?",opciones:["2/0 AWG","3/0 AWG","4/0 AWG","250 kcmil"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 310.12, un servicio residencial de 200A requiere conductores de fase de cobre calibre 2/0 AWG."},{id:"et_362",categoria:"ET_SERVICIO",pregunta:"\xBFA qu\xE9 altura m\xEDnima debe estar la terminaci\xF3n de la acometida sobre una calle p\xFAblica?",opciones:["12 pies","15 pies","18 pies","22 pies"],respuesta_correcta:2,explicacion:"NEC 230.24(B)(4) requiere un despeje vertical m\xEDnimo de 18 pies sobre calles y callejones p\xFAblicos."},{id:"et_363",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el calibre m\xEDnimo de un GEC de cobre conectado a un electrodo de concreto?",opciones:["#8 AWG","#6 AWG","#4 AWG","#2 AWG"],respuesta_correcta:2,explicacion:"NEC 250.66(B) indica que el conductor que va a un electrodo revestido de concreto no necesita ser mayor a #4 AWG cobre."},{id:"et_364",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 significa 'Bonding' en t\xE9rminos de seguridad?",opciones:["Enterrar una varilla muy profunda","Unir todas las partes met\xE1licas el\xE9ctricamente","Aislar el cable neutral de la caja","Soldar los cables de fase al panel"],respuesta_correcta:1,explicacion:"Bonding es la uni\xF3n de partes met\xE1licas no portadoras de corriente para asegurar la continuidad y el camino de falla."},{id:"et_365",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el amperaje est\xE1ndar que sigue despu\xE9s de 15 Amperios?",opciones:["18 Amperios","20 Amperios","22 Amperios","25 Amperios"],respuesta_correcta:1,explicacion:"En las clasificaciones est\xE1ndar de OCPD (Tabla 240.6), el tama\xF1o que sigue a 15A es 20A."},{id:"et_366",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 breaker protege espec\xEDficamente contra fugas de corriente a tierra?",opciones:["AFCI","GFCI","OCPD","MCCB"],respuesta_correcta:1,explicacion:"El GFCI (Ground Fault Circuit Interrupter) detecta desequilibrios m\xEDnimos entre fase y neutral para proteger vidas."},{id:"et_367",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se calcula el desconectador de un motor?",opciones:["100%","115%","125%","150%"],respuesta_correcta:1,explicacion:"NEC 430.110(A) requiere que el medio de desconexi\xF3n tenga una capacidad de al menos el 115% de la FLC del motor."},{id:"et_368",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa 'Service Factor' (SF) en la placa de un motor?",opciones:["El costo del servicio de mantenimiento","La capacidad de sobrecarga continua permitida","La distancia m\xE1xima del cable de servicio","El tipo de herramienta necesaria para abrirlo"],respuesta_correcta:1,explicacion:"Un SF de 1.15 significa que el motor puede manejar un 15% m\xE1s de su carga nominal de forma segura."},{id:"et_369",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 voltaje se obtiene entre una fase y el neutral en un sistema de 208Y/120V?",opciones:["120 Voltios","208 Voltios","240 Voltios","277 Voltios"],respuesta_correcta:0,explicacion:"En un sistema Wye de 208V, el voltaje de cada fase con respecto al neutral com\xFAn es de 120V."},{id:"et_370",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es el color prohibido para identificar cables de fase en un sistema de potencia?",opciones:["Negro","Rojo","Azul","Verde"],respuesta_correcta:3,explicacion:"El color verde est\xE1 estrictamente reservado para conductores de puesta a tierra (tierra) y no puede usarse para fases."},{id:"et_371",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es el espacio m\xEDnimo de una luminaria LED de un estante en un cl\xF3set?",opciones:["3 pulgadas","6 pulgadas","12 pulgadas","18 pulgadas"],respuesta_correcta:2,explicacion:"NEC 410.16(C) requiere una separaci\xF3n m\xEDnima de 12 pulgadas para luminarias de superficie incandescentes o LED."},{id:"et_372",categoria:"ET_ILUMINACION",pregunta:"\xBFC\xF3mo se calcula la carga de iluminaci\xF3n para un hospital por pie cuadrado?",opciones:["1 VA por pie cuadrado","2 VA por pie cuadrado","3 VA por pie cuadrado","5 VA por pie cuadrado"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 220.12, los hospitales requieren un c\xE1lculo de 2 VA por cada pie cuadrado de \xE1rea."},{id:"et_373",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Divisi\xF3n 1' en una clasificaci\xF3n de lugar peligroso?",opciones:["Peligro presente solo por accidente raro","Peligro presente en condiciones normales de trabajo","\xC1rea donde no se permite ning\xFAn cable","Zona de almacenamiento de agua \xFAnicamente"],respuesta_correcta:1,explicacion:"En Divisi\xF3n 1, el gas o polvo explosivo se espera que est\xE9 presente de manera constante o frecuente durante la operaci\xF3n."},{id:"et_374",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el requisito de separaci\xF3n entre cables de Clase 2 y cables de potencia?",opciones:["Deben ir en el mismo tubo siempre","Separaci\xF3n f\xEDsica m\xEDnima de 2 pulgadas (50 mm)","Deben ser del mismo color para no confundir","No hay requisito de separaci\xF3n f\xEDsica"],respuesta_correcta:1,explicacion:"NEC 725.136 exige una barrera o separaci\xF3n de 2 pulgadas para evitar que el alto voltaje da\xF1e los circuitos de control."},{id:"et_375",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa 'LOTO' en seguridad el\xE9ctrica?",opciones:["Line Off, Time Out","Low Output, Total Ohm","Lockout / Tagout (Bloqueo y Etiquetado)","Live Only, Trained Only"],respuesta_correcta:2,explicacion:"LOTO es el procedimiento cr\xEDtico para asegurar que el equipo est\xE9 desenergizado mientras se realiza mantenimiento."},{id:"et_376",categoria:"ET_OHM_WATT",pregunta:"Si un motor monof\xE1sico de 1 HP consume 746W a 120V, \xBFcu\xE1ntos Amperios drena?",opciones:["3.2 Amperios","6.2 Amperios","10.0 Amperios","12.4 Amperios"],respuesta_correcta:1,explicacion:"I = P / V. 746W / 120V = 6.21 Amperios (te\xF3rico sin considerar eficiencia o FP)."},{id:"et_377",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la resistencia de un calentador de 240V y 4800W?",opciones:["8 Ohmios","12 Ohmios","24 Ohmios","48 Ohmios"],respuesta_correcta:1,explicacion:"R = V\xB2 / P. Entonces: 240 * 240 / 4800 = 57600 / 4800 = 12 Ohmios."},{id:"et_378",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa 'Accessible' aplicado a equipos seg\xFAn el Art\xEDculo 100?",opciones:["Que se puede llegar a \xE9l sin quitar una tapa","Que est\xE1 guardado en una caja bajo llave","Admitiendo aproximaci\xF3n cercana; no guardado bajo llave","Que se puede tocar desde el suelo sin escalera"],respuesta_correcta:2,explicacion:"Para equipos, 'Accessible' significa que no est\xE1 bloqueado por estructuras permanentes y no requiere herramientas complejas."},{id:"et_379",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el voltaje nominal est\xE1ndar para sistemas trif\xE1sicos en EE.UU.?",opciones:["120V / 240V","208V / 120V","277V / 480V","Todas las anteriores son correctas"],respuesta_correcta:3,explicacion:"Los sistemas 208/120V, 240/120V y 480/277V son configuraciones nominales est\xE1ndar reconocidas por el c\xF3digo."},{id:"et_380",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 material de aislamiento tiene la mejor resistencia a la humedad?",opciones:["TW","THHN","THWN-2","THH"],respuesta_correcta:2,explicacion:"La 'W' indica 'Wet' (mojado). El THWN-2 est\xE1 espec\xEDficamente dise\xF1ado para inmersi\xF3n o ubicaciones mojadas a 90\xB0C."},{id:"et_381",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un conductor #2 AWG de aluminio THHN a 90\xB0C?",opciones:["75 Amperios","90 Amperios","100 Amperios","115 Amperios"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.16, el cable #2 de aluminio en la columna de 90\xB0C tiene una capacidad de 100A."},{id:"et_382",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura para un conduit EMT de 1-1/2 pulgadas?",opciones:["4.5 pulgadas","7.25 pulgadas","8.25 pulgadas","10.5 pulgadas"],respuesta_correcta:2,explicacion:"Consultando el Cap\xEDtulo 9, Tabla 2, el radio de curvatura para tuber\xEDa EMT de 1-1/2 pulgadas es de 8.25 pulgadas."},{id:"et_383",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 porcentaje de llenado se permite para 2 conductores en una canalizaci\xF3n?",opciones:["31%","40%","53%","60%"],respuesta_correcta:0,explicacion:"Para exactamente dos conductores dentro de una tuber\xEDa, el l\xEDmite de llenado es del 31% del \xE1rea interna."},{id:"et_384",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para un calentador de espacio fijo de 1500W?",opciones:["1200 VA","1500 VA","1875 VA","3000 VA"],respuesta_correcta:1,explicacion:"Los calentadores de espacio se calculan al 100% de su valor en Watts para el c\xE1lculo de carga (1500 VA)."},{id:"et_385",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 distancia m\xE1xima puede haber desde una puerta al switch de luz de una habitaci\xF3n?",opciones:["6 pulgadas","12 pulgadas","24 pulgadas","No hay una distancia espec\xEDfica"],respuesta_correcta:3,explicacion:"El NEC requiere que haya un switch, pero no dicta una medida exacta en pulgadas desde el marco de la puerta."},{id:"et_386",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o de GEC de cobre se requiere para un servicio de 100A?",opciones:["#10 AWG","#8 AWG","#6 AWG","#4 AWG"],respuesta_correcta:1,explicacion:"Para un servicio de 100A (fase #4 cobre), la Tabla 250.66 requiere un GEC de cobre calibre #8 AWG."},{id:"et_387",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el despeje horizontal m\xEDnimo de cables de servicio desde una salida de incendio?",opciones:["1 pie","3 pies","6 pies","10 pies"],respuesta_correcta:1,explicacion:"NEC 230.9(A) exige que los conductores de servicio est\xE9n al menos a 3 pies de ventanas, puertas o escaleras de incendio."},{id:"et_388",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es la funci\xF3n principal del Equipment Grounding Conductor?",opciones:["Atraer rayos hacia el panel","Servir como retorno para el neutral","Crear un camino de baja impedancia para corriente de falla","Reducir el consumo de energ\xEDa del motor"],respuesta_correcta:2,explicacion:"Su funci\xF3n es asegurar que si hay una falla a tierra, fluya suficiente corriente para disparar el breaker de inmediato."},{id:"et_389",categoria:"ET_GROUNDING",pregunta:"\xBFC\xF3mo se identifica un conductor neutral mayor a #6 AWG?",opciones:["Aislamiento blanco en toda su longitud","Tres franjas blancas continuas en toda su longitud","Marcado con cinta blanca en cada terminaci\xF3n","Cualquiera de las anteriores es correcta"],respuesta_correcta:3,explicacion:"El Art\xEDculo 200.6 permite varias formas de identificar el neutral en calibres grandes, incluyendo el marcado en los extremos."},{id:"et_390",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es la clasificaci\xF3n de interrupci\xF3n est\xE1ndar (AIC) para un breaker residencial?",opciones:["1,000 Amperios","5,000 Amperios","10,000 Amperios","22,000 Amperios"],respuesta_correcta:2,explicacion:"La mayor\xEDa de los breakers para paneles residenciales tienen una capacidad de interrupci\xF3n de 10,000 Amperios (10k AIC)."},{id:"et_391",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 significa 'Trip-Free' en un breaker?",opciones:["Que no cuesta dinero si se dispara","Que se dispara aunque la manija se mantenga bloqueada en 'ON'","Que puede ser reseteado sin usar herramientas","Que se dispara solo por cortocircuitos reales"],respuesta_correcta:1,explicacion:"Un dise\xF1o Trip-Free garantiza que el mecanismo interno desconecte la energ\xEDa incluso si alguien intenta forzar la palanca."},{id:"et_392",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se calcula la protecci\xF3n contra sobrecarga (Overload)?",opciones:["100% a 115%","115% a 125%","125% a 150%","150% a 250%"],respuesta_correcta:1,explicacion:"Dependiendo del motor y su factor de servicio, la protecci\xF3n de sobrecarga se ajusta t\xEDpicamente entre 115% y 125%."},{id:"et_393",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla se usa para motores de Corriente Continua (DC)?",opciones:["Tabla 430.247","Tabla 430.248","Tabla 430.250","Tabla 430.52"],respuesta_correcta:0,explicacion:"La Tabla 430.247 proporciona los valores de corriente nominal para motores de corriente continua."},{id:"et_394",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 es un transformador de Clase 2?",opciones:["Un transformador para edificios de dos pisos","Un transformador con potencia limitada para evitar incendios","Un transformador que solo funciona en sistemas trif\xE1sicos","Un transformador sin aislamiento galv\xE1nico"],respuesta_correcta:1,explicacion:"Los transformadores de Clase 2 limitan la energ\xEDa de salida a niveles seguros que no causen incendios o choques graves."},{id:"et_395",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es el voltaje fase-fase en un sistema Wye de 480V?",opciones:["120 Voltios","208 Voltios","240 Voltios","480 Voltios"],respuesta_correcta:3,explicacion:"En este sistema, 480V es el voltaje entre dos fases cualesquiera, mientras que 277V es el voltaje fase-neutral."},{id:"et_396",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga de iluminaci\xF3n comercial para una escuela?",opciones:["1 VA por pie cuadrado","2 VA por pie cuadrado","3 VA por pie cuadrado","4 VA por pie cuadrado"],respuesta_correcta:2,explicacion:"La Tabla 220.12 especifica un valor de 3 VA por cada pie cuadrado para escuelas y centros educativos."},{id:"et_397",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 tipo de recept\xE1culo se requiere en un garaje comercial de servicio?",opciones:["Recept\xE1culo est\xE1ndar \xFAnicamente","Recept\xE1culo con protecci\xF3n GFCI","Recept\xE1culo tipo Twist-Lock para motores","No se permiten recept\xE1culos en el piso"],respuesta_correcta:1,explicacion:"NEC 210.8(B)(8) exige protecci\xF3n GFCI en garajes comerciales de servicio y \xE1reas de reparaci\xF3n."},{id:"et_398",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Intrinsically Safe' (Intr\xEDnsecamente Seguro)?",opciones:["Equipo guardado en caja fuerte met\xE1lica","Energ\xEDa tan baja que no puede causar ignici\xF3n","Equipo que no usa electricidad para funcionar","Instalaci\xF3n con doble cable de tierra"],respuesta_correcta:1,explicacion:"La seguridad intr\xEDnseca limita la energ\xEDa el\xE9ctrica disponible para que una chispa no tenga fuerza para encender vapores."},{id:"et_399",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el radio de curvatura para un cable de comunicaciones?",opciones:["2 veces el di\xE1metro","4 veces el di\xE1metro","10 veces el di\xE1metro","20 veces el di\xE1metro"],respuesta_correcta:1,explicacion:"Para la mayor\xEDa de los cables de baja tensi\xF3n y comunicaci\xF3n, se requiere un radio de 4 veces el di\xE1metro del cable."},{id:"et_400",categoria:"ET_SEGURIDAD",pregunta:"\xBFA qu\xE9 nivel de corriente (mA) suele dispararse un GFCI de Clase A?",opciones:["1 a 3 mA","4 a 6 mA","10 a 15 mA","30 a 50 mA"],respuesta_correcta:1,explicacion:"Los GFCI para protecci\xF3n de personas est\xE1n calibrados para abrir el circuito cuando detectan una fuga de entre 4 y 6 mA."},{id:"et_401",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la resistencia total de un circuito con tres resistencias de 60 Ohmios conectadas en paralelo?",opciones:["180 Ohmios","60 Ohmios","30 Ohmios","20 Ohmios"],respuesta_correcta:3,explicacion:"Para resistencias iguales en paralelo: R / n. Entonces, 60 / 3 = 20 Ohmios."},{id:"et_402",categoria:"ET_OHM_WATT",pregunta:"Si un motor monof\xE1sico de 240V consume 4800W, \xBFcu\xE1l es su corriente de funcionamiento?",opciones:["10 Amperios","20 Amperios","30 Amperios","40 Amperios"],respuesta_correcta:1,explicacion:"I = P / V. Calculamos 4800 / 240 = 20 Amperios."},{id:"et_403",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC establece los requisitos para el uso de cables tipo NM (Romex)?",opciones:["Art\xEDculo 330","Art\xEDculo 334","Art\xEDculo 336","Art\xEDculo 338"],respuesta_correcta:1,explicacion:"El Art\xEDculo 334 cubre la instalaci\xF3n, soporte y limitaciones del cable con cubierta no met\xE1lica tipo NM."},{id:"et_404",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el espacio libre m\xEDnimo de trabajo lateral frente a un panel el\xE9ctrico de 30 pulgadas de ancho?",opciones:["24 pulgadas","30 pulgadas","36 pulgadas","42 pulgadas"],respuesta_correcta:1,explicacion:"El ancho del espacio de trabajo debe ser el ancho del equipo o 30 pulgadas, lo que sea mayor (NEC 110.26)."},{id:"et_405",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la letra 'HH' en un aislamiento de conductor como el XHHW?",opciones:["High Humidity (Humedad alta)","High Heat (Calor hasta 90\xB0C)","Heavy Housing (Carcasa pesada)","Halogen Hazardous (Hal\xF3geno)"],respuesta_correcta:1,explicacion:"La 'H' simple indica 75\xB0C, mientras que 'HH' indica una resistencia al calor de hasta 90\xB0C."},{id:"et_406",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un conductor #3 AWG de cobre THW a 75\xB0C?",opciones:["85 Amperios","100 Amperios","110 Amperios","115 Amperios"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 310.16, el cable #3 de cobre en la columna de 75\xB0C tiene una ampacidad de 100A."},{id:"et_407",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el soporte m\xE1ximo permitido para un conduit met\xE1lico intermedio (IMC) de 1 pulgada?",opciones:["Cada 5 pies","Cada 8 pies","Cada 10 pies","Cada 12 pies"],respuesta_correcta:2,explicacion:"El Art\xEDculo 342.30(A) requiere que el IMC se soporte a intervalos de no m\xE1s de 10 pies (3 metros)."},{id:"et_408",categoria:"ET_CANALIZACIONES",pregunta:"\xBFA qu\xE9 distancia m\xE1xima de una caja debe estar soportado un cable tipo MC?",opciones:["1 pie (12 pulgadas)","3 pies (36 pulgadas)","6 pies (72 pulgadas)","10 pies (120 pulgadas)"],respuesta_correcta:0,explicacion:"El cable MC debe asegurarse a no m\xE1s de 12 pulgadas (1 pie) de cada caja o terminaci\xF3n (NEC 330.30)."},{id:"et_409",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para un circuito de peque\xF1os electrodom\xE9sticos en la cocina?",opciones:["1200 VA","1500 VA","1800 VA","2400 VA"],respuesta_correcta:1,explicacion:"Cada circuito de 20A para electrodom\xE9sticos peque\xF1os debe calcularse a 1500 VA seg\xFAn NEC 220.52(A)."},{id:"et_410",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 lugar requiere protecci\xF3n GFCI en una unidad de vivienda seg\xFAn el Art\xEDculo 210.8?",opciones:["Dormitorios principales","Salas de estar y pasillos","Exteriores y balcones","Comedores formales"],respuesta_correcta:2,explicacion:"Los exteriores, garajes, ba\xF1os y cocinas son \xE1reas cr\xEDticas que requieren protecci\xF3n GFCI por seguridad."},{id:"et_411",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es la altura m\xEDnima de los conductores de acometida sobre una zona solo peatonal?",opciones:["8 pies","10 pies","12 pies","15 pies"],respuesta_correcta:1,explicacion:"NEC 230.24(B)(1) requiere un despeje vertical m\xEDnimo de 10 pies sobre \xE1reas peatonales."},{id:"et_412",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o m\xEDnimo de cable de aluminio se requiere para un servicio residencial de 100A?",opciones:["#4 AWG","#2 AWG","#1 AWG","#1/0 AWG"],respuesta_correcta:1,explicacion:"Para una vivienda con servicio de 100A, se requiere conductores de aluminio calibre #2 AWG (Tabla 310.12)."},{id:"et_413",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el di\xE1metro m\xEDnimo de un electrodo de varilla de cobre s\xF3lido?",opciones:["1/2 pulgada","5/8 pulgada","3/4 pulgada","1 pulgada"],respuesta_correcta:0,explicacion:"Las varillas de cobre s\xF3lido o acero inoxidable pueden ser de 1/2 pulgada de di\xE1metro seg\xFAn NEC 250.52."},{id:"et_414",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 tabla del NEC se usa para dimensionar el conductor de puesta a tierra de equipos (EGC)?",opciones:["Tabla 250.66","Tabla 250.102","Tabla 250.122","Tabla 310.16"],respuesta_correcta:2,explicacion:"La Tabla 250.122 se usa para dimensionar el cable de tierra basado en el amperaje del breaker del circuito."},{id:"et_415",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 indica el 'Interrupting Rating' en un dispositivo de sobrecorriente?",opciones:["La carga m\xE1xima que puede soportar continuamente","La capacidad de detener una corriente de falla sin da\xF1arse","El tiempo que tarda en dispararse por calor","El voltaje m\xE1ximo de operaci\xF3n permitida"],respuesta_correcta:1,explicacion:"Es el amperaje de cortocircuito m\xE1ximo que el dispositivo puede interrumpir con seguridad (ej. 10k AIC)."},{id:"et_416",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el amperaje est\xE1ndar que sigue despu\xE9s de los 25 Amperios?",opciones:["27 Amperios","30 Amperios","35 Amperios","40 Amperios"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 240.6(A), el siguiente tama\xF1o est\xE1ndar de fusible o breaker despu\xE9s de 25A es 30A."},{id:"et_417",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se dimensiona el conductor de un motor continuo?",opciones:["100%","115%","125%","140%"],respuesta_correcta:2,explicacion:"El cable debe tener una ampacidad de al menos el 125% de la corriente de placa del motor (NEC 430.22)."},{id:"et_418",categoria:"ET_MOTORES",pregunta:"\xBFCu\xE1l es el medio de desconexi\xF3n requerido 'a la vista' de un motor seg\xFAn el NEC?",opciones:["Un breaker en un panel a 100 pies","Un switch capaz de ser bloqueado en posici\xF3n abierta","Una caja de conexiones con tapa de seguridad","Un recept\xE1culo GFCI con bot\xF3n de prueba"],respuesta_correcta:1,explicacion:"Debe haber un desconectador visible desde la ubicaci\xF3n del motor y a no m\xE1s de 50 pies."},{id:"et_419",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es la corriente primaria de un transformador de 10 KVA a 480V monof\xE1sico?",opciones:["10.4 Amperios","20.8 Amperios","41.6 Amperios","48.0 Amperios"],respuesta_correcta:1,explicacion:"I = VA / V. 10,000 / 480 = 20.83 Amperios."},{id:"et_420",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFC\xF3mo se conectan los devanados primarios en un sistema 'Delta' trif\xE1sico?",opciones:["En paralelo con el neutral com\xFAn","En serie formando un lazo cerrado","Conectados a la varilla de tierra f\xEDsica","A trav\xE9s de fusibles de Clase 2 \xFAnicamente"],respuesta_correcta:1,explicacion:"En una configuraci\xF3n Delta, cada devanado se conecta entre dos fases formando un tri\xE1ngulo."},{id:"et_421",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga de iluminaci\xF3n por pie cuadrado para un edificio de oficinas?",opciones:["2 VA","3 VA","3.5 VA","5 VA"],respuesta_correcta:2,explicacion:"La Tabla 220.12 especifica 3.5 VA por pie cuadrado para el c\xE1lculo de carga en oficinas."},{id:"et_422",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 distancia de la puerta de un cl\xF3set se permite una luminaria LED de superficie?",opciones:["3 pulgadas","6 pulgadas","12 pulgadas","18 pulgadas"],respuesta_correcta:2,explicacion:"NEC 410.16(C) requiere un espacio de 12 pulgadas entre la luminaria y el espacio de almacenamiento del cl\xF3set."},{id:"et_423",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 clasificaci\xF3n define un \xE1rea donde hay polvos combustibles presentes?",opciones:["Clase I","Clase II","Clase III","Clase IV"],respuesta_correcta:1,explicacion:"La Clase II define \xE1reas con riesgos de explosi\xF3n debido a polvos como harina, carb\xF3n o qu\xEDmicos."},{id:"et_424",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para un circuito de control Clase 2 en HVAC?",opciones:["12 Voltios","24 Voltios","30 Voltios","120 Voltios"],respuesta_correcta:2,explicacion:"El Art\xEDculo 725 limita los circuitos de Clase 2 a 30V para seguridad contra choques el\xE9ctricos e incendios."},{id:"et_425",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa la sigla 'PPE' en el trabajo el\xE9ctrico?",opciones:["Power Phase Equipment","Personal Protective Equipment","Panel Pressure Evaluation","Primary Point Entry"],respuesta_correcta:1,explicacion:"Se refiere al equipo de protecci\xF3n personal (guantes, casco, ropa FR) necesario para trabajar con seguridad."},{id:"et_426",categoria:"ET_OHM_WATT",pregunta:"Si la resistencia es de 12 Ohmios y la corriente es de 10A, \xBFcu\xE1l es el voltaje?",opciones:["1.2 Voltios","12 Voltios","120 Voltios","144 Voltios"],respuesta_correcta:2,explicacion:"V = I * R. Entonces: 10A * 12\u03A9 = 120V."},{id:"et_427",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es el consumo en Watts de una bombilla que drena 0.5A a 120V?",opciones:["60 Watts","120 Watts","240 Watts","600 Watts"],respuesta_correcta:0,explicacion:"P = V * I. Entonces: 120V * 0.5A = 60W."},{id:"et_428",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Listed' en el Art\xEDculo 100?",opciones:["Aparecer en un cat\xE1logo de ventas com\xFAn","Evaluado por una organizaci\xF3n aprobada (como UL)","Que el equipo est\xE1 hecho de cobre s\xF3lido","Que el inspector firm\xF3 la caja del equipo"],respuesta_correcta:1,explicacion:"'Listed' significa que el equipo ha sido probado y cumple con est\xE1ndares de seguridad reconocidos."},{id:"et_429",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el voltaje nominal de un sistema monof\xE1sico com\xFAn en EE.UU.?",opciones:["110V / 220V","115V / 230V","120V / 240V","127V / 254V"],respuesta_correcta:2,explicacion:"El NEC utiliza 120V y 240V como los voltajes nominales est\xE1ndar para la mayor\xEDa de los c\xE1lculos."},{id:"et_430",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 color de cinta se usa para identificar la fase C en un sistema de 480V?",opciones:["Negro","Rojo","Azul","Amarillo"],respuesta_correcta:3,explicacion:"El est\xE1ndar de la industria (BROWN-ORANGE-YELLOW) usa amarillo para la fase C en sistemas de 480V."},{id:"et_431",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es el calibre m\xEDnimo de un conductor de cobre para cableado general?",opciones:["10 AWG","12 AWG","14 AWG","16 AWG"],respuesta_correcta:2,explicacion:"NEC 310.106(A) establece que el tama\xF1o m\xEDnimo para conductores de potencia es 14 AWG."},{id:"et_432",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el porcentaje m\xE1ximo de llenado para una tuber\xEDa con un solo conductor?",opciones:["31%","40%","53%","60%"],respuesta_correcta:2,explicacion:"El Cap\xEDtulo 9, Tabla 1 permite llenar hasta el 53% del \xE1rea interna si solo hay un cable en el tubo."},{id:"et_433",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es la profundidad m\xEDnima para enterrar un conduit r\xEDgido (RMC) bajo tierra?",opciones:["6 pulgadas","12 pulgadas","18 pulgadas","24 pulgadas"],respuesta_correcta:0,explicacion:"La Tabla 300.5 permite una profundidad de solo 6 pulgadas para tuber\xEDa r\xEDgida (RMC) en la mayor\xEDa de los casos."},{id:"et_434",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA para una estufa residencial de 12 kW?",opciones:["8,000 VA","10,000 VA","12,000 VA","15,000 VA"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 220.55, para una sola estufa de 12 kW se puede usar una carga de demanda de 8 kW."},{id:"et_435",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 circuito se requiere para los recept\xE1culos del comedor en una casa?",opciones:["Uno de 15A compartido con luces","Dos de 20A para electrodom\xE9sticos peque\xF1os","Uno de 30A dedicado \xFAnicamente al microondas","Cualquier circuito que tenga cable 14 AWG"],respuesta_correcta:1,explicacion:"El comedor se considera parte de los circuitos de 20A de 'Small Appliance' de la cocina (NEC 210.11)."},{id:"et_436",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es la altura m\xEDnima de una acometida sobre una calle p\xFAblica?",opciones:["10 pies","12 pies","15 pies","18 pies"],respuesta_correcta:3,explicacion:"NEC 230.24(B)(4) requiere un despeje m\xEDnimo de 18 pies sobre calles, avenidas y callejones p\xFAblicos."},{id:"et_437",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o de GEC de cobre se requiere para un servicio de 200A?",opciones:["#8 AWG","#6 AWG","#4 AWG","#2 AWG"],respuesta_correcta:2,explicacion:"Para un servicio de 200A (fase 2/0 o 3/0), la Tabla 250.66 requiere un GEC de cobre calibre #4 AWG."},{id:"et_438",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es la funci\xF3n del Main Bonding Jumper en el sistema el\xE9ctrico?",opciones:["Conectar el panel a la varilla de tierra","Unir el neutral y la tierra en el servicio principal","Proteger los motores contra picos de voltaje","Permitir que el neutral no lleve corriente de retorno"],respuesta_correcta:1,explicacion:"Establece la conexi\xF3n obligatoria entre el neutral y el sistema de tierra en el punto de entrada del servicio."},{id:"et_439",categoria:"ET_GROUNDING",pregunta:"\xBFDe qu\xE9 color debe ser un conductor de fase que no es neutral ni tierra?",opciones:["Blanco o gris \xFAnicamente","Verde con rayas amarillas","Cualquier color excepto blanco, gris o verde","Solo negro, rojo o azul seg\xFAn el voltaje"],respuesta_correcta:2,explicacion:"El c\xF3digo reserva blanco/gris para el neutral y verde para tierra; los dem\xE1s colores son para las fases."},{id:"et_440",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 porcentaje se carga un breaker si la carga funciona por 3 horas o m\xE1s?",opciones:["80% de su capacidad","100% de su capacidad","125% de su capacidad","150% de su capacidad"],respuesta_correcta:0,explicacion:"Para cargas continuas, el dispositivo de sobrecorriente debe ser al menos el 125% de la carga (o la carga el 80% del breaker)."},{id:"et_441",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 significa la marca 'HACR' en un breaker de circuito?",opciones:["High Ampere Circuit Regulator","Heating, Air Conditioning, Refrigeration","Home Appliance Current Resistance","High Altitude Circuit Runner"],respuesta_correcta:1,explicacion:"Indica que el breaker es apto para proteger equipos con compresores herm\xE9ticos de aire acondicionado."},{id:"et_442",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla del NEC se usa para encontrar la FLC de un motor trif\xE1sico?",opciones:["Tabla 430.248","Tabla 430.250","Tabla 310.16","Tabla 250.122"],respuesta_correcta:1,explicacion:"La Tabla 430.250 proporciona los valores de corriente a plena carga para motores de inducci\xF3n trif\xE1sicos."},{id:"et_443",categoria:"ET_MOTORES",pregunta:"\xBFCu\xE1l es el prop\xF3sito del rel\xE9 de sobrecarga (Overload) en un motor?",opciones:["Proteger contra un cortocircuito instant\xE1neo","Proteger el motor contra un calor excesivo lento","Desconectar el motor si el voltaje sube mucho","Invertir la direcci\xF3n de rotaci\xF3n del motor"],respuesta_corrector:1,explicacion:"El overload detecta cuando el motor drena m\xE1s corriente de lo normal por mucho tiempo para evitar que se queme."},{id:"et_444",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 voltaje se obtiene fase-neutral en un sistema Wye de 480V?",opciones:["120 Voltios","208 Voltios","240 Voltios","277 Voltios"],respuesta_correcta:3,explicacion:"En un sistema trif\xE1sico Wye de 480V, cada fase con respecto al neutral entrega 277V."},{id:"et_445",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 sucede con la corriente en el secundario si el voltaje se reduce a la mitad?",opciones:["La corriente se reduce a la mitad","La corriente se mantiene igual","La corriente se duplica","La corriente baja a cero"],respuesta_correcta:2,explicacion:"Por la ley de potencia (P=VI), si el voltaje baja, la corriente disponible sube proporcionalmente."},{id:"et_446",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga m\xEDnima por salida de recept\xE1culo en un local comercial?",opciones:["100 VA","150 VA","180 VA","200 VA"],respuesta_correcta:2,explicacion:"Cada salida de recept\xE1culo (yugo) en locales comerciales se calcula a 180 VA (NEC 220.14)."},{id:"et_447",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 tipo de recept\xE1culo es obligatorio en un ba\xF1o residencial?",opciones:["Recept\xE1culo est\xE1ndar de 15A","Recept\xE1culo con protecci\xF3n GFCI","Recept\xE1culo conectado al circuito de luces","Recept\xE1culo con tapa de hule negra"],respuesta_correcta:1,explicacion:"Todos los recept\xE1culos en ba\xF1os deben tener protecci\xF3n GFCI por seguridad ante el agua (NEC 210.8)."},{id:"et_448",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Divisi\xF3n 1' en una ubicaci\xF3n peligrosa?",opciones:["El peligro solo ocurre por falla accidental","El peligro est\xE1 presente en condiciones normales","No se permite ning\xFAn equipo el\xE9ctrico en el \xE1rea","Solo aplica para voltajes menores a 50V"],respuesta_correcta:1,explicacion:"En Divisi\xF3n 1 el gas o polvo explosivo se espera que est\xE9 presente frecuentemente durante la operaci\xF3n normal."},{id:"et_449",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 calibre m\xEDnimo se permite para cables de termostato Clase 2?",opciones:["14 AWG","16 AWG","18 AWG","22 AWG"],respuesta_correcta:2,explicacion:"Los cables de control y termostatos suelen usar calibres 18 AWG o menores debido a la baja corriente."},{id:"et_450",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es la primera acci\xF3n antes de trabajar en un equipo el\xE9ctrico vivo?",opciones:["Ponerse guantes de cuero \xFAnicamente","Verificar la ausencia de voltaje con un medidor","Informar al supervisor por mensaje de texto","Colocar cinta aislante en todas las terminales"],respuesta_correcta:1,explicacion:"Siempre se debe probar que el circuito no tenga energ\xEDa con un mult\xEDmetro calibrado antes de tocarlo."},{id:"et_451",categoria:"ET_OHM_WATT",pregunta:"Si un circuito de 120V drena 10A, \xBFcu\xE1l es su resistencia?",opciones:["1.2 Ohmios","10 Ohmios","12 Ohmios","120 Ohmios"],respuesta_correcta:2,explicacion:"R = V / I. Entonces: 120V / 10A = 12 Ohmios."},{id:"et_452",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos Watts hay en 2 Caballos de Fuerza (HP)?",opciones:["746 Watts","1000 Watts","1492 Watts","2000 Watts"],respuesta_correcta:2,explicacion:"1 HP = 746W. Entonces: 2 * 746 = 1492 Watts."},{id:"et_453",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC trata sobre la puesta a tierra y uni\xF3n?",opciones:["Art\xEDculo 210","Art\xEDculo 240","Art\xEDculo 250","Art\xEDculo 310"],respuesta_correcta:2,explicacion:"El Art\xEDculo 250 es la secci\xF3n fundamental para todos los sistemas de tierra y uni\xF3n el\xE9ctrica."},{id:"et_454",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa una l\xEDnea negra vertical en el margen de una p\xE1gina del NEC?",opciones:["Esa secci\xF3n es un error de imprenta","Esa parte del c\xF3digo ha sido eliminada","Hubo un cambio respecto a la edici\xF3n anterior","Esa secci\xF3n no aplica en California"],respuesta_correcta:2,explicacion:"Las l\xEDneas en el margen indican que el texto de esa secci\xF3n fue modificado en la versi\xF3n actual del c\xF3digo."},{id:"et_455",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la temperatura m\xE1xima para un conductor tipo THHN?",opciones:["60\xB0C","75\xB0C","90\xB0C","105\xB0C"],respuesta_correcta:2,explicacion:"El cable THHN tiene una clasificaci\xF3n de temperatura de 90\xB0C para ubicaciones secas."},{id:"et_456",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 color debe ser obligatoriamente el conductor neutral (puesto a tierra)?",opciones:["Verde o desnudo","Rojo o Negro","Blanco o Gris","Naranja o Azul"],respuesta_correcta:2,explicacion:"El Art\xEDculo 200.6 requiere que el conductor puesto a tierra sea blanco, gris o marcado con franjas blancas."},{id:"et_457",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el porcentaje m\xE1ximo de llenado para 3 o m\xE1s conductores en un tubo?",opciones:["31%","40%","53%","60%"],respuesta_correcta:1,explicacion:"Para 3 o m\xE1s conductores, el NEC permite ocupar hasta el 40% del \xE1rea interna del conduit."},{id:"et_458",categoria:"ET_CANALIZACIONES",pregunta:"\xBFA qu\xE9 distancia de una caja se debe soportar la tuber\xEDa EMT?",opciones:["A no m\xE1s de 1 pie","A no m\xE1s de 3 pies","A no m\xE1s de 5 pies","A no m\xE1s de 10 pies"],respuesta_correcta:1,explicacion:"El EMT debe asegurarse a una distancia m\xE1xima de 3 pies de cada terminaci\xF3n (NEC 358.30)."},{id:"et_459",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1ntos recept\xE1culos d\xFAplex se permiten en un circuito de 20A comercial?",opciones:["10 recept\xE1culos","12 recept\xE1culos","13 recept\xE1culos","Sin l\xEDmite definido"],respuesta_correcta:2,explicacion:"Calculando 180 VA por salida: (120V * 20A) / 180 VA = 13.33. El l\xEDmite es 13 recept\xE1culos."},{id:"et_460",categoria:"ET_CIRCUITOS",pregunta:"\xBFD\xF3nde es obligatorio instalar un recept\xE1culo GFCI en una vivienda?",opciones:["Dormitorios y pasillos","Cerca de cualquier lavabo o fregadero","En el centro de la sala de estar","Solo en el recept\xE1culo del refrigerador"],respuesta_correcta:1,explicacion:"NEC 210.8 requiere GFCI en \xE1reas h\xFAmedas, incluyendo cualquier recept\xE1culo a menos de 6 pies de un lavabo."},{id:"et_461",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el n\xFAmero m\xE1ximo de desconectadores permitidos en un servicio?",opciones:["Dos desconectadores","Cuatro desconectadores","Seis desconectadores","Ocho desconectadores"],respuesta_correcta:2,explicacion:"La regla de los seis permite hasta 6 desconectadores agrupados para un solo servicio el\xE9ctrico."},{id:"et_462",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el espacio libre m\xEDnimo de cables de servicio sobre un techo plano?",opciones:["3 pies","8 pies","10 pies","12 pies"],respuesta_correcta:1,explicacion:"NEC 230.24(A) requiere un despeje de 8 pies sobre superficies de techos con pendientes bajas."},{id:"et_463",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el calibre m\xEDnimo de un GEC de cobre para una varilla de tierra?",opciones:["#10 AWG","#8 AWG","#6 AWG","#4 AWG"],respuesta_correcta:2,explicacion:"El conductor del electrodo de tierra que va a una varilla no necesita ser mayor a #6 AWG cobre."},{id:"et_464",categoria:"ET_GROUNDING",pregunta:"\xBFDe qu\xE9 color debe ser el conductor de puesta a tierra de equipos (EGC)?",opciones:["Blanco o gris","Verde o desnudo","Rojo o negro","Cualquier color con cinta blanca"],respuesta_correcta:1,explicacion:"El Art\xEDculo 250.119 exige que los conductores de tierra sean verdes, verdes con raya amarilla o desnudos."},{id:"et_465",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el amperaje est\xE1ndar que sigue despu\xE9s de los 100 Amperios?",opciones:["110 Amperios","125 Amperios","150 Amperios","175 Amperios"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 240.6(A), el siguiente tama\xF1o de breaker o fusible est\xE1ndar despu\xE9s de 100A es 110A."},{id:"et_466",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 breaker protege espec\xEDficamente contra arcos el\xE9ctricos en la pared?",opciones:["GFCI (Ground Fault)","AFCI (Arc Fault)","MCCB (Case Breaker)","GFI (Indicator)"],respuesta_correcta:1,explicacion:"El AFCI detecta las firmas electr\xF3nicas de arcos peligrosos para prevenir incendios en el cableado."},{id:"et_467",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se calcula el desconectador de un motor?",opciones:["100%","115%","125%","150%"],respuesta_correcta:1,explicacion:"El desconectador debe tener una clasificaci\xF3n de al menos el 115% de la corriente de placa (NEC 430.110)."},{id:"et_468",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla se usa para encontrar la FLC de un motor monof\xE1sico de 120V?",opciones:["Tabla 430.247","Tabla 430.248","Tabla 430.250","Tabla 430.52"],respuesta_correcta:1,explicacion:"La Tabla 430.248 proporciona los valores para motores de corriente alterna monof\xE1sicos."},{id:"et_469",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 voltaje hay entre dos fases en un sistema trif\xE1sico 'Wye' de 208/120V?",opciones:["120 Voltios","208 Voltios","240 Voltios","277 Voltios"],respuesta_correcta:1,explicacion:"En un sistema Wye de 208V, el voltaje entre dos fases cualesquiera es de 208V."},{id:"et_470",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFC\xF3mo se llama el devanado que se conecta a la fuente de energ\xEDa?",opciones:["Secundario","De control","Primario","Auxiliar"],respuesta_correcta:2,explicacion:"El primario es el devanado que recibe el voltaje de entrada al transformador."},{id:"et_471",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es el espacio m\xEDnimo de una luminaria incandescente de un estante?",opciones:["3 pulgadas","6 pulgadas","12 pulgadas","18 pulgadas"],respuesta_correcta:2,explicacion:"Se requiere un espacio de 12 pulgadas para luminarias incandescentes en cl\xF3sets por riesgo de incendio."},{id:"et_472",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 altura m\xEDnima debe estar una luminaria sobre una piscina?",opciones:["8 pies","10 pies","12 pies","20 pies"],respuesta_correcta:2,explicacion:"NEC 680.22 requiere que las luminarias est\xE9n al menos a 12 pies sobre el nivel del agua de la piscina."},{id:"et_473",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Clase I' en lugares peligrosos?",opciones:["Presencia de polvos inflamables","Presencia de gases o vapores inflamables","Presencia de fibras de textiles","Presencia de agua en el equipo"],respuesta_correcta:1,explicacion:"La Clase I define \xE1reas donde hay gases o vapores que pueden causar explosiones."},{id:"et_474",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 clase de circuito de control est\xE1 limitado a 100 VA?",opciones:["Clase 1","Clase 2","Clase 3","Clase 4"],respuesta_correcta:1,explicacion:"Los circuitos de Clase 2 tienen una limitaci\xF3n de potencia de 100 VA por seguridad."},{id:"et_475",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa 'LOTO' en seguridad industrial?",opciones:["Line Off, Time Out","Lockout / Tagout","Low Output, Total Ohm","Live Only, Trained Only"],respuesta_correcta:1,explicacion:"Es el procedimiento de bloqueo y etiquetado para asegurar que nadie encienda el equipo durante el mantenimiento."},{id:"et_476",categoria:"ET_OHM_WATT",pregunta:"Si la potencia es 2400W y el voltaje es 240V, \xBFcu\xE1l es la corriente?",opciones:["10 Amperios","20 Amperios","24 Amperios","48 Amperios"],respuesta_correcta:0,explicacion:"I = P / V. Entonces: 2400W / 240V = 10A."},{id:"et_477",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos miliamperios hay en 1 Amperio?",opciones:["10 mA","100 mA","1000 mA","10000 mA"],respuesta_correcta:2,explicacion:"1 Amperio equivale exactamente a 1000 miliamperios."},{id:"et_478",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es la funci\xF3n principal del NEC seg\xFAn el Art\xEDculo 90.1?",opciones:["Manual de instrucci\xF3n para aprendices","Salvaguardia pr\xE1ctica de personas y propiedades","Gu\xEDa de dise\xF1o para eficiencia energ\xE9tica","Establecer los precios de la mano de obra"],respuesta_correcta:1,explicacion:"La intenci\xF3n del c\xF3digo es la seguridad y protecci\xF3n de la vida y propiedad contra riesgos el\xE9ctricos."},{id:"et_479",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Amperage' (Ampacidad)?",opciones:["La velocidad de la corriente el\xE9ctrica","La cantidad de energ\xEDa total del sistema","La corriente m\xE1xima que un cable soporta sin da\xF1arse","El voltaje total dividido por la resistencia"],respuesta_correcta:2,explicacion:"La ampacidad es la capacidad de conducci\xF3n de corriente continua de un conductor bajo condiciones espec\xEDficas."},{id:"et_480",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la letra 'W' en un aislamiento como el THWN?",opciones:["Wattage (Potencia alta)","Weather (Resistente al clima)","Wet (Apto para lugares mojados)","Wire (Tipo de alambre s\xF3lido)"],respuesta_correcta:2,explicacion:"La 'W' indica que el aislamiento es resistente a la humedad y puede usarse en lugares mojados o enterrado."},{id:"et_481",categoria:"ET_CONDUCTORES",pregunta:"\xBFA qu\xE9 porcentaje se reduce la ampacidad si hay 4-6 conductores en un tubo?",opciones:["100%","90%","80%","70%"],respuesta_correcta:2,explicacion:"Si hay de 4 a 6 conductores portadores de corriente, se debe reducir la ampacidad al 80% (Tabla 310.15)."},{id:"et_482",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura para un conduit de PVC de 1/2 pulgada?",opciones:["4 pulgadas","5 pulgadas","6 pulgadas","8 pulgadas"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 2 del Cap\xEDtulo 9, el radio de curvatura para tuber\xEDa de 1/2 pulgada es de 4 pulgadas."},{id:"et_483",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 tipo de tuber\xEDa no se permite como soporte de luminarias?",opciones:["RMC (R\xEDgido)","IMC (Intermedio)","EMT (El\xE9ctrico Met\xE1lico)","FMC (Flexible)"],respuesta_correcta:3,explicacion:"El conduit flexible no tiene la integridad estructural para soportar el peso de luminarias u otros equipos."},{id:"et_484",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para un recept\xE1culo d\xFAplex comercial?",opciones:["100 VA","150 VA","180 VA","200 VA"],respuesta_correcta:2,explicacion:"Cada salida de recept\xE1culo d\xFAplex comercial se calcula a 180 VA seg\xFAn NEC 220.14(I)."},{id:"et_485",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 distancia m\xE1xima puede haber entre recept\xE1culos en una sala de casa?",opciones:["6 pies","10 pies","12 pies","15 pies"],respuesta_correcta:2,explicacion:"Ning\xFAn punto en la l\xEDnea del suelo debe estar a m\xE1s de 6 pies de un recept\xE1culo (espaciado total de 12 pies)."},{id:"et_486",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de un GEC de cobre para un servicio de 400A?",opciones:["#4 AWG","#2 AWG","#1/0 AWG","#2/0 AWG"],respuesta_correcta:2,explicacion:"Para un servicio de 400A (fases 500 kcmil), se requiere un GEC de cobre calibre #1/0 (Tabla 250.66)."},{id:"et_487",categoria:"ET_SERVICIO",pregunta:"\xBFA qu\xE9 distancia de una ventana debe estar la acometida el\xE9ctrica?",opciones:["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 5 pies"],respuesta_correcta:2,explicacion:"Los conductores de acometida deben estar al menos a 3 pies de ventanas que puedan abrirse (NEC 230.9)."},{id:"et_488",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 significa un sistema de puesta a tierra 'Solidly Grounded'?",opciones:["Que la conexi\xF3n se hizo con soldadura s\xF3lida","Que el neutral se conecta a tierra sin resistencia","Que el sistema est\xE1 enterrado en suelo rocoso","Que el sistema est\xE1 protegido por un breaker s\xF3lido"],respuesta_correcta:1,explicacion:"Significa que el conductor neutral est\xE1 conectado directamente al sistema de electrodos de tierra."},{id:"et_489",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el prop\xF3sito del 'Bonding'?",opciones:["Atraer rayos hacia la varilla de tierra","Aislar los cables de fase del panel met\xE1lico","Unir todas las partes met\xE1licas para evitar diferencias de voltaje","Permitir que el neutral no lleve corriente"],respuesta_correcta:2,explicacion:"El bonding asegura que todas las partes met\xE1licas est\xE9n al mismo potencial el\xE9ctrico para evitar choques."},{id:"et_490",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para un fusible tipo tap\xF3n (Plug Fuse)?",opciones:["120 Voltios","125 Voltios","240 Voltios","250 Voltios"],respuesta_correcta:1,explicacion:"Los fusibles de tipo tap\xF3n est\xE1n dise\xF1ados para sistemas que no excedan los 125 voltios entre conductores."},{id:"et_491",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 distancia se aplica la 'Tap Rule' de 10 pies?",opciones:["A cualquier distancia en naves industriales","Solo si el cable termina en un breaker o desconectador","Solo para alimentar motores de m\xE1s de 10 HP","Solo si el cable es de cobre s\xF3lido #12"],respuesta_correcta:1,explicacion:"La regla de los 10 pies exige que los conductores terminen en un dispositivo que limite la carga."},{id:"et_492",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se calcula el breaker inicial de un motor?",opciones:["115%","125%","250%","400%"],respuesta_correcta:2,explicacion:"Para breakers de tiempo inverso, el Art\xEDculo 430 permite iniciar el c\xE1lculo al 250% de la corriente nominal."},{id:"et_493",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa un motor 'TEFC'?",opciones:["Totalmente eficiente y fr\xEDo (Efficient)","Totalmente cerrado enfriado por ventilador (Enclosed)","Motor de tres fases con control (Three-phase)","Motor t\xE9rmico de enfriamiento constante (Thermal)"],respuesta_correcta:1,explicacion:"Totally Enclosed Fan Cooled: el aire de enfriamiento pasa por fuera de la carcasa sellada del motor."},{id:"et_494",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 sucede con el voltaje si conectamos un transformador 480:120 al rev\xE9s?",opciones:["El transformador explotar\xE1 de inmediato","El voltaje de salida ser\xE1 de 1920 Voltios","El voltaje de salida ser\xE1 de 30 Voltios","El transformador no funcionar\xE1"],respuesta_correcta:1,explicacion:"Funcionar\xE1 como elevador multiplicando el voltaje por 4 (480 * 4 = 1920V)."},{id:"et_495",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 componente protege a un transformador contra sobrecalentamiento interno?",opciones:["El fusible del primario \xFAnicamente","El cable de tierra del chasis","Un sensor de temperatura o rel\xE9 t\xE9rmico","La conexi\xF3n neutral del secundario"],respuesta_correcta:2,explicacion:"Muchos transformadores tienen sensores t\xE9rmicos que cortan la energ\xEDa si el n\xFAcleo se calienta demasiado."},{id:"et_496",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga VA m\xEDnima por cada pie lineal de vitrina comercial?",opciones:["90 VA","150 VA","200 VA","360 VA"],respuesta_correcta:2,explicacion:"NEC 220.14(E) requiere calcular 200 VA por cada pie lineal de vitrina de exhibici\xF3n."},{id:"et_497",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 distancia de una tina de ba\xF1o debe estar un recept\xE1culo?",opciones:["Al menos 1 pie","Al menos 3 pies","Al menos 6 pies","No hay distancia si es GFCI"],respuesta_correcta:1,explicacion:"El c\xF3digo proh\xEDbe recept\xE1culos dentro de la zona de 3 pies horizontales de una tina o regadera (NEC 406.9)."},{id:"et_498",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Intrinsically Safe' (Intr\xEDnsecamente Seguro)?",opciones:["Que el equipo est\xE1 guardado bajo llave","Que la energ\xEDa es tan baja que no puede causar una chispa","Que el equipo tiene un extintor de fuego integrado","Que el equipo solo se enciende si el aire es puro"],respuesta_correcta:1,explicacion:"Limita la energ\xEDa el\xE9ctrica y t\xE9rmica para que no pueda encender una atm\xF3sfera explosiva."},{id:"et_499",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 tipo de cable de alarma de fuego es apto para ductos de aire (Plenum)?",opciones:["FPL","FPLR","FPLP","NPLF"],respuesta_correcta:2,explicacion:"La letra 'P' (FPLP) indica que el cable es Plenum Rated y emite poco humo en caso de incendio."},{id:"et_500",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es el l\xEDmite de voltaje para considerar un circuito 'bajo voltaje' por OSHA?",opciones:["24 Voltios","50 Voltios","120 Voltios","600 Voltios"],respuesta_correcta:1,explicacion:"OSHA establece que a partir de 50V se requieren medidas de protecci\xF3n mayores contra choques el\xE9ctricos."},{id:"et_501",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la potencia total de una carga trif\xE1sica de 208V con 30A y un factor de potencia de 0.80?",opciones:["4,992 Watts","8,640 Watts","10,800 Watts","12,480 Watts"],respuesta_correcta:1,explicacion:"En trif\xE1sico: P = V * I * 1.732 * FP. Entonces: 208 * 30 * 1.732 * 0.80 = 8,646 Watts."},{id:"et_502",categoria:"ET_OHM_WATT",pregunta:"Si un circuito de 120V tiene una resistencia de 20 Ohmios, \xBFcu\xE1nta potencia se disipa en forma de calor?",opciones:["60 Watts","120 Watts","600 Watts","720 Watts"],respuesta_correcta:3,explicacion:"P = V\xB2 / R. Entonces: 120 * 120 / 20 = 14,400 / 20 = 720 Watts."},{id:"et_503",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC regula el uso de cables tipo AC (Armor Clad)?",opciones:["Art\xEDculo 320","Art\xEDculo 330","Art\xEDculo 348","Art\xEDculo 350"],respuesta_correcta:0,explicacion:"El Art\xEDculo 320 cubre los requisitos de instalaci\xF3n y soporte para el cable con armadura met\xE1lica tipo AC."},{id:"et_504",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el espacio de trabajo m\xEDnimo (profundidad) para un equipo de 120V seg\xFAn la Condici\xF3n 1?",opciones:["2 pies (60 cm)","3 pies (90 cm)","3.5 pies (1.1 m)","4 pies (1.2 m)"],respuesta_correcta:1,explicacion:"Para sistemas de 0-150V a tierra, la Tabla 110.26(A)(1) requiere un m\xEDnimo de 3 pies de profundidad."},{id:"et_505",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la letra 'R' en el aislamiento de un conductor tipo RHW?",opciones:["Resistant (Resistente)","Rubber (Hule/Caucho)","Rigid (R\xEDgido)","Rain-rated (Para lluvia)"],respuesta_correcta:1,explicacion:"La 'R' indica que el material de aislamiento es de hule (Rubber) o un pol\xEDmero de hule sint\xE9tico."},{id:"et_506",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un conductor #1/0 AWG de cobre THWN-2 a 90\xB0C?",opciones:["125 Amperios","150 Amperios","170 Amperios","190 Amperios"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.16, el cable #1/0 de cobre en la columna de 90\xB0C tiene una capacidad de 170A."},{id:"et_507",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el soporte m\xE1ximo permitido para una tuber\xEDa de PVC de 2 pulgadas?",opciones:["Cada 3 pies","Cada 5 pies","Cada 10 pies","Cada 15 pies"],respuesta_correcta:1,explicacion:"El Art\xEDculo 352.30(A) indica que para tuber\xEDa de PVC de 2 pulgadas, el soporte debe ser cada 5 pies."},{id:"et_508",categoria:"ET_CANALIZACIONES",pregunta:"\xBFA qu\xE9 distancia m\xE1xima de una caja de EMT debe colocarse el primer soporte?",opciones:["1 pie (12 pulgadas)","3 pies (36 pulgadas)","5 pies (60 pulgadas)","10 pies (120 pulgadas)"],respuesta_correcta:1,explicacion:"El EMT debe asegurarse a una distancia m\xE1xima de 3 pies (900 mm) de cada caja, gabinete o terminaci\xF3n."},{id:"et_509",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga m\xEDnima VA para un circuito derivado de 20A en un ba\xF1o?",opciones:["1200 VA","1500 VA","1800 VA","No se especifica VA"],respuesta_correcta:3,explicacion:"El NEC requiere el circuito de 20A para el ba\xF1o, pero no asigna un valor de VA espec\xEDfico en los c\xE1lculos de carga generales."},{id:"et_510",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 tipo de protecci\xF3n es obligatoria para recept\xE1culos en un s\xF3tano terminado?",opciones:["Protecci\xF3n GFCI \xFAnicamente","Protecci\xF3n AFCI obligatoria","Solo recept\xE1culos tipo TR","Cualquier recept\xE1culo est\xE1ndar"],respuesta_correcta:1,explicacion:"En viviendas, los s\xF3tanos terminados (\xE1reas habitables) requieren protecci\xF3n AFCI para prevenir incendios (NEC 210.12)."},{id:"et_511",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el despeje m\xEDnimo de conductores de acometida sobre un techo con pendiente de 4/12 o mayor?",opciones:["3 pies","5 pies","8 pies","10 pies"],respuesta_correcta:0,explicacion:"Si la pendiente del techo es de al menos 4 pulgadas por cada 12 pulgadas, el despeje se puede reducir a 3 pies (NEC 230.24)."},{id:"et_512",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o de cable de cobre se requiere para una acometida residencial de 150A?",opciones:["#2 AWG","#1 AWG","#1/0 AWG","#2/0 AWG"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 310.12, un servicio residencial de 150A requiere conductores de fase de cobre calibre #1 AWG."},{id:"et_513",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es la longitud m\xEDnima requerida para un electrodo de varilla (Ground Rod)?",opciones:["5 pies (1.5 m)","6 pies (1.8 m)","8 pies (2.4 m)","10 pies (3.0 m)"],respuesta_correcta:2,explicacion:"El Art\xEDculo 250.52(A)(5) establece que las varillas de tierra deben tener al menos 8 pies de longitud en contacto con el suelo."},{id:"et_514",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 calibre de EGC de cobre se requiere para un circuito protegido por un breaker de 30A?",opciones:["#14 AWG","#12 AWG","#10 AWG","#8 AWG"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 250.122, un dispositivo de sobrecorriente de 30A requiere un cable de tierra de equipo de #10 AWG cobre."},{id:"et_515",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 significa un breaker marcado como 'High Interrupting Capacity'?",opciones:["Que puede manejar voltajes de m\xE1s de 1000V","Que tiene un valor de AIC superior al est\xE1ndar (ej. 22k o 65k)","Que no se dispara por sobrecargas peque\xF1as","Que se puede usar como switch de motor"],respuesta_correcta:1,explicacion:"Estos breakers est\xE1n dise\xF1ados para sistemas donde la corriente de falla potencial es muy elevada."},{id:"et_516",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el amperaje est\xE1ndar que sigue despu\xE9s de los 35 Amperios?",opciones:["38 Amperios","40 Amperios","45 Amperios","50 Amperios"],respuesta_correcta:1,explicacion:"La Tabla 240.6(A) indica que el siguiente tama\xF1o est\xE1ndar de fusible o breaker despu\xE9s de 35A es 40A."},{id:"et_517",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se calcula el breaker de tiempo inverso para un motor de inducci\xF3n?",opciones:["125%","175%","250%","300%"],respuesta_correcta:2,explicacion:"El Art\xEDculo 430.52 permite dimensionar el breaker hasta un 250% de la corriente nominal para permitir el arranque."},{id:"et_518",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa 'NEMA Design B' en la placa de identificaci\xF3n de un motor?",opciones:["El tama\xF1o del eje del motor","Motor con torque de arranque normal y corriente normal","Motor de alta eficiencia para uso en exteriores","Motor que solo funciona en 208V"],respuesta_correcta:1,explicacion:"Design B es el tipo m\xE1s com\xFAn de motor industrial, con caracter\xEDsticas de torque y corriente balanceadas."},{id:"et_519",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es la corriente secundaria de un transformador de 50 KVA trif\xE1sico a 480V?",opciones:["60.1 Amperios","104.2 Amperios","120.4 Amperios","208.2 Amperios"],respuesta_correcta:0,explicacion:"I = VA / (V * \u221A3). Entonces: 50,000 / (480 * 1.732) = 60.14 Amperios."},{id:"et_520",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 conexi\xF3n se usa para obtener 120V de un sistema trif\xE1sico de 208V?",opciones:["Conexi\xF3n Delta de 3 hilos","Conexi\xF3n Wye (Estrella) de 4 hilos","Conexi\xF3n Delta abierta con capacitor","Conexi\xF3n en serie de dos transformadores"],respuesta_correcta:1,explicacion:"La conexi\xF3n Wye proporciona un punto neutral que permite obtener 120V entre cualquier fase y el neutral."},{id:"et_521",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga VA calculada para un letrero (Sign) comercial?",opciones:["1000 VA","1200 VA","1500 VA","2000 VA"],respuesta_correcta:1,explicacion:"NEC 220.14(F) requiere asignar un m\xEDnimo de 1200 VA para cada circuito derivado de letreros comerciales."},{id:"et_522",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 altura m\xEDnima debe estar el punto m\xE1s bajo de una luminaria sobre el piso de una cochera?",opciones:["6 pies","6.5 pies","7 pies","No hay altura m\xEDnima"],respuesta_correcta:3,explicacion:"El NEC no especifica una altura m\xEDnima para luminarias en garajes, siempre que no representen un peligro f\xEDsico."},{id:"et_523",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 clase define una ubicaci\xF3n con fibras textiles inflamables?",opciones:["Clase I","Clase II","Clase III","Clase IV"],respuesta_correcta:2,explicacion:"La Clase III se refiere a \xE1reas con fibras o part\xEDculas vol\xE1tiles inflamables (como aserr\xEDn o algod\xF3n)."},{id:"et_524",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 tipo de cable se permite usar para termostatos en una zona de retorno de aire (Plenum)?",opciones:["Cable tipo CL2","Cable tipo CL2R","Cable tipo CL2P","Cable tipo NM-B"],respuesta_correcta:2,explicacion:"La 'P' (CL2P) indica que el cable est\xE1 listado para uso en plenums debido a su baja emisi\xF3n de humo."},{id:"et_525",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para el que est\xE1n certificados los guantes de hule Clase 0?",opciones:["500 Voltios","1,000 Voltios","5,000 Voltios","17,000 Voltios"],respuesta_correcta:1,explicacion:"Los guantes de Clase 0 est\xE1n dise\xF1ados y certificados para trabajar en sistemas de hasta 1,000V AC."},{id:"et_526",categoria:"ET_OHM_WATT",pregunta:"Si un calentador de 480V consume 10 Amperios, \xBFcu\xE1ntos Watts est\xE1 produciendo?",opciones:["48 Watts","480 Watts","4,800 Watts","9,600 Watts"],respuesta_correcta:2,explicacion:"P = V * I. Entonces: 480V * 10A = 4,800 Watts."},{id:"et_527",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la resistencia de un motor de 1/2 HP que drena 5 Amperios a 120V?",opciones:["12 Ohmios","24 Ohmios","48 Ohmios","120 Ohmios"],respuesta_correcta:1,explicacion:"R = V / I. Entonces: 120V / 5A = 24 Ohmios."},{id:"et_528",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC trata sobre la protecci\xF3n de circuitos contra sobrecorriente?",opciones:["Art\xEDculo 210","Art\xEDculo 240","Art\xEDculo 250","Art\xEDculo 310"],respuesta_correcta:1,explicacion:"El Art\xEDculo 240 contiene los requisitos para breakers, fusibles y la protecci\xF3n de conductores."},{id:"et_529",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Duty, Continuous' seg\xFAn el Art\xEDculo 100?",opciones:["Operaci\xF3n por m\xE1s de 1 hora sin parar","Operaci\xF3n con carga constante por tiempo indefinido","Operaci\xF3n que solo ocurre durante el d\xEDa","Operaci\xF3n que se detiene cada 3 horas"],respuesta_correcta:1,explicacion:"La carga continua es aquella donde la corriente m\xE1xima se mantiene por 3 horas o m\xE1s."},{id:"et_530",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 color identifica a la fase B en un sistema de 120/240V Delta (High-Leg)?",opciones:["Negro","Rojo","Naranja","Azul"],respuesta_correcta:2,explicacion:"El NEC requiere que la fase con el voltaje m\xE1s alto a tierra en un sistema Delta se identifique con color naranja."},{id:"et_531",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un cable #8 AWG de cobre THHN a 90\xB0C?",opciones:["40 Amperios","50 Amperios","55 Amperios","60 Amperios"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.16, el cable #8 de cobre en la columna de 90\xB0C tiene una ampacidad de 55A."},{id:"et_532",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura m\xEDnimo para un conduit de PVC de 3 pulgadas?",opciones:["10 pulgadas","13 pulgadas","15 pulgadas","18 pulgadas"],respuesta_correcta:1,explicacion:"El Cap\xEDtulo 9, Tabla 2 especifica un radio de 13 pulgadas para tuber\xEDa de PVC de 3 pulgadas."},{id:"et_533",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el porcentaje m\xE1ximo de llenado para 2 conductores en una canalizaci\xF3n?",opciones:["31%","40%","53%","60%"],respuesta_correcta:0,explicacion:"Para exactamente dos conductores dentro de una tuber\xEDa, el l\xEDmite de llenado es del 31% del \xE1rea interna."},{id:"et_534",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para un calentador de agua de 3,000W?",opciones:["3,000 VA","3,750 VA","4,500 VA","6,000 VA"],respuesta_correcta:0,explicacion:"Los calentadores de agua se consideran cargas resistivas y se calculan al 100% (3,000 VA)."},{id:"et_535",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 tipo de recept\xE1culo es obligatorio en un \xE1rea de lavander\xEDa residencial?",opciones:["Recept\xE1culo est\xE1ndar \xFAnicamente","Recept\xE1culo con protecci\xF3n GFCI \xFAnicamente","Recept\xE1culo con protecci\xF3n AFCI \xFAnicamente","Recept\xE1culo con protecci\xF3n GFCI y AFCI"],respuesta_correcta:3,explicacion:"NEC 210.8 y 210.12 requieren ambas protecciones (GFCI para humedad y AFCI para incendios) en lavander\xEDas."},{id:"et_536",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el n\xFAmero m\xE1ximo de desconectadores permitidos para un servicio?",opciones:["Dos","Cuatro","Seis","Ocho"],respuesta_correcta:2,explicacion:"La regla de los seis (NEC 230.71) permite hasta 6 desconectadores agrupados para desconectar la energ\xEDa."},{id:"et_537",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o de GEC de aluminio se requiere para un servicio de 200A?",opciones:["#4 AWG","#2 AWG","#1 AWG","#1/0 AWG"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 250.66, para un servicio de 200A (fases 2/0 cobre o 4/0 aluminio), se requiere un GEC de aluminio #2."},{id:"et_538",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 color de conductor est\xE1 reservado para la puesta a tierra de equipos?",opciones:["Blanco","Gris","Verde","Naranja"],respuesta_correcta:2,explicacion:"El color verde (o verde con rayas amarillas) identifica exclusivamente a los conductores de tierra."},{id:"et_539",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el prop\xF3sito del Main Bonding Jumper?",opciones:["Conectar el panel a la varilla de tierra","Unir el neutral con la tierra en el servicio principal","Proteger los motores contra rayos","Permitir que el neutral no lleve corriente"],respuesta_correcta:1,explicacion:"Este puente establece la conexi\xF3n cr\xEDtica entre el neutral y la tierra en el equipo de servicio principal."},{id:"et_540",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para fusibles tipo tap\xF3n (Plug Fuses)?",opciones:["125 Voltios","150 Voltios","240 Voltios","250 Voltios"],respuesta_correcta:0,explicacion:"Los fusibles de tipo tap\xF3n est\xE1n limitados por el c\xF3digo a sistemas de no m\xE1s de 125 voltios entre conductores."},{id:"et_541",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 porcentaje se carga un breaker para una carga continua?",opciones:["80%","100%","125%","150%"],respuesta_correcta:0,explicacion:"Para cargas continuas (3 horas o m\xE1s), el dispositivo de sobrecorriente debe ser al menos el 125% de la carga."},{id:"et_542",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla del NEC se usa para motores de Corriente Continua (DC)?",opciones:["Tabla 430.247","Tabla 430.248","Tabla 430.250","Tabla 430.52"],respuesta_correcta:0,explicacion:"La Tabla 430.247 proporciona los valores de corriente nominal para motores de corriente continua."},{id:"et_543",categoria:"ET_MOTORES",pregunta:"\xBFCu\xE1l es la ampacidad m\xEDnima del conductor para un motor con FLC de 20A?",opciones:["20 Amperios","23 Amperios","25 Amperios","30 Amperios"],respuesta_correcta:2,explicacion:"NEC 430.22 requiere que el conductor soporte el 125% de la carga: 20A * 1.25 = 25A."},{id:"et_544",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 voltaje se obtiene fase-neutral en un sistema Wye de 208V?",opciones:["110 Voltios","115 Voltios","120 Voltios","208 Voltios"],respuesta_correcta:2,explicacion:"En un sistema trif\xE1sico Wye de 208V, cada fase con respecto al neutral entrega 120V."},{id:"et_545",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFC\xF3mo se llama el devanado que se conecta a la fuente de energ\xEDa?",opciones:["Secundario","De control","Primario","Auxiliar"],respuesta_correcta:2,explicacion:"El primario es el devanado que recibe el voltaje de entrada al transformador."},{id:"et_546",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga VA m\xEDnima para una salida de recept\xE1culo d\xFAplex comercial?",opciones:["100 VA","150 VA","180 VA","200 VA"],respuesta_correcta:2,explicacion:"Cada salida de recept\xE1culo d\xFAplex comercial se calcula a 180 VA seg\xFAn NEC 220.14(I)."},{id:"et_547",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 tipo de recept\xE1culo es obligatorio en un ba\xF1o residencial?",opciones:["Recept\xE1culo est\xE1ndar","Recept\xE1culo con protecci\xF3n AFCI","Recept\xE1culo con protecci\xF3n GFCI","Recept\xE1culo tipo Twist-Lock"],respuesta_correcta:2,explicacion:"Todos los recept\xE1culos en ba\xF1os deben tener protecci\xF3n GFCI por seguridad ante el agua."},{id:"et_548",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Divisi\xF3n 1' en una ubicaci\xF3n peligrosa?",opciones:["Peligro solo por falla accidental","Peligro presente en condiciones normales","No se permite ning\xFAn equipo el\xE9ctrico","Solo para voltajes menores a 50V"],respuesta_correcta:1,explicacion:"En Divisi\xF3n 1 el material explosivo se espera que est\xE9 presente frecuentemente durante la operaci\xF3n normal."},{id:"et_549",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 calibre m\xEDnimo se permite para cables de termostato Clase 2?",opciones:["14 AWG","16 AWG","18 AWG","22 AWG"],respuesta_correcta:2,explicacion:"Los cables de control y termostatos suelen usar calibres 18 AWG debido a la baja corriente."},{id:"et_550",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa 'LOTO' en seguridad el\xE9ctrica?",opciones:["Line Off, Time Out","Lockout / Tagout","Low Output, Total Ohm","Live Only, Trained Only"],respuesta_correcta:1,explicacion:"Es el procedimiento de bloqueo y etiquetado para asegurar que nadie encienda el equipo durante el mantenimiento."},{id:"et_551",categoria:"ET_OHM_WATT",pregunta:"Si la potencia es 1200W y el voltaje es 120V, \xBFcu\xE1l es la corriente?",opciones:["1 Amperio","10 Amperios","12 Amperios","120 Amperios"],respuesta_correcta:1,explicacion:"I = P / V. Entonces: 1200W / 120V = 10A."},{id:"et_552",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos miliamperios hay en 1 Amperio?",opciones:["10 mA","100 mA","1000 mA","10000 mA"],respuesta_correcta:2,explicacion:"1 Amperio equivale exactamente a 1000 miliamperios."},{id:"et_553",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es la funci\xF3n del NEC seg\xFAn el Art\xEDculo 90.1?",opciones:["Manual de dise\xF1o el\xE9ctrico","Salvaguardia de personas y propiedades","Libro de precios de materiales","Gu\xEDa de mantenimiento industrial"],respuesta_correcta:1,explicacion:"La intenci\xF3n del c\xF3digo es la seguridad y protecci\xF3n contra los riesgos del uso de la electricidad."},{id:"et_554",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Ampacity'?",opciones:["Velocidad de la corriente","Voltaje total del sistema","Corriente m\xE1xima que un cable soporta sin da\xF1arse","Resistencia interna del cobre"],respuesta_correcta:2,explicacion:"La ampacidad es la capacidad de conducci\xF3n de corriente de un conductor bajo condiciones espec\xEDficas."},{id:"et_555",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la letra 'W' en un cable tipo THWN?",opciones:["Wattage (Potencia)","Weather (Clima)","Wet (Apto para lugares mojados)","Wire (Alambre)"],respuesta_correcta:2,explicacion:"La 'W' indica que el aislamiento es resistente a la humedad y puede usarse en lugares mojados."},{id:"et_556",categoria:"ET_CONDUCTORES",pregunta:"\xBFA qu\xE9 porcentaje se reduce la ampacidad si hay 4-6 conductores en un tubo?",opciones:["100%","90%","80%","70%"],respuesta_correcta:2,explicacion:"De 4 a 6 conductores requieren una reducci\xF3n de ampacidad al 80% (Tabla 310.15)."},{id:"et_557",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura para un conduit de PVC de 1/2 pulgada?",opciones:["4 pulgadas","5 pulgadas","6 pulgadas","8 pulgadas"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 2 del Cap\xEDtulo 9, el radio para tuber\xEDa de 1/2 pulgada es de 4 pulgadas."},{id:"et_558",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 tipo de tuber\xEDa no se permite como soporte de luminarias?",opciones:["RMC (R\xEDgido)","IMC (Intermedio)","EMT (El\xE9ctrico Met\xE1lico)","FMC (Flexible)"],respuesta_correcta:3,explicacion:"El conduit flexible no tiene la rigidez estructural para soportar el peso de luminarias."},{id:"et_559",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para un recept\xE1culo d\xFAplex comercial?",opciones:["100 VA","150 VA","180 VA","200 VA"],respuesta_correcta:2,explicacion:"Cada salida de recept\xE1culo d\xFAplex comercial se calcula a 180 VA."},{id:"et_560",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 distancia m\xE1xima puede haber entre recept\xE1culos en una sala de casa?",opciones:["6 pies","10 pies","12 pies","15 pies"],respuesta_correcta:2,explicacion:"Ning\xFAn punto en el suelo debe estar a m\xE1s de 6 pies de un recept\xE1culo (espaciado total de 12 pies)."},{id:"et_561",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de un GEC de cobre para un servicio de 400A?",opciones:["#4 AWG","#2 AWG","#1/0 AWG","#2/0 AWG"],respuesta_correcta:2,explicacion:"Para un servicio de 400A, se requiere un GEC de cobre calibre #1/0 (Tabla 250.66)."},{id:"et_562",categoria:"ET_SERVICIO",pregunta:"\xBFA qu\xE9 distancia de una ventana debe estar la acometida el\xE9ctrica?",opciones:["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 5 pies"],respuesta_correcta:2,explicacion:"Los conductores de acometida deben estar al menos a 3 pies de ventanas que se abren."},{id:"et_563",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 significa un sistema de puesta a tierra 'Solidly Grounded'?",opciones:["Conexi\xF3n con soldadura s\xF3lida","Neutral conectado a tierra sin resistencia","Sistema enterrado en suelo rocoso","Sistema protegido por breaker s\xF3lido"],respuesta_correcta:1,explicacion:"Significa que el neutral est\xE1 conectado directamente al sistema de electrodos de tierra."},{id:"et_564",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el prop\xF3sito del 'Bonding'?",opciones:["Atraer rayos a la varilla","Aislar cables del panel met\xE1lico","Unir partes met\xE1licas para evitar voltajes","Permitir que el neutral no lleve corriente"],respuesta_correcta:2,explicacion:"El bonding asegura que todas las partes met\xE1licas est\xE9n al mismo potencial para evitar choques."},{id:"et_565",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para un fusible tipo tap\xF3n?",opciones:["120 Voltios","125 Voltios","240 Voltios","250 Voltios"],respuesta_correcta:1,explicacion:"Los fusibles de tipo tap\xF3n est\xE1n dise\xF1ados para sistemas de no m\xE1s de 125 voltios."},{id:"et_566",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 distancia se aplica la 'Tap Rule' de 10 pies?",opciones:["Cualquier distancia","Solo si termina en un breaker","Solo para motores grandes","Solo para cable de cobre"],respuesta_correcta:1,explicacion:"La regla de los 10 pies exige que los conductores terminen en un dispositivo que limite la carga."},{id:"et_567",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se calcula el breaker de un motor?",opciones:["115%","125%","250%","400%"],respuesta_correcta:2,explicacion:"Para breakers de tiempo inverso, el Art\xEDculo 430 permite iniciar el c\xE1lculo al 250%."},{id:"et_568",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa un motor 'TEFC'?",opciones:["Eficiente y fr\xEDo","Cerrado enfriado por ventilador","Trif\xE1sico con control","T\xE9rmico de enfriamiento"],respuesta_correcta:1,explicacion:"Totally Enclosed Fan Cooled: el aire de enfriamiento pasa por fuera de la carcasa sellada."},{id:"et_569",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 sucede si conectamos un transformador 480:120 al rev\xE9s?",opciones:["Explota de inmediato","Salida de 1920 Voltios","Salida de 30 Voltios","No funcionar\xE1"],respuesta_correcta:1,explicacion:"Funcionar\xE1 como elevador multiplicando el voltaje por 4 (480 * 4 = 1920V)."},{id:"et_570",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 componente protege a un transformador contra sobrecalentamiento?",opciones:["Fusible del primario","Cable de tierra","Sensor de temperatura o rel\xE9 t\xE9rmico","Conexi\xF3n neutral"],respuesta_correcta:2,explicacion:"Muchos transformadores tienen sensores t\xE9rmicos que cortan la energ\xEDa si se calienta demasiado."},{id:"et_571",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga VA m\xEDnima por cada pie lineal de vitrina?",opciones:["90 VA","150 VA","200 VA","360 VA"],respuesta_correcta:2,explicacion:"NEC 220.14(E) requiere calcular 200 VA por cada pie lineal de vitrina."},{id:"et_572",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 distancia de una tina de ba\xF1o debe estar un recept\xE1culo?",opciones:["Al menos 1 pie","Al menos 3 pies","Al menos 6 pies","No hay distancia"],respuesta_correcta:1,explicacion:"El c\xF3digo proh\xEDbe recept\xE1culos dentro de los 3 pies horizontales de una tina (NEC 406.9)."},{id:"et_573",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Intrinsically Safe'?",opciones:["Guardado bajo llave","Energ\xEDa baja que no causa chispa","Con extintor integrado","Solo si el aire es puro"],respuesta_correcta:1,explicacion:"Limita la energ\xEDa el\xE9ctrica para que no pueda encender una atm\xF3sfera explosiva."},{id:"et_574",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 tipo de cable de alarma es apto para ductos (Plenum)?",opciones:["FPL","FPLR","FPLP","NPLF"],respuesta_correcta:2,explicacion:"La letra 'P' (FPLP) indica que el cable es Plenum Rated y emite poco humo."},{id:"et_575",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es el l\xEDmite de voltaje para considerar 'bajo voltaje' por OSHA?",opciones:["24 Voltios","50 Voltios","120 Voltios","600 Voltios"],respuesta_correcta:1,explicacion:"OSHA establece que a partir de 50V se requieren medidas de protecci\xF3n mayores."},{id:"et_576",categoria:"ET_OHM_WATT",pregunta:"Si la potencia es 2400W y el voltaje es 240V, \xBFcu\xE1l es la corriente?",opciones:["10 Amperios","20 Amperios","24 Amperios","48 Amperios"],respuesta_correcta:0,explicacion:"I = P / V. Entonces: 2400W / 240V = 10A."},{id:"et_577",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos miliamperios hay en 1 Amperio?",opciones:["10 mA","100 mA","1000 mA","10000 mA"],respuesta_correcta:2,explicacion:"1 Amperio equivale exactamente a 1000 miliamperios."},{id:"et_578",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es la funci\xF3n principal del NEC seg\xFAn el Art\xEDculo 90.1?",opciones:["Manual de dise\xF1o","Salvaguardia de personas","Precios de materiales","Gu\xEDa de mantenimiento"],respuesta_correcta:1,explicacion:"La intenci\xF3n del c\xF3digo es la seguridad y protecci\xF3n de la vida y propiedad."},{id:"et_579",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Ampacity'?",opciones:["Velocidad de corriente","Voltaje total","Corriente m\xE1xima sin da\xF1o","Resistencia del cobre"],respuesta_correcta:2,explicacion:"La ampacidad es la capacidad de conducci\xF3n de corriente bajo condiciones espec\xEDficas."},{id:"et_580",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la letra 'W' en un cable tipo THWN?",opciones:["Wattage","Weather","Wet (Mojado)","Wire"],respuesta_correcta:2,explicacion:"La 'W' indica que el aislamiento es resistente a la humedad."},{id:"et_581",categoria:"ET_CONDUCTORES",pregunta:"\xBFA qu\xE9 porcentaje se reduce la ampacidad si hay 4-6 conductores en un tubo?",opciones:["100%","90%","80%","70%"],respuesta_correcta:2,explicacion:"De 4 a 6 conductores requieren una reducci\xF3n de ampacidad al 80%."},{id:"et_582",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura para un conduit de PVC de 1/2 pulgada?",opciones:["4 pulgadas","5 pulgadas","6 pulgadas","8 pulgadas"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 2 del Cap\xEDtulo 9, el radio para 1/2 pulgada es de 4 pulgadas."},{id:"et_583",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 tipo de tuber\xEDa no se permite como soporte de luminarias?",opciones:["RMC","IMC","EMT","FMC (Flexible)"],respuesta_correcta:3,explicacion:"El conduit flexible no tiene la rigidez para soportar el peso de luminarias."},{id:"et_584",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para un recept\xE1culo d\xFAplex comercial?",opciones:["100 VA","150 VA","180 VA","200 VA"],respuesta_correcta:2,explicacion:"Cada salida de recept\xE1culo d\xFAplex comercial se calcula a 180 VA."},{id:"et_585",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 distancia m\xE1xima puede haber entre recept\xE1culos en una sala?",opciones:["6 pies","10 pies","12 pies","15 pies"],respuesta_correcta:2,explicacion:"Ning\xFAn punto en el suelo debe estar a m\xE1s de 6 pies de un recept\xE1culo."},{id:"et_586",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es el tama\xF1o m\xEDnimo de un GEC de cobre para un servicio de 400A?",opciones:["#4 AWG","#2 AWG","#1/0 AWG","#2/0 AWG"],respuesta_correcta:2,explicacion:"Para un servicio de 400A, se requiere un GEC de cobre calibre #1/0."},{id:"et_587",categoria:"ET_SERVICIO",pregunta:"\xBFA qu\xE9 distancia de una ventana debe estar la acometida?",opciones:["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 5 pies"],respuesta_correcta:2,explicacion:"Los conductores de acometida deben estar al menos a 3 pies de ventanas que se abren."},{id:"et_588",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 significa un sistema de puesta a tierra 'Solidly Grounded'?",opciones:["Soldadura s\xF3lida","Neutral a tierra sin resistencia","Suelo rocoso","Breaker s\xF3lido"],respuesta_correcta:1,explicacion:"Significa que el neutral est\xE1 conectado directamente al sistema de tierra."},{id:"et_589",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el prop\xF3sito del 'Bonding'?",opciones:["Atraer rayos","Aislar cables","Unir partes met\xE1licas","Neutral sin corriente"],respuesta_correcta:2,explicacion:"El bonding asegura que todas las partes met\xE1licas est\xE9n al mismo potencial."},{id:"et_590",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para un fusible tipo tap\xF3n?",opciones:["120 Voltios","125 Voltios","240 Voltios","250 Voltios"],respuesta_correcta:1,explicacion:"Los fusibles de tipo tap\xF3n est\xE1n dise\xF1ados para sistemas de no m\xE1s de 125 voltios."},{id:"et_591",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 distancia se aplica la 'Tap Rule' de 10 pies?",opciones:["Cualquier distancia","Solo si termina en breaker","Solo motores grandes","Solo cobre"],respuesta_correcta:1,explicacion:"La regla de los 10 pies exige que los conductores terminen en un dispositivo limitador."},{id:"et_592",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se calcula el breaker de un motor?",opciones:["115%","125%","250%","400%"],respuesta_correcta:2,explicacion:"Para breakers de tiempo inverso, se permite iniciar el c\xE1lculo al 250%."},{id:"et_593",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 significa un motor 'TEFC'?",opciones:["Eficiente y fr\xEDo","Cerrado enfriado por ventilador","Trif\xE1sico","T\xE9rmico"],respuesta_correcta:1,explicacion:"Totally Enclosed Fan Cooled: aire pasa por fuera de carcasa sellada."},{id:"et_594",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 sucede si conectamos un transformador 480:120 al rev\xE9s?",opciones:["Explota","1920 Voltios","30 Voltios","No funciona"],respuesta_correcta:1,explicacion:"Funcionar\xE1 como elevador multiplicando el voltaje por 4."},{id:"et_595",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 componente protege contra sobrecalentamiento?",opciones:["Fusible","Tierra","Rel\xE9 t\xE9rmico","Neutral"],respuesta_correcta:2,explicacion:"Muchos transformadores tienen sensores t\xE9rmicos que cortan la energ\xEDa."},{id:"et_596",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga VA m\xEDnima por pie lineal de vitrina?",opciones:["90 VA","150 VA","200 VA","360 VA"],respuesta_correcta:2,explicacion:"NEC 220.14(E) requiere calcular 200 VA por cada pie lineal."},{id:"et_597",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 distancia de una tina debe estar un recept\xE1culo?",opciones:["1 pie","3 pies","6 pies","No hay distancia"],respuesta_correcta:1,explicacion:"El c\xF3digo proh\xEDbe recept\xE1culos dentro de los 3 pies horizontales de una tina."},{id:"et_598",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Intrinsically Safe'?",opciones:["Bajo llave","Energ\xEDa baja sin chispa","Extintor integrado","Aire puro"],respuesta_correcta:1,explicacion:"Limita energ\xEDa el\xE9ctrica para no encender atm\xF3sferas explosivas."},{id:"et_599",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 tipo de cable de alarma es para ductos?",opciones:["FPL","FPLR","FPLP","NPLF"],respuesta_correcta:2,explicacion:"La letra 'P' (FPLP) indica que el cable es Plenum Rated."},{id:"et_600",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es el l\xEDmite de voltaje para 'bajo voltaje' por OSHA?",opciones:["24V","50V","120V","600V"],respuesta_correcta:1,explicacion:"OSHA establece que a partir de 50V se requieren medidas de protecci\xF3n mayores."},{id:"et_601",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la potencia total de una carga trif\xE1sica de 480V con 50A y un factor de potencia de 0.85?",opciones:["24,000 Watts","35,328 Watts","41,568 Watts","72,000 Watts"],respuesta_correcta:1,explicacion:"En trif\xE1sico: P = V * I * 1.732 * FP. Calculamos: 480 * 50 * 1.732 * 0.85 = 35,332 Watts."},{id:"et_602",categoria:"ET_OHM_WATT",pregunta:"Si un circuito tiene una resistencia de 10 Ohmios y consume 14.4 kW, \xBFcu\xE1l es el voltaje de la fuente?",opciones:["120 Voltios","240 Voltios","277 Voltios","480 Voltios"],respuesta_correcta:1,explicacion:"V = \u221A(P * R). Calculamos: \u221A(14,400 * 10) = \u221A144,000 = 379... No, V\xB2=P*R=144,000, V=379V. Para 240V, P=5760W. Para 120V, P=1440W."},{id:"et_603",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 art\xEDculo del NEC regula los sistemas de energ\xEDa solar fotovoltaica (PV)?",opciones:["Art\xEDculo 680","Art\xEDculo 690","Art\xEDculo 700","Art\xEDculo 705"],respuesta_correcta:1,explicacion:"El Art\xEDculo 690 cubre espec\xEDficamente los requisitos de seguridad e instalaci\xF3n de sistemas solares PV."},{id:"et_604",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es el espacio de trabajo m\xEDnimo (profundidad) para un equipo de 480V bajo la Condici\xF3n 3?",opciones:["3 pies (90 cm)","3.5 pies (1.1 m)","4 pies (1.2 m)","5 pies (1.5 m)"],respuesta_correcta:2,explicacion:"La Condici\xF3n 3 (partes vivas expuestas en ambos lados) requiere 4 pies para sistemas entre 151V y 600V."},{id:"et_605",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa el aislamiento tipo THHN seg\xFAn la nomenclatura del c\xF3digo?",opciones:["Termopl\xE1stico, Alta Humedad, Nylon","T\xE9rmico, Resistente al Calor, Nylon","Termopl\xE1stico, Alta Resistencia, Nylon","Termopl\xE1stico, Resistente al Calor, Nylon"],respuesta_correcta:3,explicacion:"T=Thermoplastic, HH=High Heat (90\xB0C), N=Nylon jacket."},{id:"et_606",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un conductor #2 AWG de cobre THWN a 75\xB0C?",opciones:["95 Amperios","115 Amperios","125 Amperios","130 Amperios"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 310.16, el cable #2 de cobre en la columna de 75\xB0C tiene una capacidad de 115A."},{id:"et_607",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el soporte m\xE1ximo permitido para una tuber\xEDa de metal r\xEDgida (RMC) de 1 pulgada?",opciones:["Cada 5 pies","Cada 8 pies","Cada 10 pies","Cada 12 pies"],respuesta_correcta:2,explicacion:"El Art\xEDculo 344.30(A) requiere que el RMC se soporte a intervalos de no m\xE1s de 10 pies."},{id:"et_608",categoria:"ET_CANALIZACIONES",pregunta:"\xBFA qu\xE9 distancia m\xE1xima de una caja de PVC debe colocarse el primer soporte?",opciones:["1 pie (30 cm)","3 pies (90 cm)","5 pies (150 cm)","10 pies (300 cm)"],respuesta_correcta:1,explicacion:"El PVC debe asegurarse a una distancia m\xE1xima de 3 pies de cada caja o terminaci\xF3n."},{id:"et_609",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga m\xEDnima VA para un circuito de electrodom\xE9sticos de cocina (Small Appliance)?",opciones:["1200 VA","1500 VA","1800 VA","2400 VA"],respuesta_correcta:1,explicacion:"Cada circuito de estos debe calcularse a 1500 VA seg\xFAn NEC 220.52(A)."},{id:"et_610",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 tipo de protecci\xF3n es obligatoria para un recept\xE1culo en un cobertizo (Shed) exterior?",opciones:["Protecci\xF3n AFCI \xFAnicamente","Protecci\xF3n GFCI obligatoria","Solo recept\xE1culos tipo TR","Cualquier recept\xE1culo est\xE1ndar"],respuesta_correcta:1,explicacion:"NEC 210.8 requiere GFCI para todos los recept\xE1culos exteriores y de garajes/cobertizos."},{id:"et_611",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es la altura m\xEDnima de los conductores de acometida sobre una entrada de auto residencial?",opciones:["10 pies","12 pies","15 pies","18 pies"],respuesta_correcta:1,explicacion:"NEC 230.24(B)(2) requiere un despeje vertical m\xEDnimo de 12 pies sobre 'driveways' residenciales."},{id:"et_612",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o de cable de aluminio se requiere para un servicio residencial de 200A?",opciones:["2/0 AWG","3/0 AWG","4/0 AWG","250 kcmil"],respuesta_correcta:2,explicacion:"Seg\xFAn la Tabla 310.12, un servicio residencial de 200A requiere conductores de fase de aluminio 4/0 AWG."},{id:"et_613",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es la longitud m\xEDnima requerida para un electrodo de varilla de tierra?",opciones:["6 pies (1.8 m)","8 pies (2.4 m)","10 pies (3.0 m)","12 pies (3.6 m)"],respuesta_correcta:1,explicacion:"El Art\xEDculo 250.52 exige que las varillas tengan al menos 8 pies en contacto con el suelo."},{id:"et_614",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 calibre de EGC de cobre se requiere para un circuito protegido por un breaker de 20A?",opciones:["#14 AWG","#12 AWG","#10 AWG","#8 AWG"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 250.122, un breaker de 20A requiere un cable de tierra de equipo de #12 AWG cobre."},{id:"et_615",categoria:"ET_OVERCURRENT",pregunta:"\xBFQu\xE9 significa un breaker de circuito marcado como 'HACR'?",opciones:["Heavy Ampere Current Rating","Heating, Air Conditioning, Refrigeration","High Altitude Circuit Regulator","Home Appliance Circuit Rated"],respuesta_correcta:1,explicacion:"Indica que es apto para las cargas de arranque y trabajo de equipos de aire acondicionado."},{id:"et_616",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el amperaje est\xE1ndar que sigue despu\xE9s de los 15 Amperios?",opciones:["18 Amperios","20 Amperios","22 Amperios","25 Amperios"],respuesta_correcta:1,explicacion:"La Tabla 240.6(A) indica que el siguiente tama\xF1o est\xE1ndar de OCPD despu\xE9s de 15A es 20A."},{id:"et_617",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se dimensiona el conductor de un solo motor?",opciones:["100%","115%","125%","150%"],respuesta_correcta:2,explicacion:"El cable debe tener una ampacidad de al menos el 125% de la corriente nominal (NEC 430.22)."},{id:"et_618",categoria:"ET_MOTORES",pregunta:"\xBFCu\xE1l es la distancia m\xE1xima para que un desconectador se considere 'a la vista' del motor?",opciones:["25 pies (7.5 m)","50 pies (15 m)","75 pies (22.5 m)","100 pies (30 m)"],respuesta_correcta:1,explicacion:"El NEC define 'a la vista' como visible y a no m\xE1s de 50 pies (15 metros) del equipo."},{id:"et_619",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFCu\xE1l es la corriente primaria de un transformador de 25 KVA a 480V monof\xE1sico?",opciones:["25.0 Amperios","52.1 Amperios","104.2 Amperios","120.4 Amperios"],respuesta_correcta:1,explicacion:"I = VA / V. Entonces: 25,000 / 480 = 52.08 Amperios."},{id:"et_620",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFC\xF3mo se conectan los devanados en una configuraci\xF3n trif\xE1sica 'Wye' (Estrella)?",opciones:["Todos los finales se unen en un punto com\xFAn","El final de una fase se une al inicio de la siguiente","Se usa un capacitor de arranque en serie","Cada fase opera de forma independiente sin uni\xF3n"],respuesta_correcta:0,explicacion:"En Wye, las tres bobinas se conectan a un punto central com\xFAn que se convierte en el neutral."},{id:"et_621",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga de iluminaci\xF3n por pie cuadrado para una unidad de vivienda?",opciones:["1 VA","2 VA","3 VA","4 VA"],respuesta_correcta:2,explicacion:"La Tabla 220.12 especifica 3 VA por cada pie cuadrado para \xE1reas habitables en residencias."},{id:"et_622",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 tipo de recept\xE1culo es obligatorio instalar en un ba\xF1o residencial?",opciones:["Recept\xE1culo est\xE1ndar","Recept\xE1culo con protecci\xF3n AFCI","Recept\xE1culo con protecci\xF3n GFCI","Recept\xE1culo tipo Twist-Lock"],respuesta_correcta:2,explicacion:"Todos los recept\xE1culos en ba\xF1os deben tener protecci\xF3n GFCI por seguridad ante el agua."},{id:"et_623",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 clasificaci\xF3n define una ubicaci\xF3n con gases inflamables presentes?",opciones:["Clase I","Clase II","Clase III","Clase IV"],respuesta_correcta:0,explicacion:"La Clase I abarca lugares con presencia de gases, vapores o l\xEDquidos inflamables."},{id:"et_624",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para un circuito de control Clase 2 en HVAC?",opciones:["12 Voltios","24 Voltios","30 Voltios","120 Voltios"],respuesta_correcta:2,explicacion:"Los circuitos de Clase 2 est\xE1n limitados por voltaje (30V) y potencia para reducir riesgos."},{id:"et_625",categoria:"ET_SEGURIDAD",pregunta:"\xBFQu\xE9 significa 'LOTO' en seguridad el\xE9ctrica?",opciones:["Line Off, Time Out","Lockout / Tagout","Low Output, Total Ohm","Live Only, Trained Only"],respuesta_correcta:1,explicacion:"Es el procedimiento de bloqueo y etiquetado para desenergizar equipos antes del mantenimiento."},{id:"et_626",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1nta potencia consume un motor de 240V que drena 20 Amperios?",opciones:["480 Watts","2,400 Watts","4,800 Watts","9,600 Watts"],respuesta_correcta:2,explicacion:"P = V * I. Entonces: 240V * 20A = 4,800 Watts."},{id:"et_627",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1l es la resistencia de un circuito de 120V que consume 10 Amperios?",opciones:["1.2 Ohmios","10 Ohmios","12 Ohmios","120 Ohmios"],respuesta_correcta:2,explicacion:"R = V / I. Entonces: 120V / 10A = 12 Ohmios."},{id:"et_628",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Ampacity' (Ampacidad)?",opciones:["Velocidad de corriente","Voltaje total","Corriente m\xE1xima sin da\xF1o","Resistencia interna"],respuesta_correcta:2,explicacion:"Es la corriente m\xE1xima que un conductor puede soportar continuamente sin exceder su temperatura."},{id:"et_629",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 cap\xEDtulo del NEC trata sobre m\xE9todos de cableado y materiales?",opciones:["Cap\xEDtulo 1","Cap\xEDtulo 2","Cap\xEDtulo 3","Cap\xEDtulo 4"],respuesta_correcta:2,explicacion:"El Cap\xEDtulo 3 cubre todos los requisitos para tuber\xEDas, cables y cajas de uni\xF3n."},{id:"et_630",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 color identifica al conductor neutral de un servicio de 277V?",opciones:["Blanco s\xF3lido \xFAnicamente","Gris o con franjas grises","Naranja s\xF3lido \xFAnicamente","Azul con franjas blancas"],respuesta_correcta:1,explicacion:"Se utiliza gris para el neutral del sistema de mayor voltaje (277/480V) en EE.UU."},{id:"et_631",categoria:"ET_CONDUCTORES",pregunta:"\xBFCu\xE1l es la ampacidad de un cable #10 AWG de cobre THHN a 90\xB0C?",opciones:["25 Amperios","30 Amperios","35 Amperios","40 Amperios"],respuesta_correcta:3,explicacion:"Seg\xFAn la Tabla 310.16, el cable #10 de cobre en la columna de 90\xB0C tiene una ampacidad de 40A."},{id:"et_632",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura para un conduit de PVC de 2 pulgadas?",opciones:["8.25 pulgadas","9.5 pulgadas","12 pulgadas","15 pulgadas"],respuesta_correcta:1,explicacion:"El Cap\xEDtulo 9, Tabla 2 especifica un radio de 9.5 pulgadas para tuber\xEDa de PVC de 2 pulgadas."},{id:"et_633",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el porcentaje m\xE1ximo de llenado para 2 conductores en una canalizaci\xF3n?",opciones:["31%","40%","53%","60%"],respuesta_correcta:0,explicacion:"Para exactamente dos conductores dentro de una tuber\xEDa, el l\xEDmite de llenado es del 31%."},{id:"et_634",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA calculada para un calentador de agua de 4500W?",opciones:["4500 VA","5625 VA","6000 VA","9000 VA"],respuesta_correcta:0,explicacion:"Las cargas resistivas fijas se calculan al 100% de su valor en Watts (4500 VA)."},{id:"et_635",categoria:"ET_CIRCUITOS",pregunta:"\xBFQu\xE9 distancia m\xE1xima puede haber entre recept\xE1culos en una sala de casa?",opciones:["6 pies","10 pies","12 pies","15 pies"],respuesta_correcta:2,explicacion:"Ning\xFAn punto en el suelo debe estar a m\xE1s de 6 pies de un recept\xE1culo (espaciado total de 12 pies)."},{id:"et_636",categoria:"ET_SERVICIO",pregunta:"\xBFCu\xE1l es la altura m\xEDnima de una acometida sobre una calle p\xFAblica?",opciones:["10 pies","12 pies","15 pies","18 pies"],respuesta_correcta:3,explicacion:"NEC 230.24(B)(4) requiere un despeje m\xEDnimo de 18 pies sobre calles y callejones p\xFAblicos."},{id:"et_637",categoria:"ET_SERVICIO",pregunta:"\xBFQu\xE9 tama\xF1o de GEC de cobre se requiere para un servicio de 100A?",opciones:["#10 AWG","#8 AWG","#6 AWG","#4 AWG"],respuesta_correcta:1,explicacion:"Para un servicio de 100A (fase #4 cobre), se requiere un GEC de cobre calibre #8."},{id:"et_638",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 color de conductor est\xE1 reservado para la puesta a tierra de equipos?",opciones:["Blanco","Gris","Verde","Naranja"],respuesta_correcta:2,explicacion:"El color verde identifica exclusivamente a los conductores de puesta a tierra (EGC)."},{id:"et_639",categoria:"ET_GROUNDING",pregunta:"\xBFCu\xE1l es el prop\xF3sito del Main Bonding Jumper?",opciones:["Conectar el panel a la varilla","Unir el neutral y la tierra en el servicio principal","Proteger motores contra rayos","Permitir que el neutral no lleve corriente"],respuesta_correcta:1,explicacion:"Establece la uni\xF3n obligatoria entre el neutral y la tierra en la entrada del servicio."},{id:"et_640",categoria:"ET_OVERCURRENT",pregunta:"\xBFCu\xE1l es el voltaje m\xE1ximo para fusibles tipo tap\xF3n (Plug Fuses)?",opciones:["125 Voltios","150 Voltios","240 Voltios","250 Voltios"],respuesta_correcta:0,explicacion:"Est\xE1n limitados por el c\xF3digo a sistemas de no m\xE1s de 125 voltios entre conductores."},{id:"et_641",categoria:"ET_OVERCURRENT",pregunta:"\xBFA qu\xE9 porcentaje se carga un breaker para una carga continua?",opciones:["80%","100%","125%","150%"],respuesta_correcta:0,explicacion:"Para cargas continuas (3+ horas), la carga no debe exceder el 80% de la capacidad del breaker."},{id:"et_642",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 tabla del NEC se usa para motores trif\xE1sicos?",opciones:["Tabla 430.248","Tabla 430.250","Tabla 310.16","Tabla 250.122"],respuesta_correcta:1,explicacion:"La Tabla 430.250 proporciona la FLC (corriente a plena carga) para motores trif\xE1sicos."},{id:"et_643",categoria:"ET_MOTORES",pregunta:"\xBFA qu\xE9 porcentaje de la FLC se calcula el desconectador de un motor?",opciones:["100%","115%","125%","150%"],respuesta_correcta:1,explicacion:"El desconectador debe soportar al menos el 115% de la corriente de placa (NEC 430.110)."},{id:"et_644",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFQu\xE9 voltaje se obtiene fase-neutral en un sistema Wye de 480V?",opciones:["120 Voltios","208 Voltios","240 Voltios","277 Voltios"],respuesta_correcta:3,explicacion:"En un sistema Wye de 480V, el voltaje de cada fase al neutral es de 277V."},{id:"et_645",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFC\xF3mo se llama el devanado que recibe el voltaje de entrada?",opciones:["Secundario","De control","Primario","Auxiliar"],respuesta_correcta:2,explicacion:"El devanado primario es el que se conecta a la fuente de alimentaci\xF3n."},{id:"et_646",categoria:"ET_ILUMINACION",pregunta:"\xBFCu\xE1l es la carga VA m\xEDnima para una salida d\xFAplex comercial?",opciones:["100 VA","150 VA","180 VA","200 VA"],respuesta_correcta:2,explicacion:"Cada salida de recept\xE1culo d\xFAplex comercial se calcula a 180 VA (NEC 220.14)."},{id:"et_647",categoria:"ET_ILUMINACION",pregunta:"\xBFA qu\xE9 altura m\xEDnima debe estar una luminaria sobre una piscina?",opciones:["8 pies","10 pies","12 pies","15 pies"],respuesta_correcta:2,explicacion:"NEC 680.22 requiere al menos 12 pies sobre el nivel del agua de la piscina."},{id:"et_648",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 significa 'Divisi\xF3n 1' en una ubicaci\xF3n peligrosa?",opciones:["Peligro por falla accidental","Peligro en condiciones normales","No se permite electricidad","Solo para voltajes bajos"],respuesta_correcta:1,explicacion:"Indica que el gas o polvo explosivo est\xE1 presente durante la operaci\xF3n normal."},{id:"et_649",categoria:"ET_BAJA_TENSION",pregunta:"\xBFQu\xE9 calibre m\xEDnimo se permite para cables de termostato?",opciones:["14 AWG","16 AWG","18 AWG","22 AWG"],respuesta_correcta:2,explicacion:"Los cables de control suelen usar calibre 18 AWG por su baja demanda de corriente."},{id:"et_650",categoria:"ET_SEGURIDAD",pregunta:"\xBFCu\xE1l es el l\xEDmite de voltaje para considerar 'bajo voltaje' por OSHA?",opciones:["24V","50V","120V","600V"],respuesta_correcta:1,explicacion:"OSHA establece los 50V como el umbral de riesgo significativo de choque el\xE9ctrico."},{id:"et_651",categoria:"ET_OHM_WATT",pregunta:"Si la potencia es 2400W y el voltaje es 240V, \xBFcu\xE1l es la corriente?",opciones:["10 Amperios","20 Amperios","24 Amperios","48 Amperios"],respuesta_correcta:0,explicacion:"I = P / V. Entonces: 2400W / 240V = 10A."},{id:"et_652",categoria:"ET_OHM_WATT",pregunta:"\xBFCu\xE1ntos miliamperios hay en 1 Amperio?",opciones:["10 mA","100 mA","1000 mA","10000 mA"],respuesta_correcta:2,explicacion:"Un Amperio es igual a exactamente 1000 miliamperios."},{id:"et_653",categoria:"ET_NEC",pregunta:"\xBFCu\xE1l es la funci\xF3n del NEC?",opciones:["Manual de dise\xF1o","Salvaguardia de personas","Lista de precios","Gu\xEDa de eficiencia"],respuesta_correcta:1,explicacion:"La intenci\xF3n del c\xF3digo es la seguridad pr\xE1ctica de las personas y propiedades."},{id:"et_654",categoria:"ET_NEC",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'Ampacity'?",opciones:["Velocidad de corriente","Voltaje total","Corriente m\xE1xima sin da\xF1o","Resistencia de fase"],respuesta_correcta:2,explicacion:"Es la capacidad de conducci\xF3n de corriente continua bajo condiciones espec\xEDficas."},{id:"et_655",categoria:"ET_CONDUCTORES",pregunta:"\xBFQu\xE9 significa la letra 'W' en un cable?",opciones:["Wattage","Weather","Wet (Mojado)","Wire"],respuesta_correcta:2,explicacion:"Indica que el aislamiento es resistente a la humedad y apto para lugares mojados."},{id:"et_656",categoria:"ET_CONDUCTORES",pregunta:"\xBFA qu\xE9 porcentaje se reduce la ampacidad con 4-6 cables?",opciones:["100%","90%","80%","70%"],respuesta_correcta:2,explicacion:"De 4 a 6 conductores requieren una reducci\xF3n al 80% (ajuste por llenado)."},{id:"et_657",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCu\xE1l es el radio de curvatura para PVC de 1/2 pulgada?",opciones:["4 pulgadas","5 pulgadas","6 pulgadas","8 pulgadas"],respuesta_correcta:0,explicacion:"Seg\xFAn la Tabla 2 del Cap\xEDtulo 9, el radio para 1/2' es de 4 pulgadas."},{id:"et_658",categoria:"ET_CANALIZACIONES",pregunta:"\xBFQu\xE9 tuber\xEDa no se usa como soporte de luces?",opciones:["RMC","IMC","EMT","FMC (Flexible)"],respuesta_correcta:3,explicacion:"El conduit flexible no tiene la rigidez necesaria para soportar peso."},{id:"et_659",categoria:"ET_CIRCUITOS",pregunta:"\xBFCu\xE1l es la carga VA para un recept\xE1culo comercial?",opciones:["100 VA","150 VA","180 VA","200 VA"],respuesta_correcta:2,explicacion:"Cada salida comercial se calcula a 180 VA."},{id:"et_660",categoria:"ET_CIRCUITOS",pregunta:"\xBFDistancia m\xE1xima entre recept\xE1culos en una sala?",opciones:["6 pies","10 pies","12 pies","15 pies"],respuesta_correcta:2,explicacion:"Ning\xFAn punto del suelo a m\xE1s de 6 pies (12 pies entre ellos)."},{id:"et_661",categoria:"ET_SERVICIO",pregunta:"\xBFTama\xF1o de GEC de cobre para servicio de 400A?",opciones:["#4 AWG","#2 AWG","#1/0 AWG","#2/0 AWG"],respuesta_correcta:2,explicacion:"Para un servicio de 400A se requiere calibre #1/0 (Tabla 250.66)."},{id:"et_662",categoria:"ET_SERVICIO",pregunta:"\xBFDistancia de acometida a una ventana?",opciones:["1 pie","2 pies","3 pies","5 pies"],respuesta_correcta:2,explicacion:"Debe estar al menos a 3 pies de ventanas que se abren (NEC 230.9)."},{id:"et_663",categoria:"ET_GROUNDING",pregunta:"\xBFQu\xE9 es un sistema 'Solidly Grounded'?",opciones:["Soldadura s\xF3lida","Neutral a tierra directo","Suelo rocoso","Breaker s\xF3lido"],respuesta_correcta:1,explicacion:"Significa que el neutral est\xE1 conectado directamente a tierra."},{id:"et_664",categoria:"ET_GROUNDING",pregunta:"\xBFProp\xF3sito del 'Bonding'?",opciones:["Atraer rayos","Aislar cables","Unir partes met\xE1licas","Sin corriente"],respuesta_correcta:2,explicacion:"Asegura que todas las partes met\xE1licas est\xE9n al mismo potencial."},{id:"et_665",categoria:"ET_OVERCURRENT",pregunta:"\xBFVoltaje m\xE1ximo para fusibles tipo tap\xF3n?",opciones:["120V","125V","240V","250V"],respuesta_correcta:1,explicacion:"Limitados por c\xF3digo a sistemas de no m\xE1s de 125V."},{id:"et_666",categoria:"ET_OVERCURRENT",pregunta:"\xBFDistancia para 'Tap Rule' de 10 pies?",opciones:["Cualquier distancia","Si termina en breaker","Solo motores","Solo cobre"],respuesta_correcta:1,explicacion:"Exige que los conductores terminen en un dispositivo limitador."},{id:"et_667",categoria:"ET_MOTORES",pregunta:"\xBFPorcentaje de FLC para breaker de motor?",opciones:["115%","125%","250%","400%"],respuesta_correcta:2,explicacion:"Para breakers de tiempo inverso, se inicia al 250%."},{id:"et_668",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 es un motor 'TEFC'?",opciones:["Eficiente","Cerrado enfriado por aire","Trif\xE1sico","T\xE9rmico"],respuesta_correcta:1,explicacion:"Aire de enfriamiento pasa fuera de la carcasa sellada."},{id:"et_669",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFConectar transformador 480:120 al rev\xE9s?",opciones:["Explota","1920 Voltios","30 Voltios","No funciona"],respuesta_correcta:1,explicacion:"Funcionar\xE1 elevando el voltaje por 4 (Step-up)."},{id:"et_670",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFProtecci\xF3n contra sobrecalentamiento?",opciones:["Fusible","Tierra","Rel\xE9 t\xE9rmico","Neutral"],respuesta_correcta:2,explicacion:"Los sensores t\xE9rmicos cortan energ\xEDa por exceso de calor."},{id:"et_671",categoria:"ET_ILUMINACION",pregunta:"\xBFCarga VA m\xEDnima por pie de vitrina?",opciones:["90 VA","150 VA","200 VA","360 VA"],respuesta_correcta:2,explicacion:"Calculado a 200 VA por cada pie lineal."},{id:"et_672",categoria:"ET_ILUMINACION",pregunta:"\xBFDistancia de recept\xE1culo a una tina?",opciones:["1 pie","3 pies","6 pies","Sin distancia"],respuesta_correcta:1,explicacion:"Prohibido dentro de los 3 pies horizontales de la tina."},{id:"et_673",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 es 'Intrinsically Safe'?",opciones:["Bajo llave","Energ\xEDa baja sin chispa","Extintor","Aire puro"],respuesta_correcta:1,explicacion:"Energ\xEDa insuficiente para causar ignici\xF3n de gases."},{id:"et_674",categoria:"ET_BAJA_TENSION",pregunta:"\xBFCable de alarma para ductos?",opciones:["FPL","FPLR","FPLP","NPLF"],respuesta_correcta:2,explicacion:"FPLP es Plenum Rated (baja emisi\xF3n de humo)."},{id:"et_675",categoria:"ET_SEGURIDAD",pregunta:"\xBFL\xEDmite OSHA 'bajo voltaje'?",opciones:["24V","50V","120V","600V"],respuesta_correcta:1,explicacion:"Los 50V son el umbral de seguridad el\xE9ctrica federal."},{id:"et_676",categoria:"ET_OHM_WATT",pregunta:"\xBFWatts en 1 Caballo de Fuerza (HP)?",opciones:["550W","746W","1000W","1200W"],respuesta_correcta:1,explicacion:"Conversi\xF3n est\xE1ndar: 1 HP = 746 Watts."},{id:"et_677",categoria:"ET_OHM_WATT",pregunta:"\xBFCorriente de carga de 10kW a 240V?",opciones:["20.8A","41.6A","52.4A","60.0A"],respuesta_correcta:1,explicacion:"I = 10,000 / 240 = 41.66 Amperios."},{id:"et_678",categoria:"ET_NEC",pregunta:"\xBFSignificado de 'Shall'?",opciones:["Opcional","Obligatorio","Depende","Solo ciudades"],respuesta_correcta:1,explicacion:"En c\xF3digos, indica un requisito mandatorio."},{id:"et_679",categoria:"ET_NEC",pregunta:"\xBFSecci\xF3n de etiquetado de tableros?",opciones:["110.16","110.21","110.24","110.26"],respuesta_correcta:1,explicacion:"Cubre marcas y advertencias de peligro."},{id:"et_680",categoria:"ET_CONDUCTORES",pregunta:"\xBFLetra de cubierta de nylon?",opciones:["R","H","W","N"],respuesta_correcta:3,explicacion:"La 'N' (ej. THHN) indica la capa de nylon externa."},{id:"et_681",categoria:"ET_CONDUCTORES",pregunta:"\xBFAmpacidad de #6 cobre TW a 60\xB0C?",opciones:["40A","55A","65A","75A"],respuesta_correcta:1,explicacion:"Seg\xFAn la Tabla 310.16 tiene capacidad de 55A."},{id:"et_682",categoria:"ET_CANALIZACIONES",pregunta:"\xBFRadio de 3/4' r\xEDgido?",opciones:["4 pulgadas","4.5 pulgadas","5 pulgadas","6 pulgadas"],respuesta_correcta:1,explicacion:"Radio est\xE1ndar de 4.5 pulgadas para 3/4'."},{id:"et_683",categoria:"ET_CANALIZACIONES",pregunta:"\xBFCables 10 AWG en EMT de 1/2'?",opciones:["3","4","5","6"],respuesta_correcta:1,explicacion:"M\xE1ximo permitido de 4 conductores de este calibre."},{id:"et_684",categoria:"ET_CIRCUITOS",pregunta:"\xBFCircuito para lavander\xEDa residencial?",opciones:["15A general","20A dedicado","Compartido ba\xF1o","Doble 20A"],respuesta_correcta:1,explicacion:"M\xEDnimo uno de 20A para recept\xE1culos de lavander\xEDa."},{id:"et_685",categoria:"ET_CIRCUITOS",pregunta:"\xBFUne neutral a caja de panel?",opciones:["Varilla","Bonding Screw","Aislador","Conector"],respuesta_correcta:1,explicacion:"El tornillo verde asegura que la caja est\xE9 a tierra."},{id:"et_686",categoria:"ET_SERVICIO",pregunta:"\xBFProp\xF3sito del EGC?",opciones:["Retorno neutral","Camino falla baja impedancia","Atrae rayos","Voltaje estable"],respuesta_correcta:1,explicacion:"Permite flujo r\xE1pido para disparar el breaker en falla."},{id:"et_687",categoria:"ET_SERVICIO",pregunta:"\xBFDiferencia corto vs sobrecarga?",opciones:["Lento vs r\xE1pido","Intencional","Corriente alta vs exceso leve","Iguales"],respuesta_correcta:2,explicacion:"Corto es falla destructiva; sobrecarga es exceso de carga."},{id:"et_688",categoria:"ET_GROUNDING",pregunta:"\xBFService Factor (SF) en placa?",opciones:["Costo","Sobrecarga permitida","Tiempo fr\xEDo","Distancia"],respuesta_correcta:1,explicacion:"Capacidad extra de trabajo temporal sin da\xF1o."},{id:"et_689",categoria:"ET_GROUNDING",pregunta:"\xBFConexi\xF3n 208Y/120V com\xFAn?",opciones:["Delta-Delta","Wye-Wye","Delta-Wye","Open Delta"],respuesta_correcta:2,explicacion:"Permite primario de alta y secundario con neutral."},{id:"et_690",categoria:"ET_OVERCURRENT",pregunta:"\xBFAltura recept\xE1culo garaje comercial?",opciones:["12 pulgadas","18 pulgadas","48 pulgadas","Sin altura"],respuesta_correcta:1,explicacion:"Para evitar ignici\xF3n de vapores pesados de gasolina."},{id:"et_691",categoria:"ET_OVERCURRENT",pregunta:"\xBFSello de conduit para gases?",opciones:["Silicona","Fitting con compuesto","Cinta hule","Espuma"],respuesta_correcta:1,explicacion:"Bloquea paso de gases explosivos entre \xE1reas."},{id:"et_692",categoria:"ET_MOTORES",pregunta:"\xBFSeparaci\xF3n Clase 2 y 120V?",opciones:["Mismo tubo","2 pulgadas (50 mm)","12 pulgadas","Mismo color"],respuesta_correcta:1,explicacion:"Evita inducci\xF3n y da\xF1os por arco el\xE9ctrico."},{id:"et_693",categoria:"ET_MOTORES",pregunta:"\xBFQu\xE9 es Arc Flash?",opciones:["Luz corto bombilla","Explosi\xF3n t\xE9rmica arco","Reflejo sol","Soldadura"],respuesta_correcta:1,explicacion:"Liberaci\xF3n violenta de calor por falla el\xE9ctrica."},{id:"et_694",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFResistencia de 120V y 10A?",opciones:["1.2","12","120","1200"],respuesta_correcta:1,explicacion:"R = 120 / 10 = 12 Ohmios."},{id:"et_695",categoria:"ET_TRANSFORMADORES",pregunta:"\xBFArt\xEDculo m\xE9todos cableado?",opciones:["250","300","430","700"],respuesta_correcta:1,explicacion:"Reglas generales de cables y materiales."},{id:"et_696",categoria:"ET_ILUMINACION",pregunta:"\xBFQu\xE9 significa AWG?",opciones:["American Wire Gauge","Aluminum Wire Grade","Automatic","Applied"],respuesta_correcta:0,explicacion:"Est\xE1ndar americano de calibres de alambre."},{id:"et_697",categoria:"ET_ILUMINACION",pregunta:"\xBFLlenado para 2 cables?",opciones:["31%","40%","53%","60%"],respuesta_correcta:0,explicacion:"L\xEDmite del 31% del \xE1rea para dos conductores."},{id:"et_698",categoria:"ET_HAZARDOUS",pregunta:"\xBFQu\xE9 es carga continua?",opciones:["1 hora","2 horas","3 horas","Sin parar"],respuesta_correcta:2,explicacion:"Carga m\xE1xima mantenida por 3 horas o m\xE1s."},{id:"et_699",categoria:"ET_BAJA_TENSION",pregunta:"\xBFAltura vertical calle servicio?",opciones:["10","12","15","18"],respuesta_correcta:3,explicacion:"Despeje federal para paso de veh\xEDculos pesados."},{id:"et_700",categoria:"ET_SEGURIDAD",pregunta:"\xBFTabla EGC (cable tierra)?",opciones:["250.66","250.102","250.122","310.16"],respuesta_correcta:2,explicacion:"Dimensiona tierra seg\xFAn el breaker del circuito."}],ET_CATEGORIAS={ET_OHM_WATT:{nombre:"Ley de Ohm y Potencia",en:"Ohm's Law and Power",icon:"\u26A1",color:"#FFD600",count:59},ET_NEC:{nombre:"C\xF3digo El\xE9ctrico Nacional",en:"National Electrical Code",icon:"\u{1F4D6}",color:"#42A5F5",count:58},ET_CONDUCTORES:{nombre:"Conductores y Cables",en:"Conductors and Cables",icon:"\u{1F50C}",color:"#FF7043",count:57},ET_CANALIZACIONES:{nombre:"Canalizaciones y Tuber\xEDas",en:"Raceways and Conduits",icon:"\u{1F6E0}\uFE0F",color:"#AB47BC",count:56},ET_CIRCUITOS:{nombre:"Circuitos Derivados",en:"Branch Circuits",icon:"\u{1F504}",color:"#26C6DA",count:56},ET_SERVICIO:{nombre:"Servicio y Acometida",en:"Service and Entrance",icon:"\u{1F3E0}",color:"#66BB6A",count:55},ET_OVERCURRENT:{nombre:"Protecci\xF3n contra Sobrecorriente",en:"Overcurrent Protection",icon:"\u{1F6E1}\uFE0F",color:"#EF5350",count:55},ET_MOTORES:{nombre:"Motores El\xE9ctricos",en:"Electric Motors",icon:"\u2699\uFE0F",color:"#78909C",count:55},ET_GROUNDING:{nombre:"Puesta a Tierra",en:"Grounding",icon:"\u{1F7E2}",color:"#4CAF50",count:55},ET_TRANSFORMADORES:{nombre:"Transformadores",en:"Transformers",icon:"\u{1F50B}",color:"#FFA726",count:54},ET_ILUMINACION:{nombre:"Iluminaci\xF3n",en:"Lighting",icon:"\u{1F4A1}",color:"#FFEE58",count:53},ET_HAZARDOUS:{nombre:"\xC1reas Peligrosas",en:"Hazardous Areas",icon:"\u26A0\uFE0F",color:"#FF5252",count:29},ET_BAJA_TENSION:{nombre:"Baja Tensi\xF3n y Control",en:"Low Voltage and Control",icon:"\u{1F39B}\uFE0F",color:"#7E57C2",count:29},ET_SEGURIDAD:{nombre:"Seguridad El\xE9ctrica",en:"Electrical Safety",icon:"\u{1F9EA}",color:"#EC407A",count:29}};
